        self.phi_state_owner_by_sid_v35 = {}
        self.phi_state_family_events_v35 = []
        self.phi_state_family_warnings_v35 = []
        self.phi_state_family_failures_v35 = []
        self.phi_state_family_audit_v35 = {}
