    def _promote_phi_dropin_post_update_aliases(self):
        """
        Promote executable PHI dropins whose source node is a real update of
        the target stack local.

        Canonical Sample Y case:
            phi_dropin:
                source_sid='v_367'
                target_name='local_14'
                target=local_14
                source_node=INT_ADD [local_14, 1] -> v_367

        This does not depend on var_map[v_367].  The proof is the PHI dropin
        plus source_node input dataflow.
        """

        if not hasattr(self, "phi_dropin_post_update_promotion_events"):
            self.phi_dropin_post_update_promotion_events = []

        for rec in list(getattr(self, "phi_dropins", []) or []):
            if not isinstance(rec, dict):
                continue

            source_sid = rec.get("source_sid")
            target = rec.get("target")
            target_name = rec.get("target_name") or self.name_for_var(target)
            source_node = rec.get("source_node")

            ok, reason = self._phi_dropin_source_is_target_update(rec)

            ev = {
                "kind": "phi_dropin_post_update_promotion",
                "source_sid": source_sid,
                "target_sid": rec.get("target_sid"),
                "target_name": target_name,
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "source_opcode": getattr(source_node, "opcode", None),
                "result": bool(ok),
                "reason": reason,
            }

            if not ok:
                self.phi_dropin_post_update_promotion_events.append(ev)
                continue

            source_expr = self._expr_for_phi_dropin_update_source(source_node, target_name)
            if not source_expr:
                try:
                    source_expr = self._expr_for_node_or_op(
                        source_node,
                        None,
                        self.block_of_semantic(source_node),
                    )
                except Exception:
                    source_expr = None

            if not source_expr:
                source_expr = rec.get("source_name") or str(source_sid)

            info = {
                "target_sid": rec.get("target_sid"),
                "target_name": target_name,
                "source_name": rec.get("source_name") or str(source_sid),
                "source_expr": source_expr,
                "source_opcode": getattr(source_node, "opcode", None),
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": "phi_dropin_source_is_stack_local_update",
                "policy": "render_source_sid_as_post_update_target_variable",
            }

            if source_sid is not None:
                self.post_update_alias_sids.add(source_sid)
                self.prefer_var_expr_sids.add(source_sid)
                self.post_update_aliases[source_sid] = info

                self.state_transition_alias_sids.add(source_sid)
                self.state_transition_aliases[source_sid] = dict(info)

                self.must_emit_state_write_sids.add(source_sid)
                self.state_write_info[source_sid] = {
                    "kind": "phi_dropin_post_update_state_write",
                    "target_sid": rec.get("target_sid"),
                    "target_name": target_name,
                    "pred_addr": rec.get("pred_addr"),
                    "block_addr": rec.get("pred_addr"),
                    "reason": "phi_dropin_source_is_stack_local_update",
                    "source_opcode": getattr(source_node, "opcode", None),
                    "source_expr": source_expr,
                }

            ev["source_expr"] = source_expr
            ev["promoted"] = True
            self.phi_dropin_post_update_promotion_events.append(ev)

    def _phi_dropin_source_is_target_update(self, rec):
        source_node = rec.get("source_node")
        target = rec.get("target")
        target_name = rec.get("target_name") or self.name_for_var(target)

        if source_node is None:
            return False, "missing_source_node"
        if target is None:
            return False, "missing_target"

        source_sid = rec.get("source_sid") or self.sid_of(source_node)
        if self._erase_emperor_is_derived_result_sid_v29(source_sid):
            return False, "erase_emperor_snapshot_derived_result_not_state_successor"

        if not self.is_stack_local(target):
            return False, "target_not_stack_local"
        if not target_name:
            return False, "missing_target_name"

        try:
            node = self._resolve_transparent_source_node_v20b(source_node)
        except Exception:
            node = source_node

        opcode = getattr(node, "opcode", None)

        if opcode in self.CALL_OPS or opcode in ("LOAD", "STORE", "INDIRECT", "MULTIEQUAL"):
            return False, "impure_or_phi_source:%s" % opcode

        if opcode not in self.PURE_INLINE_OPS:
            return False, "source_not_pure_inline:%s" % opcode

        if not self._node_inputs_reference_target_local(node, target, target_name):
            return False, "source_inputs_do_not_reference_target"

        if not self._node_has_update_component_excluding_target(node, target, target_name):
            return False, "source_has_no_update_component"

        return True, "pure_phi_source_updates_target_local"

    def _node_inputs_reference_target_local(self, node, target, target_name):
        for inp in list(getattr(node, "inputs", []) or []):
            try:
                if self.same_storage(inp, target):
                    return True
            except Exception:
                pass

            try:
                if self.name_for_var(self.to_var(inp)) == target_name:
                    return True
            except Exception:
                pass

        return False

    def _node_has_update_component_excluding_target(self, node, target, target_name):
        opcode = getattr(node, "opcode", None)
        inputs = list(getattr(node, "inputs", []) or [])

        if opcode in ("COPY", "CAST", "INT_ZEXT", "INT_SEXT", "TRUNC"):
            return False

        for inp in inputs:
            try:
                if self.same_storage(inp, target):
                    continue
            except Exception:
                pass

            try:
                if self.name_for_var(self.to_var(inp)) == target_name:
                    continue
            except Exception:
                pass

            if getattr(inp, "is_constant", False):
                val = None
                for attr in ("const_value", "value", "offset"):
                    val = getattr(inp, attr, None)
                    if val is not None:
                        break

                try:
                    if int(val) != 0:
                        return True
                except Exception:
                    return True
            else:
                return True

        return False

    def _expr_for_phi_dropin_update_source(self, node, target_name):
        opcode = getattr(node, "opcode", None)
        inputs = list(getattr(node, "inputs", []) or [])

        if not inputs:
            return None

        if len(inputs) == 1:
            opmap = {
                "INT_NEGATE": "~",
                "INT_2COMP": "-",
                "BOOL_NEGATE": "not ",
            }

            sym = opmap.get(opcode)
            if not sym:
                return None

            if self.is_stack_local(inputs[0]):
                a = target_name
            else:
                a = self._value_expr_for_metadata(inputs[0], seen=set())

            return "(%s%s)" % (sym, a)

        if len(inputs) != 2:
            return None

        symbols = {
            "INT_ADD": "+",
            "INT_SUB": "-",
            "INT_MULT": "*",
            "INT_DIV": "//",
            "INT_SDIV": "//",
            "INT_REM": "%",
            "INT_SREM": "%",
            "INT_AND": "&",
            "INT_OR": "|",
            "INT_XOR": "^",
            "INT_LEFT": "<<",
            "INT_RIGHT": ">>",
            "INT_SRIGHT": ">>",
        }

        sym = symbols.get(opcode)
        if not sym:
            return None

        a, b = inputs[0], inputs[1]

        if self.is_stack_local(a):
            left = target_name
        else:
            left = self._value_expr_for_metadata(a, seen=set())

        if self.is_stack_local(b):
            right = target_name
        else:
            right = self._value_expr_for_metadata(b, seen=set())

        return "(%s %s %s)" % (left, sym, right)




    # ---------------------------------------------------------
    # PHI node synthesis from PAL blocks
    # ---------------------------------------------------------

    def _synthesize_missing_phi_nodes_from_blocks(self):
        """
        Ensure every MULTIEQUAL op present in PAL block.ops is represented in
        self.phi_nodes.

        Some semantic graph builders expose stack-local PHIs in func.phi_nodes
        but leave temp PHIs only as raw block ops.  The emitter deliberately
        skips MULTIEQUAL instructions, so missing phi_nodes means missing
        executable assignments such as:

            v_5848 = v_2697 / v_2690

        This pass appends the raw MULTIEQUAL op object to phi_nodes when its
        output sid is not already represented.
        """

        existing = set()

        for phi in list(self.phi_nodes or []):
            sid = self.sid_of(getattr(phi, "output", None))
            if sid is not None:
                existing.add(sid)

        for block in getattr(self.func, "blocks", []) or []:
            for op in getattr(block, "ops", []) or []:
                if getattr(op, "opcode", None) != "MULTIEQUAL":
                    continue

                out = getattr(op, "output", None)
                sid = self.sid_of(out)

                if sid is None or sid in existing:
                    continue

                # Attach block metadata if the raw op does not carry it.
                try:
                    if getattr(op, "block", None) is None:
                        op.block = block
                except Exception:
                    pass

                try:
                    if getattr(op, "block_region", None) is None:
                        op.block_region = block
                except Exception:
                    pass

                self.phi_nodes.append(op)
                self.synthesized_phi_nodes.append(op)
                self.synthesized_phi_sids.add(sid)
                existing.add(sid)

    # ---------------------------------------------------------
    # Compatibility union-find
    # ---------------------------------------------------------

    def _init_sets(self):
        self.parent = {}
        for sid in self.nodes:
            self.parent[sid] = sid

        # Raw synthesized PHI ops may have output SIDs that are not yet keys in
        # formula_nodes.  Include them for compatibility naming metadata.
        for phi in self.phi_nodes:
            sid = self.sid_of(getattr(phi, "output", None))
            if sid is not None and sid not in self.parent:
                self.parent[sid] = sid

    def find(self, x):
        if x not in self.parent:
            return x
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        if a is None or b is None:
            return False
        if a not in self.parent or b not in self.parent:
            return False
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        self.parent[rb] = ra
        return True

    # ---------------------------------------------------------
    # Basic helpers
    # ---------------------------------------------------------

    def to_node(self, x):
        if x is None:
            return None
        if hasattr(x, "var") and hasattr(x, "opcode"):
            return x
        if isinstance(x, str):
            return self.nodes.get(x)
        sid = getattr(x, "ssa_id", None)
        if sid is not None:
            return self.nodes.get(sid)
        return None

    def to_var(self, x):
        if x is None:
            return None
        if hasattr(x, "var"):
            return x.var
        return x

    def sid_of(self, x):
        if x is None:
            return None
        if isinstance(x, str):
            return x
        if hasattr(x, "var"):
            return getattr(x.var, "ssa_id", None)
        return getattr(x, "ssa_id", None)

    def opcode_of(self, x):
        node = self.to_node(x)
        if node is None:
            return None
        return getattr(node, "opcode", None)

    def is_const(self, x):
        v = self.to_var(x)
        return bool(v is not None and getattr(v, "is_constant", False))

    def is_stack_local(self, x):
        v = self.to_var(x)
        if v is None:
            return False
        return bool(getattr(v, "is_stack", False) or getattr(v, "space", None) == "stack")

    def is_call_node(self, x):
        return self.opcode_of(x) in self.CALL_OPS

    def is_condition(self, x):
        node = self.to_node(x)
        var = self.to_var(x)

        if node is not None and getattr(node, "is_condition", False):
            return True
        if var is not None and getattr(var, "is_condition", False):
            return True

        sid = self.sid_of(x)
        for cv in self.condition_vars:
            if getattr(cv, "ssa_id", None) == sid:
                return True

        return False

    def is_return_value(self, x):
        node = self.to_node(x)
        var = self.to_var(x)

        if node is not None and getattr(node, "is_return_value", False):
            return True
        if var is not None and getattr(var, "is_return_value", False):
            return True

        sid = self.sid_of(x)
        for rv in self.return_vars:
            if getattr(rv, "ssa_id", None) == sid:
                return True

        return False

    def same_storage(self, a, b):
        """
        True only when two variables refer to the same concrete storage cell.

        Critical fix:
            Temp SSA variables such as v_5848, v_2697, and v_2690 often have
            no real storage address. The old implementation compared tuples
            containing only size metadata, so unrelated temps with the same
            size could be classified as "same storage". That made:

                MULTIEQUAL [v_2697, v_2690] -> v_5848

            look like an identity PHI and prevented PHI drop-ins.

        Policy:
            - same object or same SSA id: same
            - stack/register/global storage with concrete space+offset/address:
              compare concrete storage identity
            - pure temps without concrete storage: never same merely because
              their sizes match
        """

        av = self.to_var(a)
        bv = self.to_var(b)

        if av is None or bv is None:
            return False

        if av is bv:
            return True

        asid = getattr(av, "ssa_id", None)
        bsid = getattr(bv, "ssa_id", None)

        if asid is not None and asid == bsid:
            return True

        ak = self._storage_key(av)
        bk = self._storage_key(bv)

        if ak is None or bk is None:
            return False

        return ak == bk

    def _storage_key(self, v):
        """
        Return concrete storage identity for stack/register/global variables.

        Size alone is not storage identity. At least a space plus offset, or an
        address, is required.
        """

        if v is None:
            return None

        space = getattr(v, "space", None)
        offset = getattr(v, "offset", None)
        address = getattr(v, "address", None)
        size = getattr(v, "size", None)

        if address is not None:
            return ("addr", address, size)

        if space is not None and offset is not None:
            return ("space", space, offset, size)

        return None

    def block_of_semantic(self, x):
        """
        Resolve the PAL block where semantic object x is defined.

        v3 note:
            Some temp PHI sources/targets do not carry block metadata. For
            programmatic truth we must still map them to predecessor/join
            blocks. Therefore, after direct metadata checks, scan the PAL
            function's blocks for an op whose output has the requested SSA id.
        """

        node = self.to_node(x)

        if node is not None:
            block = getattr(node, "block", None)
            if block is not None:
                return block
            block = getattr(node, "block_region", None)
            if block is not None:
                return block
            var = self.to_var(node)
            block = getattr(var, "block_region", None)
            if block is not None:
                return block

        var = self.to_var(x)
        if var is not None:
            block = getattr(var, "block_region", None)
            if block is not None:
                return block

        # Last-resort scan by SSA output.
        sid = self.sid_of(x)
        if sid is not None:
            found = self.find_def_block_for_sid(sid)
            if found is not None:
                return found

        return None

    def find_def_block_for_sid(self, sid):
        """
        Find the PAL block containing the op that defines sid.
        """

        if sid is None:
            return None

        for block in getattr(self.func, "blocks", []) or []:
            for op in getattr(block, "ops", []) or []:
                out = getattr(op, "output", None)
                if out is not None and getattr(out, "ssa_id", None) == sid:
                    return block

        return None

    def find_phi_block_for_sid(self, sid):
        """
        Find the join block containing MULTIEQUAL output sid.
        """

        if sid is None:
            return None

        for block in getattr(self.func, "blocks", []) or []:
            for op in getattr(block, "ops", []) or []:
                if getattr(op, "opcode", None) != "MULTIEQUAL":
                    continue
                out = getattr(op, "output", None)
                if out is not None and getattr(out, "ssa_id", None) == sid:
                    return block

        return None

    def block_addr(self, block):
        if block is None:
            return None
        return getattr(block, "addr", None)

    def cfg_node_for_block(self, block):
        if self.cfg is None or block is None:
            return None

        addr = getattr(block, "addr", None)
        if addr is None:
            return None

        nodes = getattr(self.cfg, "nodes", {})
        if addr in nodes:
            return nodes[addr]

        get_node = getattr(self.cfg, "get_node", None)
        if callable(get_node):
            try:
                return get_node(addr)
            except Exception:
                return None

        return None

    def cfg_node_for_phi(self, phi):
        """
        Resolve the CFG join node for a PHI.

        v3 hardening:
            Temp PHIs such as v_5848 may not have reliable phi.block or
            output-node block metadata. We therefore scan PAL blocks for the
            MULTIEQUAL op whose output SSA id matches the PHI output.
        """

        block = getattr(phi, "block", None)
        reason = "phi.block"

        if block is None:
            block = getattr(phi, "block_region", None)
            reason = "phi.block_region"

        out = getattr(phi, "output", None)
        out_sid = self.sid_of(out)

        if block is None:
            out_node = self.to_node(out)
            if out_node is not None:
                block = getattr(out_node, "block", None)
                reason = "out_node.block"
                if block is None:
                    block = getattr(out_node, "block_region", None)
                    reason = "out_node.block_region"

        if block is None and out_sid is not None:
            block = self.find_phi_block_for_sid(out_sid)
            reason = "scan_multiequal_output"

        if block is None and out_sid is not None:
            block = self.find_def_block_for_sid(out_sid)
            reason = "scan_any_output"

        node = self.cfg_node_for_block(block)

        self.phi_join_discovery_events.append({
            "phi_sid": out_sid,
            "block_addr": getattr(block, "addr", None) if block is not None else None,
            "cfg_addr": getattr(node, "addr", None) if node is not None else None,
            "reason": reason if block is not None else "unresolved",
        })

        return node

    def pred_nodes_for_join(self, join_node):
        if join_node is None:
            return []

        preds = []
        for e in getattr(join_node, "in_edges", []):
            src = getattr(e, "src", None)
            if src is not None:
                preds.append(src)

        if preds:
            return preds

        try:
            return list(join_node.predecessors())
        except Exception:
            return []

    # ---------------------------------------------------------
    # Use-count / materialization
    # ---------------------------------------------------------

    def _compute_use_counts(self):
        self.use_counts = {}
        self.consumer_nodes_by_sid = {}
        self.condition_use_sids = set()
        self.return_use_sids = set()

        for node in self.nodes.values():
            for inp in getattr(node, "inputs", []) or []:
                sid = self.sid_of(inp)
                if sid is not None:
                    self.use_counts[sid] = self.use_counts.get(sid, 0) + 1
                    self.consumer_nodes_by_sid.setdefault(sid, []).append(node)

        for cv in self.condition_vars:
            sid = self.sid_of(cv)
            if sid is not None:
                self.use_counts[sid] = self.use_counts.get(sid, 0) + 1
                self.condition_use_sids.add(sid)

        for rv in self.return_vars:
            sid = self.sid_of(rv)
            if sid is not None:
                self.use_counts[sid] = self.use_counts.get(sid, 0) + 1
                self.return_use_sids.add(sid)

    def _mark_materialization_policy(self):
        for node in self.nodes.values():
            sid = self.sid_of(node)
            if sid is None:
                continue

            if getattr(node, "opcode", None) in self.CALL_OPS:
                if sid in self.phi_source_foldable_sids:
                    self.inline_only_sids.add(sid)
                    self.suppress_assign_sids.add(sid)
                    continue

                self.materialize_sids.add(sid)
                try:
                    node.no_inline = True
                    node.materialize = True
                    node.semantic_role = getattr(node, "semantic_role", None) or "call_result"
                    node.var.no_inline = True
                    node.var.materialize = True
                except Exception:
                    pass
                self.no_inline_nodes.append(node)

    def _protect_condition_dependency_materialization(self):
        """
        v19 bookkeeping: protect the dataflow ancestry of branch conditions.

        This is not presentation cleanup.  It prevents execution values such as
        feedback()/mutate() call results from being suppressed merely because a
        later condition can be syntactically expanded.

        Example:
            v_1736 = feedback(local_20, local_10)
            v_1043 = ((v_1736 ^ beta) % 3) == 0

        v_1736 is an executed call result.  It must be materialized before the
        condition, not inlined/recomputed and not omitted.
        """

        deps = self._compute_condition_dependency_sids()
        self.condition_dependency_sids = set(deps)

        for sid in sorted(deps, key=str):
            node = self.nodes.get(sid)
            opcode = getattr(node, "opcode", None) if node is not None else None

            if opcode in self.CALL_OPS:
                self.required_call_result_sids.add(sid)
                self.protected_condition_value_sids.add(sid)
                self.materialize_sids.add(sid)
                self.suppress_assign_sids.discard(sid)
                self.inline_only_sids.discard(sid)
                self.phi_source_foldable_sids.discard(sid)

                try:
                    node.no_inline = True
                    node.materialize = True
                    node.semantic_role = getattr(node, "semantic_role", None) or "condition_call_result"
                    node.var.no_inline = True
                    node.var.materialize = True
                except Exception:
                    pass

                self._set_ssa_policy(
                    sid,
                    "required_condition_call_result",
                    emit=True,
                    expr_mode="var",
                    reason="call result is data dependency of branch condition",
                    target_name=self.var_map.get(sid),
                )

            elif sid in self.materialize_sids:
                self.protected_condition_value_sids.add(sid)

    def _compute_condition_dependency_sids(self):
        roots = set()

        for cv in list(getattr(self, "condition_vars", []) or []):
            sid = self.sid_of(cv)
            if sid is not None:
                roots.add(sid)

        for sid, node in self.nodes.items():
            if node is not None and getattr(node, "is_condition", False):
                roots.add(sid)

        deps = set()
        stack = list(roots)

        while stack:
            sid = stack.pop()
            if sid is None or sid in deps:
                continue

            deps.add(sid)
            node = self.nodes.get(sid)
            if node is None:
                continue

            for inp in list(getattr(node, "inputs", []) or []):
                isid = self.sid_of(inp)
                if isid is not None and isid not in deps:
                    stack.append(isid)

        return deps

    def _precompute_used_temp_phi_outputs(self):
        """
        Compute value-selector temp PHI outputs before identity classification.

        This fixes the v_5848 class of bug:
            MULTIEQUAL [v_2697, v_2690] -> v_5848
            later: INT_SRIGHT [v_5848, ...]

        Such a PHI is not an identity/blank SSA artifact. It is a branch value
        selector and must be materialized or source-aliased.
        """

        self.used_temp_phi_output_sids = set()

        # Count uses as PHI sources so we can distinguish real downstream uses
        # from PHI bookkeeping.
        phi_source_uses = {}

        for phi in self.phi_nodes:
            for inp in list(getattr(phi, "inputs", []) or []):
                sid = self.sid_of(inp)
                if sid is not None:
                    phi_source_uses[sid] = phi_source_uses.get(sid, 0) + 1

        for phi in self.phi_nodes:
            out = getattr(phi, "output", None)
            inputs = list(getattr(phi, "inputs", []) or [])
            out_sid = self.sid_of(out)

            if out is None or out_sid is None or not inputs:
                continue

            if self.is_stack_local(out):
                continue

            ov = self.to_var(out)
            if ov is not None:
                if getattr(ov, "is_parameter", False):
                    continue
                if getattr(ov, "is_global", False):
                    continue
                if getattr(ov, "is_function", False):
                    continue
                if getattr(ov, "is_constant", False):
                    continue

            total_uses = self.use_counts.get(out_sid, 0)
            bookkeeping_uses = phi_source_uses.get(out_sid, 0)
            real_uses = max(0, total_uses - bookkeeping_uses)

            distinct_source_sids = set()

            for inp in inputs:
                sid = self.sid_of(inp)
                if sid is not None and sid != out_sid:
                    distinct_source_sids.add(sid)

            # A temp PHI with distinct incoming SSA values and real downstream
            # uses is a value selector, not an identity PHI.
            if real_uses > 0 and distinct_source_sids:
                self.used_temp_phi_output_sids.add(out_sid)

        # Keep legacy name in sync early.
        self.used_temp_phi_target_sids |= set(self.used_temp_phi_output_sids)

    def _is_value_selector_phi(self, phi):
        out = getattr(phi, "output", None)
        sid = self.sid_of(out)
        return bool(sid is not None and sid in self.used_temp_phi_output_sids)


    # ---------------------------------------------------------
    # PHI classification / drop-ins
    # ---------------------------------------------------------

    def _classify_phi_nodes(self):
        for phi in self.phi_nodes:
            out = getattr(phi, "output", None)
            inputs = list(getattr(phi, "inputs", []) or [])

            if out is None or not inputs:
                self.skipped_phi_nodes.append((phi, "missing output or inputs"))
                continue

            if self._is_value_selector_phi(phi):
                self.value_selector_phi_nodes.append(phi)
                self.transition_phi_nodes.append(phi)
                continue

            if self._is_identity_phi(out, inputs):
                self.identity_phi_nodes.append(phi)
            else:
                self.transition_phi_nodes.append(phi)

    def _is_identity_phi(self, out, inputs):
        usable = [i for i in inputs if i is not None]
        if not usable:
            return False

        out_sid = self.sid_of(out)

        if out_sid in self.used_temp_phi_output_sids:
            return False

        # Identity PHIs require every incoming value to be the same concrete
        # storage as the output. Anonymous temps are not concrete storage.
        for inp in usable:
            if self.is_const(inp):
                return False
            if not self.same_storage(out, inp):
                return False

        return True

    def _build_phi_dropins(self):
        self.phi_dropins = []
        self.phi_dropins_by_pred = {}
        self.phi_dropins_by_join = {}
        self.phi_source_counts = {}
        self.used_temp_phi_target_sids = set()

        for phi in self.phi_nodes:
            out = getattr(phi, "output", None)
            inputs = list(getattr(phi, "inputs", []) or [])

            if out is None or not inputs:
                continue

            join_node = self.cfg_node_for_phi(phi)
            join_addr = getattr(join_node, "addr", None) if join_node is not None else None

            preds = self.pred_nodes_for_join(join_node)
            if not preds:
                self.skipped_phi_nodes.append((phi, "no predecessor nodes"))
                continue

            assignments = self._match_phi_inputs_to_predecessors(phi, preds)

            target_sid = self.sid_of(out)

            is_value_selector = bool(target_sid in self.used_temp_phi_output_sids)

            # Any PHI target that has downstream uses must survive as a real
            # assignment target, including temp selector PHIs like v_5848.
            if target_sid is not None:
                self.local_target_sids.add(target_sid)
                if is_value_selector or (self.use_counts.get(target_sid, 0) > 0 and not self.is_stack_local(out)):
                    self.used_temp_phi_target_sids.add(target_sid)
                    self.materialize_sids.add(target_sid)
                    self.suppress_assign_sids.discard(target_sid)
                    self.inline_only_sids.discard(target_sid)

            for pred_node, incoming in assignments:
                if pred_node is None or incoming is None:
                    continue

                # True identity storage transitions do not need drop-ins.
                # Value selector temp PHIs must keep assignments even when
                # storage metadata is ambiguous or blank.
                if (not is_value_selector) and self.same_storage(out, incoming):
                    continue

                pred_addr = getattr(pred_node, "addr", None)

                source_node = self.to_node(incoming)
                source_var = self.to_var(incoming)
                source_sid = self.sid_of(incoming)

                target_name = self.name_for_var(out)

                if source_sid is not None:
                    self.phi_source_counts[source_sid] = self.phi_source_counts.get(source_sid, 0) + 1

                record = {
                    "kind": "phi_assignment",
                    "phi": phi,
                    "join_node": join_node,
                    "join_addr": join_addr,
                    "pred_node": pred_node,
                    "pred_addr": pred_addr,
                    "target": out,
                    "target_sid": target_sid,
                    "target_name": target_name,
                    "source": incoming,
                    "source_node": source_node,
                    "source_var": source_var,
                    "source_sid": source_sid,
                    "source_name": self.name_for_var(source_var),
                    "target_is_used_temp_phi": bool(target_sid in self.used_temp_phi_target_sids),
                    "target_is_value_selector_phi": bool(is_value_selector),
                    "reason": "value_selector_phi" if is_value_selector else "phi_transition",
                }

                self._stamp_phi_transition_token_v34(
                    record, stage="build_phi_dropins"
                )
                self.phi_dropins.append(record)
                self.phi_dropins_by_pred.setdefault(pred_addr, []).append(record)
                self.phi_dropins_by_join.setdefault(join_addr, []).append(record)

        self._classify_phi_source_foldability()

    def _protect_selector_passthrough_dropins_v20k(self):
        """
        Give transparent incoming arms of used value-selector PHIs explicit
        predecessor-local ownership.

        A selector arm such as::

            COPY [local_18] -> v_4146
            MULTIEQUAL [v_4146, v_4147, v_4148] -> v_4149

        carries the old value of ``local_18`` into ``v_4149``.  The COPY is a
        valid presentation bridge and may be suppressed, but the selector
        assignment is executable path state.  Therefore this arm must remain a
        required PHI drop-in instead of being declared accounted for by a
        normal source-op alias.

        The rule is topology/dataflow based: it applies only to a used temp
        selector target and only when the incoming source is a transparent
        chain rooted in concrete pre-existing storage/value.  Computed and CALL
        arms retain the existing source-alias fast path.
        """

        for rec in list(self.phi_dropins or []):
            if not rec.get("target_is_value_selector_phi"):
                continue

            source_sid = rec.get("source_sid")
            source_node = rec.get("source_node")
            target_sid = rec.get("target_sid")

            if source_sid is None or target_sid is None or source_node is None:
                continue

            opcode = getattr(source_node, "opcode", None)
            if opcode not in self.TRANSPARENT_OPS:
                continue

            leaf, chain, reason = self._selector_passthrough_leaf_v20k(source_node)
            leaf_var = self.to_var(leaf)

            concrete_leaf = bool(
                leaf_var is not None
                and (
                    self.is_stack_local(leaf_var)
                    or getattr(leaf_var, "is_parameter", False)
                    or getattr(leaf_var, "is_global", False)
                    or getattr(leaf_var, "is_constant", False)
                )
            )

            if not concrete_leaf:
                self.selector_passthrough_events.append({
                    "kind": "selector_passthrough_dropin_v20k_rejected",
                    "source_sid": source_sid,
                    "target_sid": target_sid,
                    "pred_addr": rec.get("pred_addr"),
                    "join_addr": rec.get("join_addr"),
                    "source_opcode": opcode,
                    "transparent_chain": list(chain),
                    "reason": reason or "transparent_chain_has_no_concrete_leaf",
                })
                continue

            rid = self._phi_record_id(rec)
            target_name = rec.get("target_name") or self.name_for_var(rec.get("target"))
            leaf_name = self.name_for_var(leaf_var)

            rec["selector_passthrough_dropin"] = True
            rec["dropin_required"] = True
            rec["dropin_scope"] = "predecessor_local_selector_passthrough"
            rec["required_reason"] = "used selector transparent arm requires explicit predecessor definition"
            rec.pop("source_aliased_to_target", None)
            rec.pop("accounted_for_by_state_alias", None)
            rec.pop("dropin_suppressed_reason", None)

            self.selector_passthrough_dropin_sids.add(source_sid)
            self.selector_passthrough_dropin_ids.add(rid)

            info = {
                "kind": "selector_passthrough_dropin_v20k",
                "id": rid,
                "source_sid": source_sid,
                "target_sid": target_sid,
                "target_name": target_name,
                "leaf_name": leaf_name,
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "source_opcode": opcode,
                "transparent_chain": list(chain),
                "reason": rec.get("required_reason"),
            }
            self.selector_passthrough_dropin_records.append(dict(info))
            self.selector_passthrough_events.append(dict(info))

    def _selector_passthrough_leaf_v20k(self, source_node):
        """Return ``(leaf, opcode_chain, rejection_reason)`` for a safe
        transparent selector source.

        Only the first input of unary transparent operations is followed.
        Cycles, missing inputs, PHIs, and computed leaves are rejected by the
        caller's concrete-leaf gate.
        """

        node = source_node
        seen = set()
        chain = []

        while node is not None:
            marker = id(node)
            if marker in seen:
                return None, chain, "transparent_chain_cycle"
            seen.add(marker)

            opcode = getattr(node, "opcode", None)
            if opcode not in self.TRANSPARENT_OPS:
                return getattr(node, "var", node), chain, None

            inputs = list(getattr(node, "inputs", []) or [])
            if not inputs:
                return None, chain, "transparent_node_has_no_input"

            chain.append(opcode)
            leaf = inputs[0]
            next_node = self.to_node(leaf)

            if next_node is None or getattr(next_node, "opcode", None) not in self.TRANSPARENT_OPS:
                return leaf, chain, None

            node = next_node

        return None, chain, "transparent_chain_has_no_leaf"

    def _classify_phi_source_foldability(self):
        for rec in self.phi_dropins:
            sid = rec.get("source_sid")
            node = rec.get("source_node")

            if sid is None or node is None:
                continue

            opcode = getattr(node, "opcode", None)
            use_count = self.use_counts.get(sid, 0)
            phi_count = self.phi_source_counts.get(sid, 0)

            # Pure bridge sources should never be emitted separately.
            if opcode in self.PURE_INLINE_OPS:
                self.phi_source_foldable_sids.add(sid)
                self.inline_only_sids.add(sid)
                self.suppress_assign_sids.add(sid)
                self.pure_bridge_sids.add(sid)
                continue

            # One-shot call result feeding a local target: fold into target.
            # Preserves reused calls such as inc2(i), because they have non-PHI uses.
            if opcode in self.CALL_OPS:
                if use_count <= phi_count:
                    self.phi_source_foldable_sids.add(sid)
                    self.inline_only_sids.add(sid)
                    self.suppress_assign_sids.add(sid)

    def _last_emperor_semantic_authority_active_v35(self):
        return bool(
            getattr(
                self.func,
                "phi_predecessor_linkage_version_v37",
                None,
            )
            or self.bohdi_emperor_semantic_transition_descriptions_v37
            or self.bohdi_emperor_semantic_transition_by_edge_v37
        )

    def _last_emperor_unidentified_input_signature_v35(self, value):
        var = self.to_var(value)
        if var is None:
            return ("none",)
        if getattr(var, "is_constant", False):
            constant = None
            for attr in ("const_value", "value", "offset"):
                if hasattr(var, attr):
                    constant = getattr(var, attr)
                    break
            return (
                "constant",
                repr(constant),
                int(getattr(var, "size", 0) or 0),
            )
        return (
            "unidentified",
            str(getattr(var, "space", None)),
            repr(getattr(var, "offset", None)),
            int(getattr(var, "size", 0) or 0),
            str(getattr(var, "name", None)),
        )

    def _match_phi_inputs_to_predecessors_v35(self, phi, preds):
        """Prefer complete SemanticGraph v37 linkage for any PHI.

        v37 is set based and order independent.  A complete per-PHI receipt
        set is therefore the preferred construction authority.  v35a does not
        confuse global v37 capability with total coverage, however: a sparse
        or unresolved ordinary PHI records a compatibility fallback and lets
        the established v24/v34 matcher continue.  If that PHI later becomes
        part of an execution-critical carried-state family,
        _compile_last_emperor_state_families_v35() requires exact receipts for
        the entire family and fails before projection.
        """

        if not self._last_emperor_semantic_authority_active_v35():
            return None

        self._refresh_bohdi_emperor_transition_inputs_v34()

        join_node = self.cfg_node_for_phi(phi)
        join_addr = getattr(join_node, "addr", None)
        target_sid = self._bohdi_emperor_sid_text_v34(
            getattr(phi, "output", None)
        )
        pred_by_addr = {
            getattr(pred, "addr", None): pred
            for pred in list(preds or [])
            if getattr(pred, "addr", None) is not None
        }
        input_by_sid = {}
        for incoming in list(getattr(phi, "inputs", []) or []):
            source_sid = self._bohdi_emperor_sid_text_v34(incoming)
            input_by_sid.setdefault(source_sid, []).append(incoming)

        receipts = [
            item
            for item in list(
                self.bohdi_emperor_semantic_transition_descriptions_v37
                or []
            )
            if isinstance(item, dict)
            and item.get("join_addr") == join_addr
            and self._bohdi_emperor_sid_text_v34(
                item.get("target_sid")
            ) == target_sid
        ]
        receipt_by_pred = {}
        for item in receipts:
            receipt_by_pred.setdefault(
                item.get("pred_addr"), []
            ).append(item)

        failures = []
        expected_preds = set(pred_by_addr)
        receipt_preds = set(receipt_by_pred)
        if expected_preds != receipt_preds:
            failures.append({
                "gate": "every_predecessor_has_one_semantic_receipt",
                "expected_predecessors": sorted(expected_preds),
                "receipt_predecessors": sorted(receipt_preds),
            })

        pairs = []
        for pred_addr in sorted(expected_preds):
            matches = list(receipt_by_pred.get(pred_addr, []) or [])
            if len(matches) != 1:
                failures.append({
                    "gate": "exactly_one_receipt_per_predecessor",
                    "pred_addr": pred_addr,
                    "receipts": len(matches),
                })
                continue

            receipt = matches[0]
            receipt_edge = self._bohdi_emperor_pair_v34(
                receipt.get("edge_id")
            )
            receipt_gates = {
                "edge_identity_frozen": (
                    receipt.get("edge_identity_frozen") is True
                ),
                "input_order_not_authoritative": (
                    receipt.get("input_order_used") is False
                ),
                "successor_order_not_authoritative": (
                    receipt.get("successor_order_used") is False
                ),
                "edge_pair_matches_predecessor": (
                    receipt_edge in (
                        None,
                        (pred_addr, join_addr),
                    )
                ),
            }
            failed_receipt_gates = [
                name
                for name, accepted in receipt_gates.items()
                if not accepted
            ]
            if failed_receipt_gates:
                failures.append({
                    "gate": "semantic_receipt_authority",
                    "pred_addr": pred_addr,
                    "failed_receipt_gates": failed_receipt_gates,
                    "receipt_gates": receipt_gates,
                })
                continue

            source_sid = self._bohdi_emperor_sid_text_v34(
                receipt.get("source_sid")
            )
            candidates = list(input_by_sid.get(source_sid, []) or [])
            if not candidates:
                failures.append({
                    "gate": "semantic_source_is_live_phi_input",
                    "pred_addr": pred_addr,
                    "source_sid": source_sid,
                    "candidate_inputs": len(candidates),
                })
                continue

            if source_sid is None:
                signatures = {
                    self._last_emperor_unidentified_input_signature_v35(
                        candidate
                    )
                    for candidate in candidates
                }
                if len(signatures) != 1:
                    failures.append({
                        "gate": (
                            "unidentified_semantic_sources_are_equivalent"
                        ),
                        "pred_addr": pred_addr,
                        "candidate_signatures": sorted(
                            signatures, key=str
                        ),
                    })
                    continue

            pairs.append((pred_by_addr[pred_addr], candidates[0]))

        if len(pairs) != len(pred_by_addr):
            failures.append({
                "gate": "complete_order_independent_pairing",
                "pairs": len(pairs),
                "predecessors": len(pred_by_addr),
            })

        event = {
            "kind": (
                "last_emperor_exact_phi_predecessor_pairing_v35"
                if not failures else
                "last_emperor_sparse_phi_compatibility_fallback_v35a"
            ),
            "version": (
                self.last_emperor_version_v35
                if not failures
                else self.last_emperor_coverage_version_v35a
            ),
            "join_addr": join_addr,
            "target_sid": target_sid,
            "predecessors": sorted(expected_preds),
            "semantic_receipts": len(receipts),
            "pairs": len(pairs),
            "input_order_used": False,
            "successor_order_used": False,
            "coverage_scope": (
                "exact_per_phi"
                if not failures
                else "ordinary_phi_compatibility"
            ),
            "fallback_authority": (
                None if not failures else "PALPHIfolder_v24_v34"
            ),
            "family_projection_permitted": not bool(failures),
            "failures": failures,
        }
        self.phi_state_family_events_v35.append(event)
        self.phi_semantic_coverage_events_v35a.append(event)

        if failures:
            self.phi_semantic_coverage_warnings_v35a.append(event)
            return None

        return pairs

    def _match_phi_inputs_to_predecessors(self, phi, preds):
        # v35a: consume complete v37 evidence when it exists for this PHI.
        # Sparse per-PHI coverage is not a build-time error by itself; the
        # carried-state compiler below applies exact fail-closed authority only
        # after a PHI chain qualifies as an execution-owner family.
        semantic_pairs = self._match_phi_inputs_to_predecessors_v35(
            phi, preds
        )
        if semantic_pairs is not None:
            return semantic_pairs

        # v24: resolved multiway dispatch joins use SemanticGraph's explicit
        # predecessor/source identity.  Neither CFG predecessor order nor
        # MULTIEQUAL input order is a valid authority.
        semantic_pairs = self._match_multiway_phi_inputs_to_predecessors_v24(
            phi, preds
        )
        if semantic_pairs is not None:
            return semantic_pairs

        inputs = list(getattr(phi, "inputs", []) or [])

        remaining_preds = list(preds)
        remaining_inputs = list(inputs)
        pairs = []

        for inp in list(remaining_inputs):
            src_block = self.block_of_semantic(inp)
            src_addr = self.block_addr(src_block)
            if src_addr is None:
                continue

            matched_pred = None
            for pred in remaining_preds:
                if getattr(pred, "addr", None) == src_addr:
                    matched_pred = pred
                    break

            if matched_pred is not None:
                pairs.append((matched_pred, inp))
                remaining_preds.remove(matched_pred)
                remaining_inputs.remove(inp)

        count = min(len(remaining_preds), len(remaining_inputs))
        for i in range(count):
            pairs.append((remaining_preds[i], remaining_inputs[i]))

        if len(inputs) != len(preds):
            self.skipped_phi_nodes.append(
                (phi, "phi input/predecessor count mismatch: inputs=%d preds=%d" %
                 (len(inputs), len(preds)))
            )

        return pairs

    # ---------------------------------------------------------
    # Naming
    # ---------------------------------------------------------

    def _build_groups_without_phi_union(self):
        groups = {}

        for sid, node in self.nodes.items():
            var = self.to_var(node)
            key = self.naming_key(var)
            groups.setdefault(key, []).append(sid)

        self.groups = {}

        for key, members in groups.items():
            rep = members[0]
            self.groups[rep] = members

    def naming_key(self, var):
        if var is None:
            return ("unknown", id(var))

        if getattr(var, "is_constant", False):
            return ("const", getattr(var, "offset", None), getattr(var, "size", None))

        if getattr(var, "is_parameter", False):
            return ("param", getattr(var, "name", None), getattr(var, "offset", None))

        if getattr(var, "is_stack", False) or getattr(var, "space", None) == "stack":
            return ("stack", getattr(var, "offset", None), getattr(var, "size", None))

        if getattr(var, "is_global", False):
            return ("global", getattr(var, "offset", None), getattr(var, "size", None))

        if getattr(var, "is_function", False):
            return ("function", getattr(var, "offset", None), getattr(var, "name", None))

        return ("ssa", getattr(var, "ssa_id", None))

    def _build_var_map(self):
        self.var_map = {}
        temp_counter = 0

        for rep, members in self.groups.items():
            rep_node = self.nodes.get(rep)
            rep_var = self.to_var(rep_node)
            name = self.name_for_var(rep_var)

            if not name:
                name = "v_%d" % temp_counter
                temp_counter += 1

            for sid in members:
                self.var_map[sid] = name

        for phi in self.phi_nodes:
            out = getattr(phi, "output", None)
            sid = getattr(out, "ssa_id", None)
            if sid is not None:
                self.var_map[sid] = self.name_for_var(out)

        # v29 must establish temporal snapshot/result custody before the
        # legacy first source-alias pass embedded in _build_var_map().  The
        # run() method invokes the same consumer again after return so later
        # projection passes receive an idempotent refreshed handoff.
        self._consume_erase_emperor_snapshot_custody_v29(
            stage="build_var_map_pre_alias"
        )
        self._apply_used_temp_phi_source_aliases()

    def name_for_var(self, var):
        if var is None:
            return None

        if hasattr(var, "var"):
            var = var.var

        if getattr(var, "is_constant", False):
            if hasattr(var, "const_value"):
                return str(getattr(var, "const_value"))
            if hasattr(var, "value"):
                return str(getattr(var, "value"))
            if hasattr(var, "offset"):
                return str(getattr(var, "offset"))
            return "0"

        existing = getattr(var, "name", None)
        if existing:
            return self._sanitize_name(existing)

        if getattr(var, "is_parameter", False):
            return "param"

        if getattr(var, "is_stack", False) or getattr(var, "space", None) == "stack":
            off = getattr(var, "offset", None)
            if off is not None:
                return "local_%x" % abs(off)
            return "local"

        if getattr(var, "is_global", False):
            off = getattr(var, "offset", None)
            if off is not None:
                return "g_%x" % off
            return "global"

        if getattr(var, "is_function", False):
            sym = getattr(var, "symbol", None)
            if sym:
                return self._sanitize_name(sym)
            off = getattr(var, "offset", None)
            if off is not None:
                return "sub_%x" % off
            return "sub_unknown"

        sid = getattr(var, "ssa_id", None)
        if sid is not None:
            return self._sanitize_name(str(sid))

        return None

    def _sanitize_name(self, name):
        if name is None:
            return None

        s = str(name)
        if s.startswith("0x"):
            return s

        out = []
        for ch in s:
            if ch.isalnum() or ch == "_":
                out.append(ch)
            else:
                out.append("_")
        s = "".join(out)

        if not s:
            return None

        if s[0].isdigit():
            s = "v_" + s

        while s.startswith("v_v_"):
            s = s[2:]

        return s

    def _apply_used_temp_phi_source_aliases(self):
        """
        v18c generalized PHI source aliasing.

        Old behavior handled only used temp selector PHIs such as:
            MULTIEQUAL [v_2697, v_2690] -> v_5848

        v9 extends the same execution-truth idea to local-transition PHIs:
            CALL mutate(...) -> v_1728
            MULTIEQUAL [v_1728, local_20] -> local_20

        Instead of exposing both:
            v_1728 = mutate(...)
            local_20 = mutate(...)

        map the source SID to the PHI target name, so the normal defining op
        writes the target directly:
            local_20 = mutate(...)

        This also fixes counter transition temps such as:
            INT_ADD [local_14, 1] -> v_367
            MULTIEQUAL [local_14, v_367, v_367] -> local_14

        Safety policy:
            - source must not be real storage / parameter / global / constant
            - target must be a stack local or a used temp selector PHI target
            - source must be one-shot with respect to PHI source use, or a pure
              expression whose only extra uses are condition/tail tests
            - CALL sources are aliased only when they have no meaningful
              non-PHI use
        """

        for rec in list(self.phi_dropins or []):
            target_sid = rec.get("target_sid")
            source_sid = rec.get("source_sid")

            if target_sid is None or source_sid is None:
                continue

            if not self._can_alias_phi_source_to_target(rec):
                continue

            target_name = rec.get("target_name")

            if not target_name:
                target_name = self.name_for_var(rec.get("target"))

            if not target_name:
                continue

            self.var_map[source_sid] = target_name
            self.var_map[target_sid] = target_name

            self.phi_source_alias_sids.add(source_sid)
            alias_reason = self._phi_source_alias_reason(rec)
            self.phi_source_aliases[source_sid] = {
                "target_sid": target_sid,
                "target_name": target_name,
                "source_name": rec.get("source_name"),
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": alias_reason,
            }

            # v18c: explicit state-transition alias contract for the emitter.
            # The source op should emit at its block location under target_name.
            self.state_transition_alias_sids.add(source_sid)
            self.state_transition_aliases[source_sid] = {
                "target_sid": target_sid,
                "target_name": target_name,
                "source_name": rec.get("source_name"),
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": alias_reason,
                "source_opcode": getattr(rec.get("source_node"), "opcode", None),
            }
            self.must_emit_state_write_sids.add(source_sid)
            self.state_write_info[source_sid] = {
                "kind": "phi_source_alias_state_write",
                "target_sid": target_sid,
                "target_name": target_name,
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": alias_reason,
            }

            if self._is_post_update_alias_record(rec):
                self._register_post_update_alias(rec, target_name, alias_reason)

            if self._uses_are_same_block_conditionish(source_sid, rec.get("source_node")):
                self.duplicate_phi_cleanup_alias_sids.add(source_sid)
                self.duplicate_phi_cleanup_alias_info[source_sid] = {
                    "target_sid": target_sid,
                    "target_name": target_name,
                    "pred_addr": rec.get("pred_addr"),
                    "join_addr": rec.get("join_addr"),
                    "reason": "conditionish_call_phi_duplicate_cleanup",
                }

            # Backward-compatible temp selector alias metadata.
            if target_sid in self.used_temp_phi_target_sids:
                self.temp_phi_source_alias_sids.add(source_sid)
                self.temp_phi_source_aliases[source_sid] = {
                    "target_sid": target_sid,
                    "target_name": target_name,
                    "source_name": rec.get("source_name"),
                    "pred_addr": rec.get("pred_addr"),
                    "join_addr": rec.get("join_addr"),
                    "reason": "used_temp_phi_source_alias",
                }

            # The normal assignment now carries the transition.  It must be
            # visible/materialized under the target name.  A metadata-aware
            # emitter may skip the redundant PHI drop-in record for this source.
            self.suppress_assign_sids.discard(source_sid)
            self.inline_only_sids.discard(source_sid)
            self.materialize_sids.add(source_sid)
            self.dropin_suppressed_by_source_alias.add(source_sid)
            rec["source_aliased_to_target"] = True
            rec["dropin_required"] = False
            rec["dropin_suppressed_reason"] = "normal_source_op_writes_phi_target"

            # Propagate suppression marker to equivalent records for the same
            # source/target/join. Shared PHI inputs can appear more than once.
            for other in self.phi_dropins:
                if other is rec:
                    continue
                if (
                    other.get("source_sid") == source_sid
                    and other.get("target_sid") == target_sid
                    and other.get("join_addr") == rec.get("join_addr")
                ):
                    other["source_aliased_to_target"] = True
                    other["dropin_required"] = False
                    other["dropin_suppressed_reason"] = "normal_source_op_writes_phi_target"

    def _is_post_update_alias_record(self, rec):
        """
        True when an accepted PHI source alias is the freshly computed next
        value of the same local state target.

        v20b widens the old direct INT_ADD/INT_SUB test:
          - resolves transparent wrappers around the source;
          - accepts any pure arithmetic expression that contains the target
            local and at least one non-zero constant/delta;
          - still rejects calls, loads/stores, PHIs, and non-local targets.

        This upgrades generic phi_source_alias records such as:
            v_367 = local_14 + 1  -> local_14
        into post_update_alias records.
        """

        ok, reason = self._post_update_alias_reason_v20b(rec)
        ev = {
            "source_sid": rec.get("source_sid"),
            "target_sid": rec.get("target_sid"),
            "target_name": rec.get("target_name") or self.name_for_var(rec.get("target")),
            "source_opcode": getattr(rec.get("source_node"), "opcode", None),
            "pred_addr": rec.get("pred_addr"),
            "join_addr": rec.get("join_addr"),
            "result": bool(ok),
            "reason": reason,
        }

        if ok:
            self.post_update_alias_detection_events.append(ev)
        else:
            self.post_update_alias_reject_events.append(ev)

        return bool(ok)

    def _post_update_alias_reason_v20b(self, rec):
        source_node = rec.get("source_node")
        target = rec.get("target")

        if source_node is None:
            return False, "missing_source_node"
        if target is None:
            return False, "missing_target"

        source_sid = rec.get("source_sid") or self.sid_of(source_node)
        if self._erase_emperor_is_derived_result_sid_v29(source_sid):
            return False, "erase_emperor_snapshot_derived_result_not_state_successor"

        if not self.is_stack_local(target):
            return False, "target_not_stack_local"

        target_name = rec.get("target_name") or self.name_for_var(target)
        if not target_name:
            return False, "missing_target_name"

        node = self._resolve_transparent_source_node_v20b(source_node)
        opcode = getattr(node, "opcode", None)

        if opcode in self.CALL_OPS or opcode in ("LOAD", "STORE", "INDIRECT", "MULTIEQUAL"):
            return False, "impure_or_phi_source:%s" % opcode

        if opcode not in self.PURE_INLINE_OPS:
            return False, "source_not_pure_inline:%s" % opcode

        # The source expression must contain the target state variable and a
        # change component.  This covers x+1, x-1, (x+y)%10, x^mask, etc.
        if not self._source_expr_mentions_target_v20b(node, target, target_name):
            return False, "source_expr_does_not_mention_target"

        if not self._source_expr_has_update_component_v20b(node, target, target_name):
            return False, "source_expr_has_no_update_component"

        return True, "pure_source_expr_mentions_target_and_update_component"

    def _resolve_transparent_source_node_v20b(self, node):
        seen = set()
        cur = node

        while cur is not None:
            sid = self.sid_of(cur)
            if sid is not None:
                if sid in seen:
                    return cur
                seen.add(sid)

            if self._erase_emperor_is_snapshot_value_v29(cur):
                return cur

            opcode = getattr(cur, "opcode", None)
            if opcode not in self.TRANSPARENT_OPS:
                return cur

            inputs = list(getattr(cur, "inputs", []) or [])
            if not inputs:
                return cur

            nxt = inputs[0]
            nxt_node = self.to_node(nxt)
            if nxt_node is None:
                return cur
            cur = nxt_node

        return node

    def _source_expr_mentions_target_v20b(self, node, target, target_name, seen=None):
        if node is None:
            return False

        if seen is None:
            seen = set()

        sid = self.sid_of(node)
        if sid is not None:
            if sid in seen:
                return False
            seen.add(sid)

        for inp in list(getattr(node, "inputs", []) or []):
            if self.is_const(inp):
                continue

            if self.same_storage(target, inp):
                return True

            inp_name = self.name_for_var(self.to_var(inp))
            if inp_name and inp_name == target_name:
                return True

            inp_node = self.to_node(inp)
            if inp_node is not None and self._source_expr_mentions_target_v20b(inp_node, target, target_name, seen):
                return True

        return False

    def _source_expr_has_update_component_v20b(self, node, target, target_name, seen=None):
        if node is None:
            return False

        if seen is None:
            seen = set()

        sid = self.sid_of(node)
        if sid is not None:
            if sid in seen:
                return False
            seen.add(sid)

        opcode = getattr(node, "opcode", None)

        # Pure arithmetic/bitwise value builders represent a new value when
        # they combine the target with anything else.
        if opcode in (
            "INT_ADD", "INT_SUB", "INT_MULT", "INT_DIV", "INT_SDIV",
            "INT_REM", "INT_SREM", "INT_AND", "INT_OR", "INT_XOR",
            "INT_LEFT", "INT_RIGHT", "INT_SRIGHT",
        ):
            saw_target = False
            saw_other = False

            for inp in list(getattr(node, "inputs", []) or []):
                if self.is_const(inp):
                    saw_other = True
                    continue

                inp_name = self.name_for_var(self.to_var(inp))
                if self.same_storage(target, inp) or inp_name == target_name:
                    saw_target = True
                    continue

                inp_node = self.to_node(inp)
                if inp_node is not None and self._source_expr_mentions_target_v20b(inp_node, target, target_name, seen.copy()):
                    saw_target = True
                else:
                    saw_other = True

            return saw_target and saw_other

        if opcode in self.TRANSPARENT_OPS:
            inputs = list(getattr(node, "inputs", []) or [])
            if inputs:
                inp_node = self.to_node(inputs[0])
                if inp_node is not None:
                    return self._source_expr_has_update_component_v20b(inp_node, target, target_name, seen)

        # For non-arithmetic pure helpers, recurse and let child arithmetic
        # prove the update component.
        for inp in list(getattr(node, "inputs", []) or []):
            inp_node = self.to_node(inp)
            if inp_node is not None and self._source_expr_has_update_component_v20b(inp_node, target, target_name, seen):
                return True

        return False


    def _register_post_update_alias(self, rec, target_name, alias_reason):
        source_sid = rec.get("source_sid")
        target_sid = rec.get("target_sid")
        source_node = rec.get("source_node")

        if source_sid is None or target_sid is None or source_node is None:
            return

        self.post_update_alias_sids.add(source_sid)
        self.prefer_var_expr_sids.add(source_sid)

        source_expr = self._expr_for_node_or_op(source_node, getattr(source_node, "op", None), getattr(source_node, "block", None))

        self.post_update_aliases[source_sid] = {
            "target_sid": target_sid,
            "target_name": target_name,
            "source_opcode": getattr(source_node, "opcode", None),
            "source_expr": source_expr,
            "pred_addr": rec.get("pred_addr"),
            "join_addr": rec.get("join_addr"),
            "reason": alias_reason or "post_update_phi_source_alias",
            "policy": "render_source_sid_as_post_update_target_variable",
        }

        # Strengthen the existing policy entry if present later; the final
        # policy pass will also re-apply this.
        self.materialize_sids.add(source_sid)
        self.suppress_assign_sids.discard(source_sid)
        self.inline_only_sids.discard(source_sid)

        try:
            source_node.post_update_alias = True
            source_node.no_inline = True
            source_node.materialize = True
            source_node.prefer_var_expr = True
        except Exception:
            pass

    def _propagate_post_update_alias_consumers(self):
        """
        Mark condition/compare consumers of post-update aliases.

        If v_367 is aliased to local_14, then a consumer such as:
            v_436 = INT_SLESS [0x4, v_367]
        must be rendered as 4 < local_14, not 4 < (local_14 + 1), once the
        source assignment has been emitted as local_14 += 1.
        """

        for source_sid in list(self.post_update_alias_sids):
            info = self.post_update_aliases.get(source_sid, {})
            target_name = info.get("target_name") or self.var_map.get(source_sid)

            for consumer in self._consumer_nodes_for_sid(source_sid):
                csid = self.sid_of(consumer)
                if csid is None:
                    continue

                opcode = getattr(consumer, "opcode", None)
                if opcode not in self.COMPARE_OPS and not self.is_condition(consumer):
                    # Propagate only through condition-ish nodes.  Do not
                    # rewrite arbitrary arithmetic without a future dataflow
                    # proof.
                    continue

                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases[csid] = {
                    "source_sid": source_sid,
                    "target_name": target_name,
                    "consumer_opcode": opcode,
                    "reason": "condition_consumes_post_update_alias",
                }

                try:
                    consumer.post_update_consumer = True
                    consumer.prefer_var_inputs = True
                except Exception:
                    pass

    def _phi_source_alias_reason(self, rec):
        target_sid = rec.get("target_sid")
        source_node = rec.get("source_node")
        opcode = getattr(source_node, "opcode", None) if source_node is not None else None

        if target_sid in self.used_temp_phi_target_sids:
            return "used_temp_phi_source_alias"

        if opcode in self.CALL_OPS:
            return "call_source_to_local_phi_target"

        return "pure_source_to_local_phi_target"

    def _consumer_nodes_for_sid(self, sid):
        return list(getattr(self, "consumer_nodes_by_sid", {}).get(sid, []) or [])

    def _node_block_addr(self, node):
        """
        Best-effort block address extraction for FormulaNode/PALPcodeOp-like
        objects. Different layers have used block, cfg_node, block_region, or
        direct *_addr attributes over the life of PAL; v18c accepts all of
        them for alias-safety diagnostics.
        """

        if node is None:
            return None

        for attr in ("block_addr", "cfg_addr", "addr"):
            val = getattr(node, attr, None)
            if isinstance(val, int):
                return val

        for attr in ("block", "cfg_node", "block_region", "owner_block"):
            obj = getattr(node, attr, None)
            if obj is None:
                continue

            if isinstance(obj, int):
                return obj

            val = getattr(obj, "addr", None)
            if isinstance(val, int):
                return val

            val = getattr(obj, "start", None)
            if isinstance(val, int):
                return val

        # Last resort: defining p-code op may carry an owning block.
        op = getattr(node, "op", None)
        if op is not None and op is not node:
            return self._node_block_addr(op)

        return None

    def _is_conditionish_consumer_node(self, node):
        """
        True for small pure tests that can safely be rendered against an
        aliased local after the source write. This deliberately excludes CALL,
        STORE, LOAD, and arithmetic state producers.
        """

        if node is None:
            return False

        cop = getattr(node, "opcode", None)

        allowed = {
            "INT_EQUAL", "INT_NOTEQUAL",
            "INT_LESS", "INT_SLESS",
            "INT_LESSEQUAL", "INT_SLESSEQUAL",
            "INT_AND", "INT_OR", "INT_XOR",
            "INT_ZEXT", "CAST", "SUBPIECE",
        }

        return cop in allowed

    def _uses_are_same_block_conditionish(self, source_sid, source_node):
        """
        Safe alias widening for call/temp results that immediately become a
        local PHI target but are also tested in the same local branch block.

        Example:
            v_1743 = mutate(...)
            local_18 = PHI(..., v_1743)
            if v_1743 != 0xf: ...

        The emitted form may be:
            local_18 = mutate(...)
            if local_18 != 0xf: ...

        v18b required strong same-block addr evidence. v18c is still safe but
        more tolerant of missing block metadata: if every non-PHI consumer is a
        conditionish pure node, and no consumer is visibly in a different block,
        aliasing is allowed.
        """

        if source_sid is None or source_node is None:
            return False

        src_block_addr = self._node_block_addr(source_node)
        consumers = self._consumer_nodes_for_sid(source_sid)

        if not consumers:
            return True

        saw_real_consumer = False

        for cn in consumers:
            if cn is source_node:
                continue

            if not self._is_conditionish_consumer_node(cn):
                return False

            saw_real_consumer = True

            caddr = self._node_block_addr(cn)

            # If both addresses are known, require same block. If one side is
            # unknown, do not reject purely on missing metadata.
            if src_block_addr is not None and caddr is not None and caddr != src_block_addr:
                return False

        return saw_real_consumer or True

    def _phi_record_id(self, rec):
        """Return PHIfolder's stamped token; never invent a downstream schema."""
        if not isinstance(rec, dict):
            return None
        existing = self._normalize_phi_transition_id_v34(rec.get("id"))
        if existing is not None:
            return existing
        token = self._stamp_phi_transition_token_v34(
            rec, stage="lazy_phi_record_id"
        )
        return token.get("id")

    def _mark_path_local_phi_dropins(self):
        """
        Mark PHI records whose predecessor block is a shared branch tail.

        SGL v18b can project a shared tail block into more than one branch arm.
        Emitter must not globally de-duplicate PHI drop-ins for such records,
        otherwise one path receives the join update and the other loses it.
        """

        for rec in self.phi_dropins:
            if rec.get("multiway_case_edge_dropin"):
                rec["path_local_dropin"] = True
                rec["dropin_scope"] = "multiway_case_edge_predecessor"
                rid = self._phi_record_id(rec)
                self.path_local_phi_dropin_ids.add(rid)
                if rid not in {
                    item.get("id") for item in self.path_local_phi_dropin_records
                }:
                    self.path_local_phi_dropin_records.append({
                        "id": rid,
                        "dispatcher": rec.get("multiway_dispatcher"),
                        "case_target": rec.get("multiway_case_target"),
                        "edge_identity": rec.get("multiway_edge_identity"),
                        "join_addr": rec.get("join_addr"),
                        "pred_addr": rec.get("pred_addr"),
                        "target_sid": rec.get("target_sid"),
                        "target_name": rec.get("target_name"),
                        "source_sid": rec.get("source_sid"),
                        "source_name": rec.get("source_name"),
                        "reason": "multiway case-edge predecessor scope",
                    })
                continue

            pred = rec.get("pred_node")
            if pred is None:
                continue

            in_edges = list(getattr(pred, "in_edges", []) or [])
            out_edges = list(getattr(pred, "out_edges", []) or [])

            shared_pred = len(in_edges) > 1
            linear_to_join = (
                len(out_edges) == 1
                and getattr(getattr(out_edges[0], "dst", None), "addr", None) == rec.get("join_addr")
            )

            if not (shared_pred and linear_to_join):
                continue

            rec["path_local_dropin"] = True
            rec["dropin_scope"] = "path_local_shared_tail"
            rid = self._phi_record_id(rec)
            self.path_local_phi_dropin_ids.add(rid)
            self.path_local_phi_dropin_records.append({
                "id": rid,
                "join_addr": rec.get("join_addr"),
                "pred_addr": rec.get("pred_addr"),
                "target_sid": rec.get("target_sid"),
                "target_name": rec.get("target_name"),
                "source_sid": rec.get("source_sid"),
                "source_name": rec.get("source_name"),
                "reason": "shared branch-tail predecessor",
            })


    # ---------------------------------------------------------
    # DISTINCT SSA OPERAND / SNAPSHOT CUSTODY (v26)
    # ---------------------------------------------------------

    # ---------------------------------------------------------
    # v28 EXACT-CONSUMER OPERAND / STATE CUSTODY
    # ---------------------------------------------------------

    @staticmethod
    def _projection_sid_text_v28(value):
        if value is None:
            return None
        if hasattr(value, "var"):
            value = getattr(value, "var", value)
        sid = getattr(value, "ssa_id", value)
        return None if sid is None else str(sid)

    @staticmethod
    def _projection_sid_variants_v28(sid):
        if sid is None:
            return []
        out = [sid, str(sid)]
        text = str(sid)
        if text.startswith("v_") and text[2:].isdigit():
            out.extend([text[2:], int(text[2:])])
        elif text.isdigit():
            out.extend([int(text), "v_%s" % text])
        unique = []
        seen = set()
        for item in out:
            marker = (type(item).__name__, str(item))
            if marker in seen:
                continue
            seen.add(marker)
            unique.append(item)
        return unique

    def _projection_node_for_sid_v28(self, sid):
        for key in self._projection_sid_variants_v28(sid):
            if key in self.nodes:
                return self.nodes.get(key)
        return None

    def _projection_var_map_key_v28(self, sid):
        for key in self._projection_sid_variants_v28(sid):
            if key in self.var_map:
                return key
        node = self._projection_node_for_sid_v28(sid)
        if node is not None:
            node_sid = self.sid_of(node)
            if node_sid is not None:
                return node_sid
        return sid

    def _projection_sid_is_protected_v28(self, sid):
        variants = self._projection_sid_variants_v28(sid)
        protected = (
            self.joint_consumer_exact_operand_sids
            | self.joint_consumer_projection_lineage_sids
        )
        return any(item in protected or str(item) in protected for item in variants)

    def _concrete_stack_key_v28(self, value):
        var = self.to_var(value)
        if var is None:
            return None

        space = (
            getattr(var, "storage_space", None)
            or getattr(var, "space", None)
        )
        if str(space or "").lower() != "stack":
            return None

        offset = getattr(var, "storage_offset", None)
        if offset is None:
            offset = getattr(var, "offset", None)
        if offset is None:
            return None

        size = getattr(var, "storage_size", None)
        if size is None:
            size = getattr(var, "size", None)

        try:
            return ("stack", int(offset), int(size or 0))
        except Exception:
            return None

    @staticmethod
    def _normalize_projection_stack_key_v28(key):
        if not isinstance(key, (tuple, list)):
            return None
        key = tuple(key)
        if len(key) >= 3 and str(key[0]).lower() == "stack":
            try:
                return ("stack", int(key[1]), int(key[2] or 0))
            except Exception:
                return None
        if len(key) >= 4 and key[0] == "space" and str(key[1]).lower() == "stack":
            try:
                return ("stack", int(key[2]), int(key[3] or 0))
            except Exception:
                return None
        return None

    @staticmethod
    def _projection_name_for_stack_key_v28(key):
        key = PALPHIfolder._normalize_projection_stack_key_v28(key)
        if key is None:
            return None
        return "local_%x" % abs(int(key[1]))

    def _projection_source_key_v28(self, value, seen=None):
        if value is None:
            return None
        if seen is None:
            seen = set()

        direct = self._concrete_stack_key_v28(value)
        if direct is not None:
            return direct

        node = self.to_node(value)
        if node is None:
            return None
        sid = self.sid_of(node)
        marker = str(sid) if sid is not None else "node:%s" % id(node)
        if marker in seen:
            return None
        seen.add(marker)

        opcode = getattr(node, "opcode", None)
        inputs = list(getattr(node, "inputs", []) or [])
        if opcode in self.TRANSPARENT_OPS or opcode == "SUBPIECE":
            if inputs:
                return self._projection_source_key_v28(inputs[0], seen)
            return None

        if opcode == "MULTIEQUAL" and inputs:
            keys = {
                self._projection_source_key_v28(inp, set(seen))
                for inp in inputs
            }
            keys.discard(None)
            if len(keys) == 1:
                return next(iter(keys))
        return None

    def _projection_lineage_v28(self, value, expected_key, seen=None):
        """Return exact SID lineage that preserves one proved stack cell.

        Only transparent transports and identity PHIs whose every resolvable
        arm proves the same concrete stack key are traversed.  This keeps the
        projection local to the exact consumer evidence while ensuring a COPY
        or loop-carried PHI owner is rendered under the same executable name.
        """
        if value is None:
            return []
        if seen is None:
            seen = set()

        node = self.to_node(value)
        var = self.to_var(value)
        sid = self.sid_of(value)
        marker = str(sid) if sid is not None else "obj:%s" % id(value)
        if marker in seen:
            return []
        seen.add(marker)

        actual_key = self._projection_source_key_v28(value)
        if actual_key != expected_key:
            return []

        records = []
        if sid is not None:
            records.append((sid, node, var))

        if node is None:
            return records

        opcode = getattr(node, "opcode", None)
        inputs = list(getattr(node, "inputs", []) or [])
        if (opcode in self.TRANSPARENT_OPS or opcode == "SUBPIECE") and inputs:
            records.extend(
                self._projection_lineage_v28(inputs[0], expected_key, seen)
            )
        elif opcode == "MULTIEQUAL" and inputs:
            for inp in inputs:
                if self._projection_source_key_v28(inp) == expected_key:
                    records.extend(
                        self._projection_lineage_v28(
                            inp, expected_key, set(seen)
                        )
                    )

        unique = []
        used = set()
        for rec in records:
            key = str(rec[0])
            if key in used:
                continue
            used.add(key)
            unique.append(rec)
        return unique

    def _projection_contract_records_v28(self):
        records = []
        seen = set()
        for raw_key, raw_rec in list(
            (self.joint_consumer_stack_projection_contracts or {}).items()
        ):
            if not isinstance(raw_rec, dict):
                self.joint_consumer_stack_projection_warnings.append({
                    "kind": "joint_consumer_contract_not_mapping_v28",
                    "key": raw_key,
                    "record_type": type(raw_rec).__name__,
                })
                continue
            rec = dict(raw_rec)
            consumer_sid = self._projection_sid_text_v28(
                rec.get("consumer_sid")
                if rec.get("consumer_sid") is not None
                else (raw_key[0] if isinstance(raw_key, tuple) and raw_key else None)
            )
            operand_index = rec.get("operand_index")
            if operand_index is None and isinstance(raw_key, tuple) and len(raw_key) > 1:
                operand_index = raw_key[1]
            try:
                operand_index = int(operand_index)
            except Exception:
                operand_index = None
            rec["consumer_sid"] = consumer_sid
            rec["operand_index"] = operand_index
            marker = (consumer_sid, operand_index)
            if marker in seen:
                continue
            seen.add(marker)
            records.append(rec)
        records.sort(key=lambda rec: (
            str(rec.get("consumer_sid")),
            -1 if rec.get("operand_index") is None else rec.get("operand_index"),
        ))
        return records

    def _projection_mark_visible_v28(self, sid, name, reason, state_write=False):
        key = self._projection_var_map_key_v28(sid)
        if key is None:
            return None
        self.var_map[key] = name
        self.joint_consumer_projection_lineage_sids.add(key)
        self.joint_consumer_projection_lineage_sids.add(str(key))
        self.materialize_sids.add(key)
        self.suppress_assign_sids.discard(key)
        self.inline_only_sids.discard(key)
        self.phi_source_foldable_sids.discard(key)
        self.prefer_var_expr_sids.add(key)
        if state_write:
            self.must_emit_state_write_sids.add(key)
            info = dict(self.state_write_info.get(key, {}) or {})
            info.update({
                "kind": info.get("kind") or "joint_consumer_exact_state_write",
                "target_sid": key,
                "target_name": name,
                "reason": reason,
            })
            self.state_write_info[key] = info

        # `ssa_policy_by_sid` is emitter-authoritative when present.  Merely
        # repairing var_map/sets after `_build_presentation_metadata()` is not
        # sufficient because a stale pure-inline policy would still suppress
        # or expand this value.  Reassert exact executable custody here; the
        # final_projection pass runs after the presentation classifier.
        self._set_ssa_policy(
            key,
            "joint_consumer_exact_state_write" if state_write
            else "joint_consumer_exact_operand_state",
            emit=True,
            expr_mode="var",
            reason=reason,
            target_name=name,
        )
        self.preferred_expr_by_sid[key] = {
            "mode": "var",
            "target_name": name,
            "joint_consumer_exact_projection": True,
        }
        return key

    def _projection_update_phi_owners_v28(
        self, sid, name, reason, finalize=False,
    ):
        """Update PHI target naming and preserve exactly one execution owner.

        Before alias planning, only the target name is refreshed.  During the
        final pass, an accepted source-state alias remains the owner; otherwise
        the predecessor-local drop-in is made non-suppressible.  This avoids
        emitting both the aliased source write and the same PHI transition.
        """
        owned = []
        sid_text = self._projection_sid_text_v28(sid)
        for rec in list(self.phi_dropins or []):
            if self._projection_sid_text_v28(rec.get("target_sid")) != sid_text:
                continue

            rec["target_name"] = name
            rec["joint_consumer_exact_projection"] = True
            if not finalize:
                continue

            source_sid = rec.get("source_sid")
            alias_owned = bool(
                rec.get("source_aliased_to_target")
                or rec.get("accounted_for_by_state_alias")
                or source_sid in self.state_transition_alias_sids
            )
            rid = self._phi_record_id(rec)

            if alias_owned:
                for table in (
                    self.state_transition_aliases,
                    self.phi_source_aliases,
                    self.temp_phi_source_aliases,
                    self.post_update_aliases,
                ):
                    info = table.get(source_sid)
                    if isinstance(info, dict):
                        info["target_name"] = name
                source_key = self._projection_var_map_key_v28(source_sid)
                if source_key is not None:
                    self._projection_mark_visible_v28(
                        source_key,
                        name,
                        "source-state alias owns exact projected PHI transition",
                        state_write=True,
                    )
                rec["source_aliased_to_target"] = True
                rec["dropin_required"] = False
                rec["dropin_suppressed_reason"] = (
                    "exact projected source-state alias owns transition"
                )
                self.required_phi_dropin_ids.discard(rid)
                self.non_suppressible_dropin_ids.discard(rid)
                self.path_local_phi_dropin_ids.discard(rid)
                self.required_phi_dropin_records = [
                    item for item in self.required_phi_dropin_records
                    if item.get("id") != rid
                ]
                self.non_suppressible_dropin_records = [
                    item for item in self.non_suppressible_dropin_records
                    if item.get("id") != rid
                ]
                continue

            rec["dropin_required"] = True
            rec["dropin_scope"] = rec.get("dropin_scope") or (
                "joint_consumer_exact_operand_state"
            )
            rec["required_reason"] = reason
            rec["must_print_override"] = True
            rec["must_print_reason"] = reason
            rec.pop("source_aliased_to_target", None)
            rec.pop("accounted_for_by_state_alias", None)
            rec.pop("dropin_suppressed_reason", None)
            self.required_phi_dropin_ids.add(rid)
            self.non_suppressible_dropin_ids.add(rid)
            if source_sid is not None:
                self.executable_dropin_source_sids.add(source_sid)
            owned.append(rid)
        return owned

    def _projection_protect_lineage_v28(
        self, operand, storage_key, name, rec, stage,
    ):
        reason = (
            "SemanticGraph exact consumer operand requires distinct "
            "stack-state identity"
        )
        lineage = self._projection_lineage_v28(operand, storage_key)
        protected = []
        phi_owners = []

        for sid, node, var in lineage:
            opcode = getattr(node, "opcode", None) if node is not None else None
            direct_stack = self._concrete_stack_key_v28(var) == storage_key
            state_write = bool(
                direct_stack
                and opcode is not None
                and opcode not in ("MULTIEQUAL",)
            )
            key = self._projection_mark_visible_v28(
                sid, name, reason, state_write=state_write
            )
            if key is None:
                continue
            protected.append(key)

            if opcode == "COPY" and direct_stack:
                self.real_local_copy_sids.add(key)
                copy_info = dict(self.real_local_copy_info.get(key, {}) or {})
                copy_info.update({
                    "target_sid": key,
                    "target_name": name,
                    "reason": "joint_consumer_exact_snapshot_copy_v28",
                })
                self.real_local_copy_info[key] = copy_info

            if opcode == "MULTIEQUAL":
                phi_owners.extend(
                    self._projection_update_phi_owners_v28(
                        key,
                        name,
                        reason,
                        finalize=(stage == "final_projection"),
                    )
                )

            try:
                if node is not None:
                    node.no_inline = True
                    node.materialize = True
                    node.prefer_var_expr = True
                    node.semantic_role = (
                        getattr(node, "semantic_role", None)
                        or "joint_consumer_exact_operand_state"
                    )
                if var is not None:
                    var.no_inline = True
                    var.materialize = True
            except Exception:
                pass

        return protected, phi_owners

    def _projection_result_for_consumer_v28(self, consumer, operand_names):
        if consumer is None:
            return None
        out = getattr(consumer, "var", None)
        key = self._concrete_stack_key_v28(out)
        if key is None:
            return None
        name = self._projection_name_for_stack_key_v28(key)
        sid = self.sid_of(consumer)
        if sid is None or not name:
            return None

        actual = self._projection_mark_visible_v28(
            sid,
            name,
            "noncommutative joint-consumer result owns distinct stack cell",
            state_write=True,
        )
        if actual is None:
            return None
        self.joint_consumer_result_projection_names[
            self._projection_sid_text_v28(sid)
        ] = name
        return {
            "consumer_sid": self._projection_sid_text_v28(sid),
            "storage_key": key,
            "projection_name": name,
            "operand_names": list(operand_names),
        }

    def _apply_joint_consumer_stack_projections_v28(self, stage):
        """Bind SemanticGraph v33 exact contracts to executable state.

        v27 accidentally ignored ``operand_projection_contracts`` and gated on
        compatibility maps that v33 intentionally leaves empty.  v28 validates
        every contract against the live consumer and then applies names only to
        the proved operand lineage and, when concrete, the consumer result.
        """
        contracts = self._projection_contract_records_v28()
        if not contracts:
            self.joint_consumer_stack_projection_events.append({
                "kind": "joint_consumer_exact_projection_inactive_v28",
                "version": self.JOINT_CONSUMER_STACK_PROJECTION_VERSION,
                "stage": stage,
                "reason": "no_exact_consumer_operand_contracts",
                "legacy_storage_projection_keys": len(
                    self.joint_consumer_storage_projection_names
                ),
                "legacy_sid_projection_names": len(
                    self.joint_consumer_sid_projection_names
                ),
            })
            return 0

        changed = []
        grouped = {}
        for rec in contracts:
            grouped.setdefault(rec.get("consumer_sid"), []).append(rec)

        for consumer_sid, records in grouped.items():
            consumer = self._projection_node_for_sid_v28(consumer_sid)
            if consumer is None:
                self.joint_consumer_stack_projection_warnings.append({
                    "kind": "joint_consumer_missing_consumer_v28",
                    "consumer_sid": consumer_sid,
                    "stage": stage,
                })
                continue

            inputs = list(getattr(consumer, "inputs", []) or [])
            operand_names = []
            finalized = []
            for rec in records:
                index = rec.get("operand_index")
                if index is None or index < 0 or index >= len(inputs):
                    self.joint_consumer_stack_projection_warnings.append({
                        "kind": "joint_consumer_operand_index_invalid_v28",
                        "consumer_sid": consumer_sid,
                        "operand_index": index,
                        "input_count": len(inputs),
                        "stage": stage,
                    })
                    continue

                operand = inputs[index]
                actual_sid = self._projection_sid_text_v28(self.sid_of(operand))
                expected_sid = self._projection_sid_text_v28(rec.get("source_sid"))
                actual_key = self._projection_source_key_v28(operand)
                expected_key = self._normalize_projection_stack_key_v28(
                    rec.get("storage_key")
                )
                name = rec.get("projection_name")

                if actual_sid != expected_sid or actual_key != expected_key or not name:
                    self.joint_consumer_stack_projection_warnings.append({
                        "kind": "joint_consumer_contract_live_mismatch_v28",
                        "consumer_sid": consumer_sid,
                        "operand_index": index,
                        "expected_source_sid": expected_sid,
                        "actual_source_sid": actual_sid,
                        "expected_storage_key": expected_key,
                        "actual_storage_key": actual_key,
                        "projection_name": name,
                        "stage": stage,
                    })
                    continue

                before_key = self._projection_var_map_key_v28(actual_sid)
                before = self.var_map.get(before_key)
                protected, phi_owners = self._projection_protect_lineage_v28(
                    operand, expected_key, str(name), rec, stage
                )
                actual_key_sid = self._projection_var_map_key_v28(actual_sid)
                self.joint_consumer_exact_operand_sids.add(actual_key_sid)
                self.joint_consumer_exact_operand_sids.add(str(actual_key_sid))
                after = self.var_map.get(actual_key_sid)
                operand_names.append(after)

                final = dict(rec)
                final.update({
                    "live_source_sid": actual_sid,
                    "live_storage_key": actual_key,
                    "final_var_map_key": actual_key_sid,
                    "final_name": after,
                    "protected_lineage_sids": list(protected),
                    "owned_phi_dropin_ids": list(phi_owners),
                    "stage": stage,
                    "execution_custody": "exact_operand_lineage_materialized",
                })
                self.joint_consumer_final_operand_contracts[
                    (consumer_sid, index)
                ] = final
                finalized.append(final)
                if before != after:
                    changed.append({
                        "consumer_sid": consumer_sid,
                        "operand_index": index,
                        "source_sid": actual_sid,
                        "before": before,
                        "after": after,
                        "storage_key": actual_key,
                    })

            result = self._projection_result_for_consumer_v28(
                consumer, operand_names
            )
            self.joint_consumer_stack_projection_events.append({
                "kind": "joint_consumer_exact_projection_applied_v28",
                "version": self.JOINT_CONSUMER_STACK_PROJECTION_VERSION,
                "stage": stage,
                "consumer_sid": consumer_sid,
                "consumer_opcode": getattr(consumer, "opcode", None),
                "operand_contracts": len(records),
                "finalized_contracts": len(finalized),
                "operand_names": list(operand_names),
                "result_projection": result,
            })

        return len(changed)

    def _audit_joint_consumer_stack_projections_v28(self):
        contracts = self._projection_contract_records_v28()
        failures = []
        details = []
        grouped_names = {}

        for rec in contracts:
            consumer_sid = rec.get("consumer_sid")
            index = rec.get("operand_index")
            consumer = self._projection_node_for_sid_v28(consumer_sid)
            detail = {
                "consumer_sid": consumer_sid,
                "operand_index": index,
                "expected_source_sid": self._projection_sid_text_v28(
                    rec.get("source_sid")
                ),
                "expected_storage_key": self._normalize_projection_stack_key_v28(
                    rec.get("storage_key")
                ),
                "expected_name": rec.get("projection_name"),
            }
            if consumer is None:
                detail["failure"] = "consumer_missing"
                failures.append(dict(detail))
                details.append(detail)
                continue

            inputs = list(getattr(consumer, "inputs", []) or [])
            if index is None or index < 0 or index >= len(inputs):
                detail["failure"] = "operand_index_invalid"
                detail["input_count"] = len(inputs)
                failures.append(dict(detail))
                details.append(detail)
                continue

            operand = inputs[index]
            actual_sid = self._projection_sid_text_v28(self.sid_of(operand))
            actual_storage = self._projection_source_key_v28(operand)
            map_key = self._projection_var_map_key_v28(actual_sid)
            actual_name = self.var_map.get(map_key)
            detail.update({
                "actual_source_sid": actual_sid,
                "actual_storage_key": actual_storage,
                "var_map_key": map_key,
                "actual_name": actual_name,
                "materialized": map_key in self.materialize_sids,
                "not_suppressed": map_key not in self.suppress_assign_sids,
                "not_inline_only": map_key not in self.inline_only_sids,
                "prefer_var_expr": map_key in self.prefer_var_expr_sids,
            })

            gates = {
                "source_sid_matches": actual_sid == detail["expected_source_sid"],
                "storage_key_matches": actual_storage == detail["expected_storage_key"],
                "name_matches": actual_name == detail["expected_name"],
                "materialized": detail["materialized"],
                "not_suppressed": detail["not_suppressed"],
                "not_inline_only": detail["not_inline_only"],
            }
            detail["gates"] = gates
            failed = [name for name, ok in gates.items() if not ok]
            if failed:
                detail["failed_gates"] = failed
                failures.append(dict(detail))

            grouped_names.setdefault(consumer_sid, []).append({
                "operand_index": index,
                "name": actual_name,
                "storage_key": actual_storage,
            })
            details.append(detail)

        noncommutative = {
            "INT_SUB", "INT_DIV", "INT_SDIV", "INT_REM", "INT_SREM",
            "INT_LEFT", "INT_RIGHT", "INT_SRIGHT",
            "INT_LESS", "INT_SLESS", "INT_LESSEQUAL", "INT_SLESSEQUAL",
        }
        for consumer_sid, items in grouped_names.items():
            consumer = self._projection_node_for_sid_v28(consumer_sid)
            opcode = getattr(consumer, "opcode", None) if consumer is not None else None
            distinct_storage = {
                item.get("storage_key") for item in items
                if item.get("storage_key") is not None
            }
            names = [item.get("name") for item in items]
            if (
                opcode in noncommutative
                and len(distinct_storage) > 1
                and len(set(names)) != len(names)
            ):
                failures.append({
                    "consumer_sid": consumer_sid,
                    "consumer_opcode": opcode,
                    "reason": "distinct_noncommutative_operands_still_share_name",
                    "operands": items,
                })

            result_name = self.joint_consumer_result_projection_names.get(
                str(consumer_sid)
            )
            if result_name:
                result_key = self._projection_var_map_key_v28(consumer_sid)
                result_gates = {
                    "name_matches": self.var_map.get(result_key) == result_name,
                    "materialized": result_key in self.materialize_sids,
                    "not_suppressed": result_key not in self.suppress_assign_sids,
                    "must_emit_state_write": result_key in self.must_emit_state_write_sids,
                }
                if not all(result_gates.values()):
                    failures.append({
                        "consumer_sid": consumer_sid,
                        "reason": "consumer_result_state_custody_failed",
                        "expected_name": result_name,
                        "actual_name": self.var_map.get(result_key),
                        "gates": result_gates,
                    })

        active = bool(contracts)
        if active and not details:
            failures.append({
                "reason": "exact_contracts_present_but_zero_checked",
                "contract_count": len(contracts),
            })

        self.joint_consumer_stack_projection_audit = {
            "kind": (
                "joint_consumer_exact_projection_verified_v28"
                if not failures else
                "joint_consumer_exact_projection_failed_v28"
            ),
            "version": self.JOINT_CONSUMER_STACK_PROJECTION_VERSION,
            "active": active,
            "input_contracts": len(contracts),
            "checked_contracts": len(details),
            "finalized_contracts": len(
                self.joint_consumer_final_operand_contracts
            ),
            "protected_operand_sids": sorted(
                self.joint_consumer_exact_operand_sids, key=str
            ),
            "protected_lineage_sids": sorted(
                self.joint_consumer_projection_lineage_sids, key=str
            ),
            "result_projections": dict(
                self.joint_consumer_result_projection_names
            ),
            "details": details,
            "warnings": list(self.joint_consumer_stack_projection_warnings),
            "failures": failures,
            "acceptance_gate": (
                "every exact consumer contract matches live operand identity, "
                "survives final var_map, remains materialized, and leaves "
                "noncommutative distinct operands textually distinct"
            ),
        }
        self.joint_consumer_stack_projection_events.append(
            dict(self.joint_consumer_stack_projection_audit)
        )
        if failures:
            raise RuntimeError(
                "PALPHIfolder v28 exact consumer projection custody failed: %s"
                % failures
            )
        return self.joint_consumer_stack_projection_audit

    # Compatibility wrappers for pipeline integrations that still call the
    # v27 helper/method names directly.
    def _projection_sid_text_v27(self, value):
        return self._projection_sid_text_v28(value)

    def _projection_name_for_sid_v27(self, sid):
        text = self._projection_sid_text_v28(sid)
        if text is None:
            return None
        return self.joint_consumer_sid_projection_names.get(text)

    def _apply_joint_consumer_stack_projections_v27(self, stage):
        return self._apply_joint_consumer_stack_projections_v28(stage)

    def _audit_joint_consumer_stack_projections_v27(self):
        return self._audit_joint_consumer_stack_projections_v28()

    @staticmethod
    def _sid_text_v26(sid):
        if sid is None:
            return None
        return str(sid)

    def _snapshot_temp_name_v26(self, sid, forbidden_name=None):
        """Return a deterministic Python identity for a preserved SSA epoch."""

        raw = self._sanitize_name(self._sid_text_v26(sid))
        if not raw:
            raw = "v_snapshot"

        if not raw.startswith(("v_", "c_")):
            raw = "v_%s" % raw

        forbidden = {
            str(forbidden_name)
            for forbidden_name in (forbidden_name,)
            if forbidden_name not in (None, "")
        }
        forbidden.update(
            str(value)
            for key, value in (self.var_map or {}).items()
            if key != sid and value not in (None, "")
        )

        if raw not in forbidden:
            return raw

        base = raw + "__snapshot"
        candidate = base
        ordinal = 2
        while candidate in forbidden:
            candidate = "%s_%d" % (base, ordinal)
            ordinal += 1
        return candidate

    def _candidate_alias_target_name_v26(self, rec):
        """Return the target name of a structurally eligible alias candidate.

        This is intentionally narrower than `_can_alias_phi_source_to_target`
        and contains no use-count decision.  It is used only to see aliases
        that may be accepted later in iteration order, so the current source
        can be protected before two distinct epochs collapse.
        """

        if not isinstance(rec, dict):
            return None

        source_sid = rec.get("source_sid")
        target_sid = rec.get("target_sid")
        source_node = rec.get("source_node")
        target = rec.get("target")
        source = rec.get("source") or rec.get("source_var")

        if source_sid is None or target_sid is None or source_node is None:
            return None
        if source_sid in self.distinct_ssa_snapshot_sids:
            return None
        if rec.get("multiway_case_edge_dropin"):
            return None
        if self._abi_sid_v23(source_sid) in self.abi_entry_root_sids:
            return None

        target_is_local = self.is_stack_local(target)
        target_is_temp_selector = target_sid in self.used_temp_phi_target_sids
        if not (target_is_local or target_is_temp_selector):
            return None

        if self.is_stack_local(source):
            return None

        source_var = self.to_var(source)
        if source_var is not None:
            if getattr(source_var, "is_parameter", False):
                return None
            if getattr(source_var, "is_global", False):
                return None
            if getattr(source_var, "is_function", False):
                return None
            if getattr(source_var, "is_constant", False):
                return None

        if source_sid in self.protected_copy_temp_sids:
            return None
        if source_sid in self.real_local_copy_sids:
            return None
        if source_sid in self.selector_passthrough_dropin_sids:
            return None
        if source_sid in self.required_call_result_sids:
            return None

        return (
            rec.get("target_name")
            or self.name_for_var(target)
            or self.var_map.get(target_sid)
        )

    def _candidate_alias_targets_for_sid_v26(self, sid):
        targets = set()
        if sid is None or sid in self.distinct_ssa_snapshot_sids:
            return targets

        for rec in list(self.phi_dropins or []):
            if rec.get("source_sid") != sid:
                continue
            target_name = self._candidate_alias_target_name_v26(rec)
            if target_name:
                targets.add(str(target_name))
        return targets

    def _consumer_identity_v26(self, consumer):
        sid = self.sid_of(consumer)
        plan = self._compute_plan_for_sid_v21(sid)
        op_key = plan.get("op_key") if isinstance(plan, dict) else None

        if op_key is None:
            for attr in ("op_key", "op_id", "id"):
                value = getattr(consumer, attr, None)
                if value is not None:
                    op_key = value
                    break

        return {
            "consumer_sid": sid,
            "consumer_op_key": op_key,
            "consumer_opcode": getattr(consumer, "opcode", None),
            "consumer_block_addr": self._node_block_addr(consumer),
        }

    def _distinct_ssa_alias_collision_v26(
        self,
        rec,
        include_candidate_aliases=True,
    ):
        """Return exact simultaneous-consumer evidence for an unsafe alias."""

        source_sid = rec.get("source_sid")
        target_name = self._candidate_alias_target_name_v26(rec)
        if source_sid is None or not target_name:
            return None

        collisions = []
        for consumer in self._consumer_nodes_for_sid(source_sid):
            if consumer is None:
                continue
            if getattr(consumer, "opcode", None) == "MULTIEQUAL":
                continue

            inputs = list(getattr(consumer, "inputs", []) or [])
            source_positions = [
                index
                for index, value in enumerate(inputs)
                if self.sid_of(value) == source_sid
            ]
            if not source_positions:
                continue

            for peer_position, peer in enumerate(inputs):
                peer_sid = self.sid_of(peer)
                if peer_sid is None or peer_sid == source_sid:
                    continue
                if self.is_const(peer):
                    continue

                peer_names = set()
                peer_name = (
                    self.var_map.get(peer_sid)
                    or self.name_for_var(self.to_var(peer))
                )
                if peer_name:
                    peer_names.add(str(peer_name))

                if include_candidate_aliases:
                    peer_names.update(
                        self._candidate_alias_targets_for_sid_v26(peer_sid)
                    )

                if str(target_name) not in peer_names:
                    continue

                identity = self._consumer_identity_v26(consumer)
                identity.update({
                    "source_sid": source_sid,
                    "source_positions": list(source_positions),
                    "source_candidate_target": str(target_name),
                    "peer_sid": peer_sid,
                    "peer_position": peer_position,
                    "peer_projection_candidates": sorted(peer_names),
                    "distinct_ssa_inputs": source_sid != peer_sid,
                    "simultaneous_consumer": True,
                    "candidate_aliases_included": bool(
                        include_candidate_aliases
                    ),
                })
                collisions.append(identity)

        if not collisions:
            return None

        return {
            "kind": "phi_distinct_ssa_operand_alias_collision_v26",
            "version": self.DISTINCT_SSA_SNAPSHOT_VERSION,
            "source_sid": source_sid,
            "target_sid": rec.get("target_sid"),
            "target_name": str(target_name),
            "pred_addr": rec.get("pred_addr"),
            "join_addr": rec.get("join_addr"),
            "collisions": collisions,
            "reason": (
                "global_phi_source_alias_would_collapse_distinct_"
                "simultaneously_consumed_ssa_epochs"
            ),
        }

    def _register_distinct_ssa_snapshot_v26(self, rec, collision):
        """Preserve one SSA epoch as a real temporary and local PHI drop-in."""

        source_sid = rec.get("source_sid")
        target_name = (
            rec.get("target_name")
            or self.name_for_var(rec.get("target"))
            or self.var_map.get(rec.get("target_sid"))
        )
        key = (
            source_sid,
            rec.get("target_sid"),
            rec.get("pred_addr"),
            rec.get("join_addr"),
        )

        if source_sid in self.distinct_ssa_snapshot_sids:
            return self.distinct_ssa_snapshot_info.get(source_sid)
        if key in self.distinct_ssa_snapshot_rejection_keys:
            return self.distinct_ssa_snapshot_info.get(source_sid)

        self.distinct_ssa_snapshot_rejection_keys.add(key)
        snapshot_name = self._snapshot_temp_name_v26(
            source_sid,
            forbidden_name=target_name,
        )

        self.distinct_ssa_snapshot_sids.add(source_sid)
        self.var_map[source_sid] = snapshot_name

        self.phi_source_foldable_sids.discard(source_sid)
        self.inline_only_sids.discard(source_sid)
        self.suppress_assign_sids.discard(source_sid)
        self.materialize_sids.add(source_sid)
        self.phi_source_alias_sids.discard(source_sid)
        self.temp_phi_source_alias_sids.discard(source_sid)
        self.state_transition_alias_sids.discard(source_sid)
        self.state_transition_aliases.pop(source_sid, None)
        self.dropin_suppressed_by_source_alias.discard(source_sid)

        source_node = rec.get("source_node")
        try:
            source_node.no_inline = True
            source_node.materialize = True
            source_node.semantic_role = (
                getattr(source_node, "semantic_role", None)
                or "distinct_ssa_snapshot"
            )
            source_node.var.no_inline = True
            source_node.var.materialize = True
        except Exception:
            pass

        owned_records = []
        for candidate in list(self.phi_dropins or []):
            if candidate.get("source_sid") != source_sid:
                continue

            candidate_target = (
                candidate.get("target_name")
                or self.name_for_var(candidate.get("target"))
                or self.var_map.get(candidate.get("target_sid"))
            )
            if target_name and candidate_target and candidate_target != target_name:
                continue

            candidate["distinct_ssa_snapshot_source"] = True
            candidate["distinct_ssa_snapshot_name"] = snapshot_name
            candidate["dropin_required"] = True
            candidate["dropin_scope"] = (
                "distinct_ssa_snapshot_predecessor"
            )
            candidate["required_reason"] = (
                "distinct SSA epoch must remain materialized until "
                "simultaneous consumer"
            )
            candidate["must_print_override"] = True
            candidate["must_print_reason"] = (
                "prevent_distinct_ssa_operand_identity_collapse"
            )
            candidate.pop("source_aliased_to_target", None)
            candidate.pop("accounted_for_by_state_alias", None)
            candidate.pop("dropin_suppressed_reason", None)

            record_id = self._phi_record_id(candidate)
            self.required_phi_dropin_ids.add(record_id)
            self.non_suppressible_dropin_ids.add(record_id)
            self.executable_dropin_source_sids.add(source_sid)
            owned_records.append(record_id)

        info = {
            "kind": "phi_distinct_ssa_snapshot_contract_v26",
            "version": self.DISTINCT_SSA_SNAPSHOT_VERSION,
            "source_sid": source_sid,
            "snapshot_name": snapshot_name,
            "target_sid": rec.get("target_sid"),
            "target_name": target_name,
            "pred_addr": rec.get("pred_addr"),
            "join_addr": rec.get("join_addr"),
            "source_opcode": getattr(source_node, "opcode", None),
            "owned_phi_dropin_ids": owned_records,
            "collision": dict(collision or {}),
            "execution_policy": (
                "materialize_source_epoch_once_then_use_snapshot_"
                "identity_at_joint_consumer"
            ),
            "alias_policy": "global_source_to_target_alias_rejected",
            "authority": (
                "semantic_consumer_input_SIDs_plus_PHIfolder_"
                "candidate_projection"
            ),
        }
        self.distinct_ssa_snapshot_info[source_sid] = info
        self.distinct_ssa_operand_contracts.append(info)

        for item in list((collision or {}).get("collisions", []) or []):
            consumer_key = (
                item.get("consumer_op_key")
                or item.get("consumer_sid")
                or (
                    item.get("consumer_block_addr"),
                    item.get("consumer_opcode"),
                )
            )
            self.distinct_ssa_operand_contracts_by_consumer.setdefault(
                consumer_key, []
            ).append(info)

        event = {
            "kind": "phi_distinct_ssa_source_alias_rejected_v26",
            "version": self.DISTINCT_SSA_SNAPSHOT_VERSION,
            "source_sid": source_sid,
            "snapshot_name": snapshot_name,
            "target_sid": rec.get("target_sid"),
            "target_name": target_name,
            "pred_addr": rec.get("pred_addr"),
            "join_addr": rec.get("join_addr"),
            "collision_count": len(
                list((collision or {}).get("collisions", []) or [])
            ),
            "reason": info.get("alias_policy"),
        }
        self.distinct_ssa_snapshot_events.append(event)
        return info

    def _audit_distinct_ssa_snapshot_custody_v26(self):
        """Fail closed if a v26 snapshot is later re-aliased or suppressed."""

        failures = []

        for sid in sorted(self.distinct_ssa_snapshot_sids, key=str):
            info = self.distinct_ssa_snapshot_info.get(sid, {})
            gates = {
                "has_unique_snapshot_name": bool(
                    info.get("snapshot_name")
                    and info.get("snapshot_name") != info.get("target_name")
                ),
                "materialized": sid in self.materialize_sids,
                "not_suppressed": sid not in self.suppress_assign_sids,
                "not_inline_only": sid not in self.inline_only_sids,
                "not_phi_source_aliased": sid not in self.phi_source_alias_sids,
                "not_state_transition_aliased": (
                    sid not in self.state_transition_alias_sids
                ),
                "dropin_owner_present": bool(
                    info.get("owned_phi_dropin_ids")
                ),
            }
            failed = [
                name for name, accepted in gates.items() if not accepted
            ]
            if failed:
                failures.append({
                    "source_sid": sid,
                    "snapshot_name": info.get("snapshot_name"),
                    "failed_gates": failed,
                    "gates": gates,
                })

        # Audit aliases that survived for an actual, not merely candidate,
        # projection collision.
        for source_sid in sorted(self.phi_source_alias_sids, key=str):
            for rec in list(self.phi_dropins or []):
                if rec.get("source_sid") != source_sid:
                    continue
                collision = self._distinct_ssa_alias_collision_v26(
                    rec,
                    include_candidate_aliases=False,
                )
                if collision:
                    failures.append({
                        "source_sid": source_sid,
                        "reason": "accepted_alias_still_collapses_actual_operands",
                        "collision": collision,
                    })

        audit = {
            "kind": (
                "phi_distinct_ssa_snapshot_custody_verified_v26"
                if not failures
                else "phi_distinct_ssa_snapshot_custody_failed_v26"
            ),
            "version": self.DISTINCT_SSA_SNAPSHOT_VERSION,
            "active": bool(self.distinct_ssa_snapshot_sids),
            "protected_snapshot_sids": sorted(
                self.distinct_ssa_snapshot_sids,
                key=str,
            ),
            "contracts": len(self.distinct_ssa_operand_contracts),
            "consumer_keys": len(
                self.distinct_ssa_operand_contracts_by_consumer
            ),
            "alias_rejections": len(
                self.distinct_ssa_snapshot_events
            ),
            "failures": failures,
            "rule": (
                "distinct_SSA_inputs_at_one_consumer_must_not_share_"
                "one_rendered_PHI_target_without_equivalence_proof"
            ),
        }
        self.distinct_ssa_snapshot_audit = audit
        self.distinct_ssa_snapshot_events.append(dict(audit))

        if failures:
            raise RuntimeError(
                "PALPHIfolder v26 distinct SSA snapshot custody failed: %s"
                % failures
            )

        return audit


    def _can_alias_phi_source_to_target(self, rec):
        target = rec.get("target")
        source = rec.get("source") or rec.get("source_var")
        source_sid = rec.get("source_sid")
        target_sid = rec.get("target_sid")
        source_node = rec.get("source_node")

        if source_sid is None or target_sid is None or source_node is None:
            return False

        # v24: a resolved multiway case edge is an explicit predecessor-local
        # execution scope.  Global source->target aliasing would erase the edge
        # identity that SGL's ExecCase and the emitter must retain.
        if rec.get("multiway_case_edge_dropin"):
            self.multiway_case_edge_events.append({
                "kind": "phi_multiway_case_edge_source_alias_rejected_v24",
                "dispatcher": rec.get("multiway_dispatcher"),
                "case_target": rec.get("multiway_case_target"),
                "join_addr": rec.get("join_addr"),
                "pred_addr": rec.get("pred_addr"),
                "target_sid": self._multiway_sid_v24(target_sid),
                "source_sid": self._multiway_sid_v24(source_sid),
                "reason": "case_edge_predecessor_custody_requires_local_dropin",
            })
            return False

        # ABI-F: a physical/logical/implicit function-entry SID is an
        # immutable live-in execution root.  Renaming it globally to a PHI
        # target makes paths that have not executed that target appear defined
        # and is the structural source of the v_789 class of defect.
        if self._abi_sid_v23(source_sid) in self.abi_entry_root_sids:
            event = {
                "kind": "phi_abi_entry_root_source_alias_rejected_v23",
                "version": self.ABI_ENTRY_CUSTODY_VERSION,
                "source_sid": self._abi_sid_v23(source_sid),
                "target_sid": self._abi_sid_v23(target_sid),
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": "immutable_ABI_entry_root_cannot_be_globally_renamed",
            }
            marker = (
                event.get("source_sid"), event.get("target_sid"),
                event.get("pred_addr"), event.get("join_addr"),
            )
            if marker not in {
                (
                    item.get("source_sid"), item.get("target_sid"),
                    item.get("pred_addr"), item.get("join_addr"),
                )
                for item in self.abi_entry_source_alias_rejections
            }:
                self.abi_entry_source_alias_rejections.append(event)
            return False

        # Target must be a real local transition target or a used temp selector.
        target_is_local = self.is_stack_local(target)
        target_is_temp_selector = target_sid in self.used_temp_phi_target_sids

        if not (target_is_local or target_is_temp_selector):
            return False

        # Never alias real storage-bearing sources; those are actual variables.
        if self.is_stack_local(source):
            return False

        sv = self.to_var(source)
        if sv is not None:
            if getattr(sv, "is_parameter", False):
                return False
            if getattr(sv, "is_global", False):
                return False
            if getattr(sv, "is_function", False):
                return False
            if getattr(sv, "is_constant", False):
                return False

        if source_sid in self.protected_copy_temp_sids:
            return False

        if source_sid in self.real_local_copy_sids:
            return False

        if self._erase_emperor_is_snapshot_sid_v29(source_sid):
            self.erase_emperor_snapshot_events_v29.append({
                "kind": "erase_emperor_snapshot_source_alias_rejected_v29",
                "source_sid": self._erase_emperor_sid_text_v29(source_sid),
                "target_sid": self._erase_emperor_sid_text_v29(target_sid),
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": "temporal_snapshot_cannot_be_globally_renamed",
            })
            return False

        if self._erase_emperor_is_derived_result_sid_v29(source_sid):
            self._record_erase_emperor_derived_alias_rejection_v29(
                source_sid,
                target_sid,
                "phi_source_alias",
                pred_addr=rec.get("pred_addr"),
                join_addr=rec.get("join_addr"),
            )
            return False

        # v20k: a transparent arm of a used selector PHI is deliberately
        # carried by a required predecessor-local drop-in.  Do not convert it
        # back into a suppressible source alias.
        if source_sid in self.selector_passthrough_dropin_sids:
            return False

        # v19: a call result that is part of a branch-condition dependency
        # is an execution value, not a presentation bridge.  Do not rename it
        # into a PHI target or suppress its normal materialization.
        if source_sid in self.required_call_result_sids:
            return False

        opcode = getattr(source_node, "opcode", None)

        # v28: SemanticGraph exact-consumer operand custody is already proven
        # against a concrete consumer index.  A later global PHI source alias
        # must not erase that executable identity.
        if self._projection_sid_is_protected_v28(source_sid):
            self.joint_consumer_stack_projection_events.append({
                "kind": "joint_consumer_source_alias_rejected_v28",
                "source_sid": source_sid,
                "target_sid": target_sid,
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "reason": "exact_consumer_operand_lineage_has_executable_custody",
            })
            return False

        # v26: global source->target aliasing is forbidden when this source is
        # simultaneously consumed beside another distinct SSA epoch that
        # already projects, or may later project, to the same target name.
        if source_sid in self.distinct_ssa_snapshot_sids:
            return False

        collision = self._distinct_ssa_alias_collision_v26(
            rec,
            include_candidate_aliases=True,
        )
        if collision:
            self._register_distinct_ssa_snapshot_v26(rec, collision)
            return False

        total_uses = self.use_counts.get(source_sid, 0)
        phi_uses = self.phi_source_counts.get(source_sid, 0)
        non_phi_uses = max(0, total_uses - phi_uses)

        if opcode in self.CALL_OPS:
            # Calls must not be duplicated.  Alias when the only real consumer
            # is the PHI transition itself, or when remaining consumers are
            # conditionish tests of the freshly written value.
            if total_uses <= phi_uses:
                return True

            if target_is_local and self._uses_are_same_block_conditionish(source_sid, source_node):
                return True

            return False

        if opcode in self.PURE_INLINE_OPS:
            # Pure expressions can be aliased even when the extra use is a
            # tail/condition compare, e.g. v_367 feeds local_14 and v_436.
            # Mapping v_367 -> local_14 lets the condition observe the updated
            # counter instead of re-expanding local_14 + 1 after the update.
            if self._is_post_update_alias_record(rec):
                return self._post_update_extra_uses_are_conditionish(source_sid)
            if non_phi_uses <= 1:
                return True
            return total_uses <= phi_uses

        return total_uses <= phi_uses

    def _post_update_extra_uses_are_conditionish(self, source_sid):
        """
        Safety check for post-update aliases with more than one non-PHI use.
        Accept only compare/condition consumers.  This keeps the v_367 class
        safe without opening arbitrary expression rewrites.
        """
        if source_sid is None:
            return False

        consumers = self._consumer_nodes_for_sid(source_sid)
        if not consumers:
            return True

        for cn in consumers:
            opcode = getattr(cn, "opcode", None)

            # A source may appear in its own bookkeeping; ignore impossible or
            # absent nodes conservatively.
            if cn is None:
                continue

            if opcode in self.COMPARE_OPS:
                continue

            if self.is_condition(cn):
                continue

            # Transparent bridges feeding a condition are acceptable; the
            # downstream condition pass will catch the compare node too.
            if opcode in self.TRANSPARENT_OPS:
                continue

            return False

        return True

    def _protect_snapshot_copy_temps(self):
        """
        Protect temp snapshots created from stack locals.

        Pattern:
            COPY [local_20] -> v_4658
            COPY [local_1c] -> local_20
            COPY [v_4658]  -> local_1c

        v_4658 is not a transparent bridge.  It is a snapshot required to keep
        swap semantics after local_20 is overwritten.  Therefore it must not be
        suppressed by transparent COPY policy.
        """

        for block in getattr(self.func, "blocks", []) or []:
            for op in getattr(block, "ops", []) or []:
                if getattr(op, "opcode", None) != "COPY":
                    continue

                out = getattr(op, "output", None)
                inputs = list(getattr(op, "inputs", []) or [])
                if not inputs or out is None:
                    continue

                src = inputs[0]
                sid = self.sid_of(out)

                if sid is None:
                    continue

                # SemanticGraph v35 already owns temporal snapshots with an
                # exact SID projection.  Do not overwrite that stronger
                # contract with the older swap-oriented local-name heuristic.
                if self._erase_emperor_is_snapshot_sid_v29(sid):
                    continue

                # Source must be a real local; output must be a temp/non-local.
                if not self.is_stack_local(src):
                    continue

                if self.is_stack_local(out):
                    continue

                if self.use_counts.get(sid, 0) <= 0:
                    continue

                self.protected_copy_temp_sids.add(sid)
                self.materialize_sids.add(sid)
                self.suppress_assign_sids.discard(sid)
                self.inline_only_sids.discard(sid)

                self.protected_copy_temp_info[sid] = {
                    "block_addr": getattr(block, "addr", None),
                    "source_name": self.name_for_var(self.to_var(src)),
                    "target_name": self.name_for_var(self.to_var(out)) or sid,
                    "reason": "stack_local_snapshot_copy",
                }

    def _protect_real_local_copy_state_writes(self):
        """
        Protect real state-copy operations.

        This pass is deliberately block/op based because the bug class is
        executable state mutation, not formula presentation.

        Examples:
            COPY [local_1c] -> local_20
            COPY [v_4658]  -> local_1c

        These must survive as writes. They are not transparent SSA bridges.
        """

        for block in getattr(self.func, "blocks", []) or []:
            for idx, op in enumerate(getattr(block, "ops", []) or []):
                opcode = getattr(op, "opcode", None)

                if opcode != "COPY":
                    continue

                out = getattr(op, "output", None)
                inputs = list(getattr(op, "inputs", []) or [])

                if out is None or not inputs:
                    continue

                src = inputs[0]
                out_sid = self.sid_of(out)
                src_sid = self.sid_of(src)

                if out_sid is None:
                    continue

                # A write into stack/local storage is an executable state
                # write unless it is a provable self-copy.
                if not self.is_stack_local(out):
                    continue

                if self.same_storage(out, src):
                    continue

                target_name = self.name_for_var(self.to_var(out))
                source_name = self.name_for_var(self.to_var(src))

                self.real_local_copy_sids.add(out_sid)
                self.must_emit_state_write_sids.add(out_sid)
                self.materialize_sids.add(out_sid)
                self.suppress_assign_sids.discard(out_sid)
                self.inline_only_sids.discard(out_sid)

                info = {
                    "block_addr": getattr(block, "addr", None),
                    "op_index": idx,
                    "opcode": opcode,
                    "target_sid": out_sid,
                    "target_name": target_name,
                    "source_sid": src_sid,
                    "source_name": source_name,
                    "reason": "real_local_copy_state_write",
                }

                self.real_local_copy_info[out_sid] = info
                self.state_write_info[out_sid] = {
                    "kind": "real_local_copy",
                    **info,
                }

    def _mark_required_executable_phi_dropins(self):
        """
        v19 bookkeeping: mark PHI transition records that represent real
        predecessor-path state updates.

        The folder does not print them.  It only declares that these records
        are required unless another explicit state-write alias already accounts
        for the same source->target transition.
        """

        for rec in list(self.phi_dropins or []):
            rid = self._phi_record_id(rec)
            source_sid = rec.get("source_sid")
            target_sid = rec.get("target_sid")
            target = rec.get("target")
            source_node = rec.get("source_node")
            opcode = getattr(source_node, "opcode", None) if source_node is not None else None

            if source_sid is None or target_sid is None:
                continue

            target_is_state = bool(self.is_stack_local(target) or target_sid in self.used_temp_phi_target_sids)
            if not target_is_state:
                continue

            # If a normal source op is deliberately aliased to write the PHI
            # target at its own block location, the drop-in may be redundant.
            if source_sid in self.state_transition_alias_sids:
                rec["accounted_for_by_state_alias"] = True
                continue

            # Otherwise this PHI assignment is executable state on this path.
            rec["dropin_required"] = True
            rec["dropin_scope"] = rec.get("dropin_scope") or "executable_phi_transition"
            rec["required_reason"] = "target state requires predecessor transition"
            self.required_phi_dropin_ids.add(rid)
            self.non_suppressible_dropin_ids.add(rid)
            self.executable_dropin_source_sids.add(source_sid)

            self.required_phi_dropin_records.append({
                "id": rid,
                "join_addr": rec.get("join_addr"),
                "pred_addr": rec.get("pred_addr"),
                "target_sid": target_sid,
                "target_name": rec.get("target_name"),
                "source_sid": source_sid,
                "source_name": rec.get("source_name"),
                "source_opcode": opcode,
                "reason": rec.get("required_reason"),
            })

            self.non_suppressible_dropin_records.append({
                "id": rid,
                "join_addr": rec.get("join_addr"),
                "pred_addr": rec.get("pred_addr"),
                "target_sid": target_sid,
                "source_sid": source_sid,
                "reason": "executable phi transition cannot be presentation-suppressed",
            })

    def _suppress_duplicate_alias_dropins(self):
        """
        Final v18c cleanup: if a source op has been aliased to write a PHI
        target directly, every matching drop-in must be treated as redundant.
        This catches duplicate cases where multiple PHI records or shared-tail
        projections refer to the same source/target transition.
        """

        for rec in self.phi_dropins:
            source_sid = rec.get("source_sid")

            if source_sid is None:
                continue

            if source_sid not in self.state_transition_alias_sids:
                continue

            # Suppress only when the normal source op is explicitly contracted
            # to write the PHI target.  Required executable drop-ins without a
            # state alias must remain visible to the emitter.
            rec["source_aliased_to_target"] = True
            rec["dropin_required"] = False
            rec["dropin_suppressed_reason"] = "v19_source_alias_writes_phi_target"
            self.dropin_suppressed_by_source_alias.add(source_sid)

            target_sid = rec.get("target_sid")
            if target_sid is not None:
                self.dropin_suppressed_by_source_alias.add((rec.get("pred_addr"), rec.get("join_addr"), target_sid, source_sid))

    def _finalize_state_write_policy(self):
        """
        Convert accumulated execution-state decisions into SSA policy entries.

        PHIfolder v18's contract:
            - state transition aliases emit where their source op lives
            - real local copies emit where their COPY op lives
            - protected snapshots emit as temps
            - redundant PHI dropins are suppressed only when source alias
              fully accounts for the transition
        """

        for sid in sorted(self.state_transition_alias_sids):
            info = self.state_transition_aliases.get(sid, {})
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)

            cls = "state_transition_alias"
            reason = info.get("reason", "phi source writes target local/temp")
            if sid in self.post_update_alias_sids:
                cls = "post_update_state_alias"
                reason = self.post_update_aliases.get(sid, {}).get("reason", reason)
                self.prefer_var_expr_sids.add(sid)

            self._set_ssa_policy(
                sid,
                cls,
                emit=True,
                expr_mode="var",
                reason=reason,
                target_name=info.get("target_name") or self.var_map.get(sid),
            )

        for sid in sorted(self.real_local_copy_sids):
            info = self.real_local_copy_info.get(sid, {})
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "real_local_copy",
                emit=True,
                expr_mode="var",
                reason=info.get("reason", "real local-to-local state copy"),
                target_name=info.get("target_name") or self.var_map.get(sid),
            )

        for sid in sorted(self.protected_copy_temp_sids):
            info = self.protected_copy_temp_info.get(sid, {})
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "protected_snapshot_copy",
                emit=True,
                expr_mode="var",
                reason=info.get("reason", "snapshot copy required"),
                target_name=info.get("target_name") or self.var_map.get(sid),
            )

        for sid in sorted(self.distinct_ssa_snapshot_sids, key=str):
            info = self.distinct_ssa_snapshot_info.get(sid, {})
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self.phi_source_foldable_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "distinct_ssa_operand_snapshot",
                emit=True,
                expr_mode="var",
                reason=(
                    "distinct SSA epoch remains live beside another "
                    "version at one consumer"
                ),
                target_name=(
                    info.get("snapshot_name")
                    or self.var_map.get(sid)
                ),
            )



    # ---------------------------------------------------------
    # SGL CONDITION-CONSUMER METADATA CLOSURE
    # ---------------------------------------------------------

    def _consume_sgl_condition_consumers(self):
        """
        Consume frozen SGL condition-consumer records.

        Produces:
          - func.condition_temp_defs
          - func.post_update_condition_aliases

        This pass is metadata-only.  It does not mutate the ExecTree and does
        not perform emitter-style text replacement.
        """

        consumers = list(getattr(self, "sgl_condition_consumers", []) or [])
        if not consumers:
            consumers = list(getattr(self.func, "sgl_condition_consumers", []) or [])

        self.condition_temp_defs = []
        self.condition_temp_def_sids = set()
        self.post_update_condition_aliases = []
        self.post_update_condition_alias_sids = set()

        seen_temp = set()
        seen_alias = set()

        for consumer in consumers:
            cond_expr = str(consumer.get("cond_expr") or "")
            cond_sid = consumer.get("cond_sid")
            caddr = consumer.get("addr")

            # 1. v_N condition temps that should be materialized or exactly
            # inlined by the emitter.
            for sid in self._extract_temp_sids_from_condition_expr(cond_expr):
                rec = self._make_condition_temp_def_record(sid, consumer)
                if rec is None:
                    continue
                key = (rec.get("sid"), rec.get("consumer_addr"), rec.get("expr"), rec.get("opcode"))
                if key in seen_temp:
                    continue
                seen_temp.add(key)
                self.condition_temp_defs.append(rec)
                self.condition_temp_def_sids.add(sid)
                self.materialize_sids.add(sid)
                self.suppress_assign_sids.discard(sid)
                self.inline_only_sids.discard(sid)
                self.protected_condition_value_sids.add(sid)

            # 2. Condition root and descendants may consume post-update value
            # aliases already discovered by PHI.
            for rec in self._post_update_alias_records_for_consumer(cond_sid, cond_expr, consumer):
                key = (
                    rec.get("source_sid"),
                    rec.get("consumer_addr"),
                    rec.get("target_name"),
                    rec.get("source_expr"),
                    rec.get("condition_expr"),
                )
                if key in seen_alias:
                    continue
                seen_alias.add(key)
                self.post_update_condition_aliases.append(rec)
                ssid = rec.get("source_sid")
                csid = rec.get("consumer_sid")
                if ssid is not None:
                    self.post_update_condition_alias_sids.add(ssid)
                    self.prefer_var_expr_sids.add(ssid)
                if csid is not None:
                    self.post_update_consumer_sids.add(csid)
                    self.prefer_var_expr_sids.add(csid)

        # 3. SGL same-block state-write closure.  This catches RawCond
        # conditions whose condition-source address is the same block that
        # emitted the update expression, e.g. Sample Y:
        #     block/source addr 0x10129b:
        #       local_14 = local_14 + 1
        #       if 4 < (local_14 + 1)
        for rec in self._sgl_same_block_post_update_alias_records(consumers):
            key = (
                rec.get("source_sid"),
                rec.get("consumer_addr"),
                rec.get("target_name"),
                rec.get("source_expr"),
                rec.get("condition_expr"),
                rec.get("producer_addr"),
            )
            if key in seen_alias:
                continue
            seen_alias.add(key)
            self.post_update_condition_aliases.append(rec)
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            if ssid is not None:
                self.post_update_condition_alias_sids.add(ssid)
                self.post_update_alias_sids.add(ssid)
                self.prefer_var_expr_sids.add(ssid)
                self.post_update_aliases.setdefault(ssid, {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_opcode": rec.get("source_opcode"),
                    "source_expr": rec.get("source_expr"),
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "policy": "render_source_sid_as_post_update_target_variable",
                })
            if csid is not None:
                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases.setdefault(csid, {
                    "source_sid": ssid,
                    "target_name": rec.get("target_name"),
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": rec.get("reason"),
                })

        # RawCond local-update fallback. This is deliberately narrow:
        # detect simple local_N +/- const subexpressions in RawCond text only
        # when the same block has an already-known state-write contract for
        # that local. This catches Sample Y local_14 + 1 when node linkage is
        # missing but execution metadata still proves a local_14 write.
        for rec in self._sgl_rawcond_local_update_alias_records(consumers):
            key = (
                rec.get("source_sid"),
                rec.get("consumer_addr"),
                rec.get("target_name"),
                rec.get("source_expr"),
                rec.get("condition_expr"),
                rec.get("producer_addr"),
            )
            if key in seen_alias:
                continue
            seen_alias.add(key)
            self.post_update_condition_aliases.append(rec)
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            if ssid is not None:
                self.post_update_condition_alias_sids.add(ssid)
                self.post_update_alias_sids.add(ssid)
                self.prefer_var_expr_sids.add(ssid)
                self.post_update_aliases.setdefault(ssid, {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_opcode": rec.get("source_opcode"),
                    "source_expr": rec.get("source_expr"),
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "policy": "render_source_sid_as_post_update_target_variable",
                })
            if csid is not None:
                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases.setdefault(csid, {
                    "source_sid": ssid,
                    "target_name": rec.get("target_name"),
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": rec.get("reason"),
                })

        # 4. SGL-adjacent state-write closure.  This catches RawCond conditions
        # that have no formula consumer edge, e.g. Sample Y tail:
        #     block local_14 = local_14 + 1
        #     if 4 < (local_14 + 1)
        for rec in self._sgl_adjacent_post_update_alias_records():
            key = (
                rec.get("source_sid"),
                rec.get("consumer_addr"),
                rec.get("target_name"),
                rec.get("source_expr"),
                rec.get("condition_expr"),
                rec.get("producer_addr"),
            )
            if key in seen_alias:
                continue
            seen_alias.add(key)
            self.post_update_condition_aliases.append(rec)
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            if ssid is not None:
                self.post_update_condition_alias_sids.add(ssid)
                self.post_update_alias_sids.add(ssid)
                self.prefer_var_expr_sids.add(ssid)
                self.post_update_aliases.setdefault(ssid, {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_opcode": rec.get("source_opcode"),
                    "source_expr": rec.get("source_expr"),
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "policy": "render_source_sid_as_post_update_target_variable",
                })
            if csid is not None:
                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases.setdefault(csid, {
                    "source_sid": ssid,
                    "target_name": rec.get("target_name"),
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": rec.get("reason"),
                })

        # v20i. Stack-mutating temp consumed by same-block condition.
        # This is the direct fix for Sample Y when no local_14 PHI/writeback
        # path exists:
        #   INT_ADD local_14,1 -> v_367
        #   INT_SLESS 4,v_367 -> v_436
        for rec in self._stack_update_temp_condition_alias_records(consumers):
            key = (
                rec.get("source_sid"),
                rec.get("consumer_addr"),
                rec.get("target_name"),
                rec.get("source_expr"),
                rec.get("condition_expr"),
                rec.get("producer_addr"),
            )
            if key in seen_alias:
                continue
            seen_alias.add(key)
            self.post_update_condition_aliases.append(rec)
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            if ssid is not None:
                self.post_update_condition_alias_sids.add(ssid)
                self.post_update_alias_sids.add(ssid)
                self.prefer_var_expr_sids.add(ssid)
                self.post_update_aliases.setdefault(ssid, {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_opcode": rec.get("source_opcode"),
                    "source_expr": rec.get("source_expr"),
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "policy": "render_source_sid_as_post_update_target_variable",
                })
                self.state_transition_alias_sids.add(ssid)
                self.state_transition_aliases[ssid] = {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_name": "v_%s" % ssid,
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "source_opcode": rec.get("source_opcode"),
                }
                self.must_emit_state_write_sids.add(ssid)
                self.state_write_info[ssid] = {
                    "kind": "stack_update_temp_state_write",
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "pred_addr": rec.get("producer_addr"),
                    "block_addr": rec.get("producer_addr"),
                    "reason": rec.get("reason"),
                    "source_opcode": rec.get("source_opcode"),
                }
            if csid is not None:
                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases.setdefault(csid, {
                    "source_sid": ssid,
                    "target_name": rec.get("target_name"),
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": rec.get("reason"),
                })

        # v20g. PHI-transition source consumed by same-block condition.
        # This is the direct fix for Sample Y:
        #   INT_ADD local_14,1 -> v_367
        #   INT_SLESS 4,v_367 -> v_436
        #   PHI/drop-in metadata says source_sid 367 targets local_14.
        for rec in self._transition_source_condition_alias_records(consumers):
            key = (
                rec.get("source_sid"),
                rec.get("consumer_addr"),
                rec.get("target_name"),
                rec.get("source_expr"),
                rec.get("condition_expr"),
                rec.get("producer_addr"),
            )
            if key in seen_alias:
                continue
            seen_alias.add(key)
            self.post_update_condition_aliases.append(rec)
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            if ssid is not None:
                self.post_update_condition_alias_sids.add(ssid)
                self.post_update_alias_sids.add(ssid)
                self.prefer_var_expr_sids.add(ssid)
                self.post_update_aliases.setdefault(ssid, {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_opcode": rec.get("source_opcode"),
                    "source_expr": rec.get("source_expr"),
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "policy": "render_source_sid_as_post_update_target_variable",
                })
            if csid is not None:
                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases.setdefault(csid, {
                    "source_sid": ssid,
                    "target_name": rec.get("target_name"),
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": rec.get("reason"),
                })

        # v20f. Exact block-local temp/update/compare closure.
        # This catches the alpha_four tail where the semantic value is:
        #   INT_ADD local_14,1 -> v_367
        #   INT_SLESS 4,v_367 -> v_436
        # rather than a direct local_14 state-write op.
        for rec in self._block_local_temp_post_update_alias_records(consumers):
            key = (
                rec.get("source_sid"),
                rec.get("consumer_addr"),
                rec.get("target_name"),
                rec.get("source_expr"),
                rec.get("condition_expr"),
                rec.get("producer_addr"),
            )
            if key in seen_alias:
                continue
            seen_alias.add(key)
            self.post_update_condition_aliases.append(rec)
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            if ssid is not None:
                self.post_update_condition_alias_sids.add(ssid)
                self.post_update_alias_sids.add(ssid)
                self.prefer_var_expr_sids.add(ssid)
                self.post_update_aliases.setdefault(ssid, {
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_opcode": rec.get("source_opcode"),
                    "source_expr": rec.get("source_expr"),
                    "pred_addr": rec.get("producer_addr"),
                    "join_addr": rec.get("consumer_addr"),
                    "reason": rec.get("reason"),
                    "policy": "render_source_sid_as_post_update_target_variable",
                })
            if csid is not None:
                self.post_update_consumer_sids.add(csid)
                self.prefer_var_expr_sids.add(csid)
                self.post_update_consumer_aliases.setdefault(csid, {
                    "source_sid": ssid,
                    "target_name": rec.get("target_name"),
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": rec.get("reason"),
                })

        # Promote condition temp policies after records have been collected.
        for rec in self.condition_temp_defs:
            sid = rec.get("sid")
            if sid is None:
                continue
            self._set_ssa_policy(
                sid,
                "condition_temp_def",
                emit=True,
                expr_mode="var",
                reason="SGL condition consumes temp; PHI exported exact definition metadata",
                target_name=self.var_map.get(sid) or rec.get("name"),
            )

        # Promote post-update condition aliases to preferred expression metadata.
        for rec in self.post_update_condition_aliases:
            ssid = rec.get("source_sid")
            csid = rec.get("consumer_sid")
            target_name = rec.get("target_name")

            if ssid is not None:
                self.preferred_expr_by_sid.setdefault(ssid, {})
                self.preferred_expr_by_sid[ssid].update({
                    "mode": "var",
                    "post_update_condition_alias": True,
                    "target_name": target_name,
                    "condition_addr": rec.get("consumer_addr"),
                    "source_expr": rec.get("source_expr"),
                })

            if csid is not None:
                self.post_update_consumer_aliases.setdefault(csid, {})
                self.post_update_consumer_aliases[csid].update({
                    "source_sid": ssid,
                    "target_name": target_name,
                    "consumer_opcode": rec.get("consumer_opcode"),
                    "reason": "SGL condition consumes post-update alias",
                })

        self.metadata_closure_events.append({
            "kind": "sgl_condition_consumer_metadata_closure",
            "consumers": len(consumers),
            "condition_temp_defs": len(self.condition_temp_defs),
            "post_update_condition_aliases": len(self.post_update_condition_aliases),
        })

    def _extract_temp_sids_from_condition_expr(self, expr):
        out = set()
        if not expr:
            return out
        for raw in re.findall(r"\bv_(\d+)\b", str(expr)):
            try:
                out.add(int(raw))
            except Exception:
                pass
        return out

    def _make_condition_temp_def_record(self, sid, consumer):
        if sid is None:
            return None

        node = self.nodes.get(sid)
        op = None
        block = None

        if node is not None:
            op = getattr(node, "op", None)
            block = getattr(node, "block", None) or getattr(node, "block_region", None)
        else:
            op, block = self.find_def_op_for_sid(sid)

        if node is None and op is None:
            return None

        opcode = getattr(node, "opcode", None) if node is not None else getattr(op, "opcode", None)
        pure = bool(opcode in self.PURE_INLINE_OPS or opcode in self.TRANSPARENT_OPS)

        if opcode in self.CALL_OPS or opcode in ("LOAD", "STORE", "INDIRECT", "MULTIEQUAL"):
            pure = False

        name = self.var_map.get(sid) or ("v_%s" % sid)
        expr = self._expr_for_node_or_op(node, op, block)

        return {
            "kind": "condition_temp_def",
            "sid": sid,
            "name": name,
            "consumer_kind": consumer.get("kind"),
            "consumer_addr": consumer.get("addr"),
            "consumer_role": consumer.get("role"),
            "condition_expr": consumer.get("cond_expr"),
            "expr": expr,
            "opcode": opcode,
            "pure": pure,
            "source_addr": getattr(block, "addr", None) if block is not None else self._node_block_addr(node),
            "emit_policy": "materialize_before_condition",
            "inline_allowed": bool(pure),
            "owner": "PHIfolder",
        }

    def find_def_op_for_sid(self, sid):
        if sid is None:
            return None, None
        for block in getattr(self.func, "blocks", []) or []:
            for op in getattr(block, "ops", []) or []:
                out = getattr(op, "output", None)
                if self.sid_of(out) == sid:
                    return op, block
        return None, None

    def _post_update_alias_records_for_consumer(self, cond_sid, cond_expr, consumer):
        records = []

        # A. Existing PHI-discovered post-update aliases, e.g. local_14 + 1.
        for source_sid, info in list(self.post_update_aliases.items()):
            node = self.nodes.get(source_sid)
            source_expr = self._expr_for_node_or_op(node, getattr(node, "op", None), getattr(node, "block", None)) if node is not None else None
            if not source_expr:
                continue
            if not self._condition_expr_contains_exact_formula(cond_expr, source_expr):
                continue
            records.append(self._make_post_update_condition_alias_record(
                source_sid,
                cond_sid,
                source_expr,
                info.get("target_name") or self.var_map.get(source_sid),
                consumer,
                "existing_phi_post_update_alias",
                getattr(node, "opcode", None) if node is not None else None,
            ))

        # B. Direct local state-update nodes that are not PHI source aliases,
        # e.g. local_28 = (local_28 + local_2c) % 10.
        for sid, node in list(self.nodes.items()):
            if sid in self.post_update_aliases:
                continue
            if not self._node_is_direct_post_update_value(node):
                continue
            source_expr = self._expr_for_node_or_op(node, getattr(node, "op", None), getattr(node, "block", None))
            if not source_expr:
                continue
            if not self._condition_expr_contains_exact_formula(cond_expr, source_expr):
                continue
            target_name = self.name_for_var(self.to_var(getattr(node, "var", None))) or self.var_map.get(sid)
            records.append(self._make_post_update_condition_alias_record(
                sid,
                cond_sid,
                source_expr,
                target_name,
                consumer,
                "direct_state_update_condition_alias",
                getattr(node, "opcode", None),
            ))

        return [r for r in records if r is not None]

    def _make_post_update_condition_alias_record(self, source_sid, consumer_sid, source_expr, target_name, consumer, reason, opcode):
        if source_sid is None or not target_name or not source_expr:
            return None

        return {
            "kind": "post_update_condition_alias",
            "source_sid": source_sid,
            "consumer_sid": consumer_sid,
            "target_name": target_name,
            "source_expr": source_expr,
            "condition_expr": consumer.get("cond_expr"),
            "consumer_kind": consumer.get("kind"),
            "consumer_addr": consumer.get("addr"),
            "consumer_role": consumer.get("role"),
            "consumer_opcode": getattr(self.nodes.get(consumer_sid), "opcode", None) if consumer_sid is not None else None,
            "source_opcode": opcode,
            "reason": reason,
            "emit_policy": "render_source_sid_as_target_after_state_write",
            "owner": "PHIfolder",
        }

    def _node_is_direct_post_update_value(self, node):
        if node is None:
            return False

        opcode = getattr(node, "opcode", None)
        if opcode not in self.PURE_INLINE_OPS:
            return False
        if opcode in self.COMPARE_OPS or opcode in ("BOOL_NEGATE",):
            return False

        out = getattr(node, "var", None)
        target_name = self.name_for_var(self.to_var(out))
        if not target_name:
            return False

        expr = self._expr_for_node_or_op(node, getattr(node, "op", None), getattr(node, "block", None))
        if not expr:
            return False

        if not self._expr_mentions_name(expr, target_name):
            return False

        return True

    def _condition_expr_contains_exact_formula(self, cond_expr, source_expr):
        if not cond_expr or not source_expr:
            return False

        variants = self._expr_variants(source_expr)
        c = self._normalize_expr_text(cond_expr)

        for v in variants:
            if not v:
                continue
            vv = self._normalize_expr_text(v)
            if vv and vv in c:
                return True
        return False

    def _expr_variants(self, expr):
        s = str(expr).strip()
        out = {s}
        if s.startswith("(") and s.endswith(")"):
            out.add(s[1:-1].strip())
        out.add("(%s)" % s)
        out.add("((%s))" % s)
        return out

    def _normalize_expr_text(self, s):
        return re.sub(r"\s+", "", str(s or ""))

    def _expr_mentions_name(self, expr, name):
        if not expr or not name:
            return False
        return re.search(r"\b%s\b" % re.escape(str(name)), str(expr)) is not None

    def _expr_for_node_or_op(self, node, op=None, block=None):
        if node is not None:
            return self._expr_for_node(node, seen=set())
        if op is not None:
            return self._expr_for_op(op, block=block, seen=set())
        return None

    def _expr_for_node(self, node, seen=None):
        if node is None:
            return None
        if seen is None:
            seen = set()
        sid = self.sid_of(node)
        if sid is not None:
            if sid in seen:
                return self.name_for_var(self.to_var(getattr(node, "var", None))) or self.var_map.get(sid) or ("v_%s" % sid)
            seen.add(sid)

        opcode = getattr(node, "opcode", None)
        inputs = list(getattr(node, "inputs", []) or [])
        return self._expr_from_opcode_inputs(opcode, inputs, getattr(node, "var", None), seen)

    def _expr_for_op(self, op, block=None, seen=None):
        if op is None:
            return None
        if seen is None:
            seen = set()
        opcode = getattr(op, "opcode", None)
        inputs = list(getattr(op, "inputs", []) or [])
        return self._expr_from_opcode_inputs(opcode, inputs, getattr(op, "output", None), seen)

    def _expr_from_opcode_inputs(self, opcode, inputs, out_var=None, seen=None):
        if seen is None:
            seen = set()

        if opcode in ("COPY", "CAST", "INT_ZEXT", "INT_SEXT", "TRUNC") and inputs:
            # v30: this method describes the producer expression (RHS).
            # Snapshot *references* are intercepted by
            # _value_expr_for_metadata(), but the COPY definition itself must
            # remain ``snapshot = captured_epoch`` rather than self-copying.
            return self._value_expr_for_metadata(inputs[0], seen)

        binops = {
            "INT_ADD": "+",
            "INT_SUB": "-",
            "INT_MULT": "*",
            "INT_DIV": "//",
            "INT_SDIV": "//",
            "INT_REM": "%",
            "INT_SREM": "%",
            "INT_AND": "&",
            "INT_OR": "|",
            "INT_XOR": "^",
            "INT_LEFT": "<<",
            "INT_RIGHT": ">>",
            "INT_SRIGHT": ">>",
            "INT_EQUAL": "==",
            "INT_NOTEQUAL": "!=",
            "INT_LESS": "<",
            "INT_SLESS": "<",
            "INT_LESSEQUAL": "<=",
            "INT_SLESSEQUAL": "<=",
        }

        if opcode in binops and len(inputs) == 2:
            return "(%s %s %s)" % (
                self._value_expr_for_metadata(inputs[0], seen.copy()),
                binops[opcode],
                self._value_expr_for_metadata(inputs[1], seen.copy()),
            )

        if opcode == "BOOL_NEGATE" and inputs:
            return "not (%s)" % self._value_expr_for_metadata(inputs[0], seen.copy())

        if opcode == "SUBPIECE" and inputs:
            args = ", ".join(self._value_expr_for_metadata(i, seen.copy()) for i in inputs)
            return "subpiece(%s)" % args

        if opcode == "PIECE" and inputs:
            args = ", ".join(self._value_expr_for_metadata(i, seen.copy()) for i in inputs)
            return "piece(%s)" % args

        if opcode in self.CALL_OPS:
            sid = self.sid_of(out_var)
            return self.var_map.get(sid) or self.name_for_var(self.to_var(out_var)) or ("v_%s" % sid if sid is not None else None)

        sid = self.sid_of(out_var)
        return self.var_map.get(sid) or self.name_for_var(self.to_var(out_var)) or ("v_%s" % sid if sid is not None else None)

    def _value_expr_for_metadata(self, x, seen=None):
        if seen is None:
            seen = set()

        snapshot_name = self._erase_emperor_projection_for_value_v29(x)
        if snapshot_name:
            return snapshot_name

        derived_name = self._null_emperor_projection_for_value_v31(x)
        if derived_name:
            return derived_name

        v = self.to_var(x)
        if v is not None and getattr(v, "is_constant", False):
            return self._const_expr_for_metadata(v)

        sid = self.sid_of(x)
        if sid is not None and sid in self.nodes:
            node = self.nodes.get(sid)
            if node is not None and getattr(node, "opcode", None) not in self.CALL_OPS:
                return self._expr_for_node(node, seen)

        return self.var_map.get(sid) or self.name_for_var(v) or ("v_%s" % sid if sid is not None else str(x))

    def _const_expr_for_metadata(self, v):
        for attr in ("const_value", "value", "offset"):
            val = getattr(v, attr, None)
            if val is not None:
                if isinstance(val, int) and abs(val) >= 10:
                    return hex(val)
                return str(val)
        return "0"








    # ---------------------------------------------------------
    # STACK-UPDATE TEMP CONDITION ALIAS CLOSURE
    # ---------------------------------------------------------

    def _stack_update_temp_condition_alias_records(self, consumers):
        """
        Detect stack-local in-place update represented as temp output.

        Pattern:
            INT_ADD [local_14, 0x1] -> v_367
            INT_SLESS [0x4, v_367] -> v_436
            CBRANCH cond=v_436

        The source SID v_367 is the post-update value of local_14.  This is
        SID/dataflow-backed; it does not depend on PHI/drop-in metadata.
        """

        records = []
        seen = set()

        for consumer in list(consumers or []):
            caddr = consumer.get("addr")
            cond_sid = consumer.get("cond_sid")
            cond_expr = str(consumer.get("cond_expr") or "")
            if caddr is None:
                continue

            block = self._pal_block_for_addr(caddr) if hasattr(self, "_pal_block_for_addr") else None
            if block is None:
                self.stack_update_temp_condition_alias_events.append({
                    "kind": "stack_update_temp_condition_alias_miss",
                    "consumer_addr": caddr,
                    "condition_expr": cond_expr,
                    "reason": "no_pal_block_for_consumer_addr",
                })
                continue

            cmp_consumers = self._block_condition_consumers_by_input_sid(block, cond_sid)
            candidates = self._stack_update_temp_candidates_for_block(block)

            for source_sid, state in sorted(candidates.items(), key=lambda kv: str(kv[0])):
                if source_sid not in cmp_consumers:
                    self.stack_update_temp_condition_alias_events.append({
                        "kind": "stack_update_temp_condition_alias_reject",
                        "consumer_addr": caddr,
                        "producer_addr": state.get("producer_addr"),
                        "source_sid": source_sid,
                        "target_name": state.get("target_name"),
                        "source_expr": state.get("source_expr"),
                        "condition_expr": cond_expr,
                        "reason": "temp_not_consumed_by_condition_compare",
                    })
                    continue

                cmp_info = cmp_consumers.get(source_sid) or {}
                rec = self._make_post_update_condition_alias_record(
                    source_sid,
                    cmp_info.get("consumer_sid") or cond_sid,
                    state.get("source_expr"),
                    state.get("target_name"),
                    consumer,
                    "stack_update_temp_consumed_by_condition_alias",
                    state.get("source_opcode"),
                )
                if rec is None:
                    continue

                rec["producer_addr"] = state.get("producer_addr")
                rec["target_sid"] = state.get("target_sid")
                rec["producer_opcode"] = state.get("source_opcode")
                rec["condition_consumer_sid"] = cmp_info.get("consumer_sid")
                rec["condition_consumer_opcode"] = cmp_info.get("consumer_opcode")
                rec["stack_update_temp"] = True

                key = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("consumer_addr"),
                    rec.get("condition_consumer_sid"),
                )
                if key in seen:
                    continue
                seen.add(key)

                self.stack_update_temp_condition_alias_events.append({
                    "kind": "stack_update_temp_condition_alias",
                    "producer_addr": rec.get("producer_addr"),
                    "consumer_addr": rec.get("consumer_addr"),
                    "source_sid": rec.get("source_sid"),
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_expr": rec.get("source_expr"),
                    "condition_expr": rec.get("condition_expr"),
                    "condition_consumer_sid": rec.get("condition_consumer_sid"),
                    "condition_consumer_opcode": rec.get("condition_consumer_opcode"),
                })
                records.append(rec)

        return records

    def _stack_update_temp_candidates_for_block(self, block):
        """
        Return only real stack-update temp candidates.

        v20h over-fired on read-only bit tests:
            INT_AND [local_14, 0x1] -> v_247
            INT_NOTEQUAL [v_247, 0x0] -> v_279

        That is not a state mutation.  It is only a condition builder.

        v20i therefore restricts this fallback to canonical in-place update
        shapes that Ghidra/HF commonly lowers from stack writes such as:
            ADD dword ptr [RBP-0xc], 1
        into:
            INT_ADD [local_14, 0x1] -> v_367

        Wider arithmetic/bitwise cases should be accepted through explicit
        PHI/drop-in/state-transition metadata, not this heuristic fallback.
        """

        out = {}
        if block is None:
            return out

        for op in list(getattr(block, "ops", []) or []):
            opcode = getattr(op, "opcode", None)

            if not self._is_guarded_stack_update_opcode(opcode):
                continue

            output = getattr(op, "output", None)
            source_sid = self.sid_of(output)
            if source_sid is None:
                continue

            if self._erase_emperor_is_derived_result_sid_v29(source_sid):
                info = self._erase_emperor_derived_info_for_sid_v29(source_sid)
                self._record_erase_emperor_derived_alias_rejection_v29(
                    source_sid,
                    info.get("later_epoch_sid"),
                    "stack_update_temp_candidate",
                    pred_addr=getattr(block, "addr", None),
                    join_addr=getattr(block, "addr", None),
                )
                self.stack_update_temp_condition_alias_events.append({
                    "kind": (
                        "erase_emperor_snapshot_derived_stack_update_"
                        "candidate_rejected_v29"
                    ),
                    "producer_addr": getattr(block, "addr", None),
                    "source_sid": self._erase_emperor_sid_text_v29(source_sid),
                    "source_opcode": opcode,
                    "snapshot_sids": list(info.get("snapshot_sids", []) or []),
                    "later_epoch_sid": info.get("later_epoch_sid"),
                    "reason": (
                        "order_sensitive result compares a protected historical "
                        "epoch with a later state epoch; it is a derived value, "
                        "not an in-place state successor"
                    ),
                })
                continue

            snapshot_inputs = self._erase_emperor_snapshot_dependencies_for_node_v29(op)
            if snapshot_inputs and opcode in self.ERASE_EMPEROR_ORDER_SENSITIVE_OPS:
                self.stack_update_temp_condition_alias_events.append({
                    "kind": (
                        "erase_emperor_uncontracted_snapshot_stack_update_"
                        "candidate_rejected_v29"
                    ),
                    "producer_addr": getattr(block, "addr", None),
                    "source_sid": self._erase_emperor_sid_text_v29(source_sid),
                    "source_opcode": opcode,
                    "snapshot_sids": sorted(snapshot_inputs, key=str),
                    "reason": (
                        "snapshot-derived order-sensitive result lacks positive "
                        "state-successor proof"
                    ),
                })
                continue

            # Output must be temp/non-stack.  If the output is stack-local, the
            # ordinary local-state emission paths own it.
            if self.is_stack_local(output):
                continue

            inputs = list(getattr(op, "inputs", []) or [])
            if not inputs:
                continue

            target_var = None
            target_name = None
            for inp in inputs:
                if self.is_stack_local(inp):
                    target_var = self.to_var(inp)
                    target_name = self.name_for_var(target_var)
                    break

            if not target_name:
                continue

            # Reject read-only condition masks such as local_14 & 1.  The
            # fallback is for mutation-like updates, not arbitrary expressions
            # that merely mention a stack local.
            if not self._stack_update_op_has_delta_component(op, target_var, target_name):
                self.stack_update_temp_condition_alias_events.append({
                    "kind": "stack_update_temp_candidate_reject",
                    "producer_addr": getattr(block, "addr", None),
                    "source_sid": source_sid,
                    "target_name": target_name,
                    "source_opcode": opcode,
                    "reason": "no_delta_component_or_read_only_test",
                })
                continue

            source_expr = self._expr_for_op(op, block=block, seen=set())
            if not source_expr or not self._expr_mentions_name(source_expr, target_name):
                source_expr = self._expr_for_stack_update_op(op, target_name)
                if not source_expr:
                    continue

            target_sid = self.sid_of(target_var)

            out[source_sid] = {
                "source_sid": source_sid,
                "target_sid": target_sid,
                "target_name": target_name,
                "source_expr": source_expr,
                "source_opcode": opcode,
                "producer_addr": getattr(block, "addr", None),
            }

        return out

    def _is_guarded_stack_update_opcode(self, opcode):
        """
        Conservative fallback whitelist.

        ADD/SUB catch counter++/counter-- and in-place stack increments.
        Single-input arithmetic forms are accepted for genuine unary stack
        updates if they appear in PAL.  Bitwise masks are deliberately not
        accepted here; they are commonly read-only condition builders.
        """
        return opcode in (
            "INT_ADD",
            "INT_SUB",
            "INT_NEGATE",
            "INT_2COMP",
        )

    def _stack_update_op_has_delta_component(self, op, target_var, target_name):
        opcode = getattr(op, "opcode", None)
        inputs = list(getattr(op, "inputs", []) or [])

        if opcode in ("INT_ADD", "INT_SUB"):
            if len(inputs) != 2:
                return False

            has_target = False
            has_delta = False

            for inp in inputs:
                if self.is_stack_local(inp):
                    iv = self.to_var(inp)
                    if self.name_for_var(iv) == target_name:
                        has_target = True
                    continue

                # A non-zero constant is the canonical increment/decrement
                # component.  Non-stack variable deltas are also accepted for
                # x = x + y style state transitions.
                if getattr(inp, "is_constant", False):
                    val = None
                    for attr in ("const_value", "value", "offset"):
                        val = getattr(inp, attr, None)
                        if val is not None:
                            break
                    try:
                        if int(val) != 0:
                            has_delta = True
                    except Exception:
                        has_delta = True
                else:
                    has_delta = True

            return bool(has_target and has_delta)

        # Unary arithmetic update over the target itself.
        if opcode in ("INT_NEGATE", "INT_2COMP"):
            return bool(inputs and self.is_stack_local(inputs[0]) and self.name_for_var(self.to_var(inputs[0])) == target_name)

        return False



    def _expr_for_stack_update_op(self, op, target_name):
        opcode = getattr(op, "opcode", None)
        inputs = list(getattr(op, "inputs", []) or [])
        if len(inputs) != 2 or not target_name:
            return None

        symbols = {
            "INT_ADD": "+",
            "INT_SUB": "-",
            "INT_AND": "&",
            "INT_OR": "|",
            "INT_XOR": "^",
            "INT_LEFT": "<<",
            "INT_RIGHT": ">>",
            "INT_SRIGHT": ">>",
        }
        sym = symbols.get(opcode)
        if not sym:
            return None

        a, b = inputs[0], inputs[1]
        if self.is_stack_local(a):
            left = target_name
            right = self._value_expr_for_metadata(b, seen=set())
        elif self.is_stack_local(b):
            left = self._value_expr_for_metadata(a, seen=set())
            right = target_name
        else:
            return None

        return "(%s %s %s)" % (left, sym, right)



    # ---------------------------------------------------------
    # TRANSITION-SOURCE CONDITION ALIAS CLOSURE
    # ---------------------------------------------------------

    def _transition_source_condition_alias_records(self, consumers):
        """
        Use PHI/drop-in transition metadata as the source of truth for
        source_sid -> local target.

        This catches Sample Y even when var_map[source_sid] is still v_367:
            phi/drop-in: source_sid 367 -> target_name local_14
            block ops  : INT_SLESS [0x4, v_367] -> v_436
            RawCond    : 4 < (local_14 + 1)
        """

        records = []
        seen = set()
        transition_sources = self._transition_source_records_by_sid()

        for consumer in list(consumers or []):
            caddr = consumer.get("addr")
            cond_sid = consumer.get("cond_sid")
            cond_expr = str(consumer.get("cond_expr") or "")
            if caddr is None:
                continue

            block = self._pal_block_for_addr(caddr) if hasattr(self, "_pal_block_for_addr") else None
            if block is None:
                self.transition_source_condition_alias_events.append({
                    "kind": "transition_source_condition_alias_miss",
                    "consumer_addr": caddr,
                    "condition_expr": cond_expr,
                    "reason": "no_pal_block_for_consumer_addr",
                })
                continue

            cmp_consumers = self._block_condition_consumers_by_input_sid(block, cond_sid)

            for source_sid, trans in sorted(transition_sources.items(), key=lambda kv: str(kv[0])):
                if source_sid not in cmp_consumers:
                    continue

                producer_addr = trans.get("pred_addr") or self._source_sid_block_addr(source_sid)
                # Prefer exact same-block evidence, but accept unknown producer
                # addr because phi/dropin predecessor metadata may be absent.
                if producer_addr is not None and producer_addr != caddr:
                    self.transition_source_condition_alias_events.append({
                        "kind": "transition_source_condition_alias_reject",
                        "consumer_addr": caddr,
                        "producer_addr": producer_addr,
                        "source_sid": source_sid,
                        "target_name": trans.get("target_name"),
                        "condition_expr": cond_expr,
                        "reason": "producer_addr_differs_from_condition_addr",
                    })
                    continue

                node = self.nodes.get(source_sid)
                source_expr = self._expr_for_node_or_op(node, getattr(node, "op", None), getattr(node, "block", None)) if node is not None else None
                if not source_expr:
                    op, block2 = self.find_def_op_for_sid(source_sid)
                    source_expr = self._expr_for_op(op, block=block2, seen=set()) if op is not None else None

                if not source_expr:
                    source_expr = trans.get("source_expr")

                if not source_expr:
                    self.transition_source_condition_alias_events.append({
                        "kind": "transition_source_condition_alias_reject",
                        "consumer_addr": caddr,
                        "source_sid": source_sid,
                        "target_name": trans.get("target_name"),
                        "condition_expr": cond_expr,
                        "reason": "missing_source_expr",
                    })
                    continue

                target_name = trans.get("target_name")
                if not target_name:
                    continue

                # This pass is source-SID backed. The RawCond text can differ
                # by hex/decimal constants, so exact source_expr-in-cond match
                # is diagnostic, not required, when compare consumes source_sid.
                cmp_info = cmp_consumers.get(source_sid) or {}
                rec = self._make_post_update_condition_alias_record(
                    source_sid,
                    cmp_info.get("consumer_sid") or cond_sid,
                    source_expr,
                    target_name,
                    consumer,
                    "transition_source_consumed_by_condition_alias",
                    getattr(node, "opcode", None) if node is not None else trans.get("source_opcode"),
                )
                if rec is None:
                    continue

                rec["producer_addr"] = producer_addr if producer_addr is not None else caddr
                rec["target_sid"] = trans.get("target_sid")
                rec["transition_record"] = trans.get("kind")
                rec["condition_consumer_sid"] = cmp_info.get("consumer_sid")
                rec["condition_consumer_opcode"] = cmp_info.get("consumer_opcode")
                rec["source_sid_backed"] = True

                key = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("consumer_addr"),
                    rec.get("condition_consumer_sid"),
                )
                if key in seen:
                    continue
                seen.add(key)

                self.transition_source_condition_alias_events.append({
                    "kind": "transition_source_condition_alias",
                    "producer_addr": rec.get("producer_addr"),
                    "consumer_addr": rec.get("consumer_addr"),
                    "source_sid": rec.get("source_sid"),
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_expr": rec.get("source_expr"),
                    "condition_expr": rec.get("condition_expr"),
                    "condition_consumer_sid": rec.get("condition_consumer_sid"),
                    "condition_consumer_opcode": rec.get("condition_consumer_opcode"),
                    "transition_record": rec.get("transition_record"),
                })
                records.append(rec)

        return records

    def _transition_source_records_by_sid(self):
        """
        Collect source_sid -> target local facts from PHI/drop-in/state
        transition metadata.

        v20g1 hotfix: metadata containers are not stable across PAL versions.
        Accept both dict-shaped and list-shaped forms for:
          - state_transition_aliases
          - phi_source_aliases
          - phi_dropins
        """

        out = {}

        for sid, info in self._iter_sid_info_records(getattr(self, "state_transition_aliases", {}) or {}):
            target_name = info.get("target_name")
            if not target_name:
                continue
            out[sid] = {
                "kind": "state_transition_alias",
                "source_sid": sid,
                "target_sid": info.get("target_sid"),
                "target_name": target_name,
                "pred_addr": info.get("pred_addr"),
                "join_addr": info.get("join_addr"),
                "source_opcode": info.get("source_opcode") or getattr(self.nodes.get(sid), "opcode", None),
            }

        for sid, info in self._iter_sid_info_records(getattr(self, "phi_source_aliases", {}) or {}):
            target_name = info.get("target_name")
            if not target_name:
                continue
            out.setdefault(sid, {
                "kind": "phi_source_alias",
                "source_sid": sid,
                "target_sid": info.get("target_sid"),
                "target_name": target_name,
                "pred_addr": info.get("pred_addr"),
                "join_addr": info.get("join_addr"),
                "source_opcode": info.get("source_opcode") or getattr(self.nodes.get(sid), "opcode", None),
            })

        for rec in list(getattr(self, "phi_dropins", []) or []):
            if not isinstance(rec, dict):
                continue
            sid = rec.get("source_sid")
            target_name = rec.get("target_name")
            if sid is None or not target_name:
                continue
            if not str(target_name).startswith("local_"):
                continue
            out.setdefault(sid, {
                "kind": "phi_dropin",
                "source_sid": sid,
                "target_sid": rec.get("target_sid"),
                "target_name": target_name,
                "pred_addr": rec.get("pred_addr"),
                "join_addr": rec.get("join_addr"),
                "source_opcode": getattr(rec.get("source_node"), "opcode", None) or getattr(self.nodes.get(sid), "opcode", None),
            })

        return out

    def _iter_sid_info_records(self, obj):
        """
        Normalize transition metadata into (sid, dict) pairs.

        Supported shapes:
          {sid: {...}}
          [{source_sid: sid, ...}, ...]
          [(sid, {...}), ...]
        """

        if isinstance(obj, dict):
            for sid, info in obj.items():
                if isinstance(info, dict):
                    yield sid, info
                else:
                    yield sid, {"value": info}
            return

        if isinstance(obj, (list, tuple, set)):
            for item in obj:
                if isinstance(item, dict):
                    sid = item.get("source_sid")
                    if sid is None:
                        sid = item.get("sid")
                    if sid is None:
                        sid = item.get("id")
                    if sid is not None:
                        yield sid, item
                    continue

                if isinstance(item, (list, tuple)) and len(item) == 2:
                    sid, info = item
                    if isinstance(info, dict):
                        yield sid, info
                    else:
                        yield sid, {"value": info}


    def _source_sid_block_addr(self, sid):
        node = self.nodes.get(sid)
        addr = self._node_block_addr(node)
        if addr is not None:
            return addr
        block = self.find_def_block_for_sid(sid)
        return getattr(block, "addr", None) if block is not None else None



    # ---------------------------------------------------------
    # BLOCK-LOCAL TEMP POST-UPDATE ALIAS CLOSURE
    # ---------------------------------------------------------

    def _block_local_temp_post_update_alias_records(self, consumers):
        """
        Exact closure for:
            update temp -> compare condition -> CBRANCH

        Sample Y:
            INT_ADD [local_14, 0x1] -> v_367
            INT_SLESS [0x4, v_367] -> v_436
            CBRANCH cond=v_436

        If var_map says v_367 renders as local_14, then v_367 is the
        post-update value of local_14 in this condition.
        """

        records = []
        seen = set()

        for consumer in list(consumers or []):
            caddr = consumer.get("addr")
            cond_sid = consumer.get("cond_sid")
            cond_expr = str(consumer.get("cond_expr") or "")
            if caddr is None:
                continue

            block = self._pal_block_for_addr(caddr) if hasattr(self, "_pal_block_for_addr") else None
            if block is None:
                self.block_local_temp_post_update_alias_events.append({
                    "kind": "block_local_temp_post_update_alias_miss",
                    "consumer_addr": caddr,
                    "condition_expr": cond_expr,
                    "reason": "no_pal_block_for_consumer_addr",
                })
                continue

            producers = self._block_update_temp_candidates(block)
            consumers_of_temp = self._block_condition_consumers_by_input_sid(block, cond_sid)

            for source_sid, state in producers.items():
                if source_sid not in consumers_of_temp:
                    self.block_local_temp_post_update_alias_events.append({
                        "kind": "block_local_temp_post_update_alias_reject",
                        "consumer_addr": caddr,
                        "producer_addr": state.get("producer_addr"),
                        "source_sid": source_sid,
                        "target_name": state.get("target_name"),
                        "source_expr": state.get("source_expr"),
                        "condition_expr": cond_expr,
                        "reason": "temp_not_consumed_by_condition_compare",
                    })
                    continue

                cmp_info = consumers_of_temp.get(source_sid) or {}
                rec = self._make_post_update_condition_alias_record(
                    source_sid,
                    cmp_info.get("consumer_sid") or cond_sid,
                    state.get("source_expr"),
                    state.get("target_name"),
                    consumer,
                    "block_local_temp_update_feeds_condition_alias",
                    state.get("source_opcode"),
                )
                if rec is None:
                    continue

                rec["producer_addr"] = state.get("producer_addr")
                rec["target_sid"] = state.get("target_sid")
                rec["producer_opcode"] = state.get("source_opcode")
                rec["condition_consumer_sid"] = cmp_info.get("consumer_sid")
                rec["condition_consumer_opcode"] = cmp_info.get("consumer_opcode")

                key = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("consumer_addr"),
                    rec.get("producer_addr"),
                )
                if key in seen:
                    continue
                seen.add(key)

                self.block_local_temp_post_update_alias_events.append({
                    "kind": "block_local_temp_post_update_alias",
                    "producer_addr": rec.get("producer_addr"),
                    "consumer_addr": rec.get("consumer_addr"),
                    "source_sid": rec.get("source_sid"),
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_expr": rec.get("source_expr"),
                    "condition_expr": rec.get("condition_expr"),
                    "condition_consumer_sid": rec.get("condition_consumer_sid"),
                    "condition_consumer_opcode": rec.get("condition_consumer_opcode"),
                })
                records.append(rec)

        return records

    def _block_update_temp_candidates(self, block):
        out = {}
        if block is None:
            return out

        for op in list(getattr(block, "ops", []) or []):
            opcode = getattr(op, "opcode", None)
            if opcode not in (
                "INT_ADD", "INT_SUB", "INT_MULT", "INT_DIV", "INT_SDIV",
                "INT_REM", "INT_SREM", "INT_AND", "INT_OR", "INT_XOR",
                "INT_LEFT", "INT_RIGHT", "INT_SRIGHT",
            ):
                continue

            output = getattr(op, "output", None)
            sid = self.sid_of(output)
            if sid is None:
                continue

            target_name = self.var_map.get(sid)
            if not target_name or not str(target_name).startswith("local_"):
                continue

            expr = self._expr_for_op(op, block=block, seen=set())
            if not expr:
                continue

            if not self._expr_mentions_name(expr, target_name):
                continue

            out[sid] = {
                "source_sid": sid,
                "target_sid": sid,
                "target_name": target_name,
                "source_expr": expr,
                "source_opcode": opcode,
                "producer_addr": getattr(block, "addr", None),
            }

        return out

    def _block_condition_consumers_by_input_sid(self, block, cond_sid=None):
        out = {}
        if block is None:
            return out

        # Prefer actual compare/condition op that defines cond_sid; also accept
        # any compare op in this block that consumes the candidate temp.
        for op in list(getattr(block, "ops", []) or []):
            opcode = getattr(op, "opcode", None)
            if opcode not in self.COMPARE_OPS and opcode != "BOOL_NEGATE":
                continue

            osid = self.sid_of(getattr(op, "output", None))
            if cond_sid is not None and osid != cond_sid:
                # Still collect; SGL cond_sid can be absent/mismatched for
                # RawCond.  The temp-consumption proof is stronger here.
                pass

            for inp in list(getattr(op, "inputs", []) or []):
                isid = self.sid_of(inp)
                if isid is None:
                    continue
                out[isid] = {
                    "consumer_sid": osid,
                    "consumer_opcode": opcode,
                }

        return out



    # ---------------------------------------------------------
    # SGL RAWCOND LOCAL-UPDATE FALLBACK
    # ---------------------------------------------------------

    def _sgl_rawcond_local_update_alias_records(self, consumers):
        """
        Fallback for lost formula linkage.

        A RawCond like:
            (4 < (local_14 + 1))
        contains the post-update expression text, but PHI may fail to recover
        the exact source node. Accept a metadata alias only if there is an
        already-known same-address state-write contract for local_14.
        """

        records = []
        seen = set()

        for consumer in list(consumers or []):
            cond_expr = str(consumer.get("cond_expr") or "")
            caddr = consumer.get("addr")
            if not cond_expr or caddr is None:
                continue

            for cand in self._extract_local_delta_exprs_from_rawcond(cond_expr):
                target_name = cand.get("target_name")
                source_expr = cand.get("source_expr")
                if not target_name or not source_expr:
                    continue

                state = self._same_addr_state_write_contract_for_local(caddr, target_name)
                if state is None:
                    self.sgl_rawcond_local_update_alias_events.append({
                        "kind": "sgl_rawcond_local_update_alias_reject",
                        "consumer_addr": caddr,
                        "target_name": target_name,
                        "source_expr": source_expr,
                        "condition_expr": cond_expr,
                        "reason": "no_same_addr_state_write_contract_for_local",
                    })
                    continue

                rec = self._make_post_update_condition_alias_record(
                    state.get("source_sid"),
                    consumer.get("cond_sid"),
                    source_expr,
                    target_name,
                    consumer,
                    "sgl_rawcond_local_delta_state_write_alias",
                    state.get("source_opcode"),
                )
                if rec is None:
                    continue

                rec["producer_addr"] = state.get("producer_addr")
                rec["target_sid"] = state.get("target_sid")
                rec["producer_opcode"] = state.get("source_opcode")
                rec["rawcond_fallback"] = True

                key = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("source_expr"),
                    rec.get("consumer_addr"),
                    rec.get("producer_addr"),
                )
                if key in seen:
                    continue
                seen.add(key)

                self.sgl_rawcond_local_update_alias_events.append({
                    "kind": "sgl_rawcond_local_update_alias",
                    "producer_addr": rec.get("producer_addr"),
                    "consumer_addr": rec.get("consumer_addr"),
                    "source_sid": rec.get("source_sid"),
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_expr": rec.get("source_expr"),
                    "condition_expr": rec.get("condition_expr"),
                })
                records.append(rec)

        return records

    def _extract_local_delta_exprs_from_rawcond(self, cond_expr):
        """
        Extract narrow local +/- constant candidates from RawCond text.
        """

        out = []
        s = str(cond_expr or "")

        pat = re.compile(
            r"\(\s*(local_[0-9a-fA-F]+)\s*([+-])\s*(0x[0-9a-fA-F]+|\d+)\s*\)"
        )

        for m in pat.finditer(s):
            local = m.group(1)
            op = m.group(2)
            const = m.group(3)
            expr = "(%s %s %s)" % (local, op, const)
            out.append({
                "target_name": local,
                "source_expr": expr,
                "operator": op,
                "constant": const,
            })

        return out

    def _same_addr_state_write_contract_for_local(self, addr, target_name):
        """
        Find a state-write contract for target_name at addr.
        """

        if addr is None or not target_name:
            return None

        for sid, info in self._iter_sid_info_records(getattr(self, "state_write_info", {}) or {}):
            if info.get("target_name") != target_name:
                continue
            iaddr = info.get("block_addr", info.get("pred_addr", info.get("producer_addr")))
            if iaddr != addr:
                continue
            node = self.nodes.get(sid)
            return {
                "source_sid": sid,
                "target_sid": info.get("target_sid", sid),
                "target_name": target_name,
                "producer_addr": addr,
                "source_opcode": info.get("source_opcode") or getattr(node, "opcode", None),
            }

        for sid, info in self._iter_sid_info_records(getattr(self, "state_transition_aliases", {}) or {}):
            if info.get("target_name") != target_name:
                continue
            iaddr = info.get("pred_addr", info.get("block_addr", info.get("producer_addr")))
            if iaddr != addr:
                continue
            node = self.nodes.get(sid)
            return {
                "source_sid": sid,
                "target_sid": info.get("target_sid", sid),
                "target_name": target_name,
                "producer_addr": addr,
                "source_opcode": info.get("source_opcode") or getattr(node, "opcode", None),
            }

        for sid in list(getattr(self, "must_emit_state_write_sids", set()) or set()):
            if self.var_map.get(sid) != target_name:
                continue
            node = self.nodes.get(sid)
            naddr = self._node_block_addr(node)
            if naddr is not None and naddr != addr:
                continue
            return {
                "source_sid": sid,
                "target_sid": sid,
                "target_name": target_name,
                "producer_addr": addr,
                "source_opcode": getattr(node, "opcode", None) if node is not None else None,
            }

        block = self._pal_block_for_addr(addr) if hasattr(self, "_pal_block_for_addr") else None
        if block is not None:
            for op in list(getattr(block, "ops", []) or []):
                out = getattr(op, "output", None)
                sid = self.sid_of(out)
                if sid is None:
                    continue
                if (self.var_map.get(sid) or self.name_for_var(self.to_var(out))) != target_name:
                    continue
                opcode = getattr(op, "opcode", None)
                if opcode not in self.PURE_INLINE_OPS:
                    continue
                return {
                    "source_sid": sid,
                    "target_sid": sid,
                    "target_name": target_name,
                    "producer_addr": addr,
                    "source_opcode": opcode,
                }

        return None



    # ---------------------------------------------------------
    # SGL SAME-BLOCK POST-UPDATE ALIAS CLOSURE
    # ---------------------------------------------------------

    def _sgl_same_block_post_update_alias_records(self, consumers):
        """
        Derive post-update condition aliases when SGL RawCond and update op
        share the same PAL block address.

        Sample Y / alpha_four tail:
            SGL source event: src=0x10129b expr=(4 < (local_14 + 1))
            emitted block  : local_14 = (local_14 + 1)

        This pass scans the PAL block at consumer["addr"], renders pure
        state-update expressions in that block, and if the condition text
        contains the same expression, emits a post_update_condition_alias.
        """

        records = []
        seen = set()

        for consumer in list(consumers or []):
            cond_expr = str(consumer.get("cond_expr") or "")
            caddr = consumer.get("addr")

            if not cond_expr or caddr is None:
                continue

            block = self._pal_block_for_addr(caddr)
            if block is None:
                self.sgl_same_block_post_update_alias_events.append({
                    "kind": "sgl_same_block_post_update_alias_miss",
                    "consumer_addr": caddr,
                    "condition_expr": cond_expr,
                    "reason": "no_pal_block_for_consumer_addr",
                })
                continue

            for state in self._state_update_records_for_block(block):
                source_expr = state.get("source_expr")
                target_name = state.get("target_name")

                if not source_expr or not target_name:
                    continue

                if not self._condition_expr_contains_exact_formula(cond_expr, source_expr):
                    self.sgl_same_block_post_update_alias_events.append({
                        "kind": "sgl_same_block_post_update_alias_reject",
                        "consumer_addr": caddr,
                        "producer_addr": state.get("producer_addr"),
                        "source_sid": state.get("source_sid"),
                        "target_name": target_name,
                        "source_expr": source_expr,
                        "condition_expr": cond_expr,
                        "reason": "source_expr_not_in_condition",
                    })
                    continue

                rec = self._make_post_update_condition_alias_record(
                    state.get("source_sid"),
                    consumer.get("cond_sid"),
                    source_expr,
                    target_name,
                    consumer,
                    "sgl_same_block_state_write_condition_alias",
                    state.get("source_opcode"),
                )
                if rec is None:
                    continue

                rec["producer_addr"] = state.get("producer_addr")
                rec["target_sid"] = state.get("target_sid")
                rec["producer_opcode"] = state.get("source_opcode")

                key = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("source_expr"),
                    rec.get("consumer_addr"),
                    rec.get("producer_addr"),
                )
                if key in seen:
                    continue
                seen.add(key)

                self.sgl_same_block_post_update_alias_events.append({
                    "kind": "sgl_same_block_post_update_alias",
                    "producer_addr": rec.get("producer_addr"),
                    "consumer_addr": rec.get("consumer_addr"),
                    "source_sid": rec.get("source_sid"),
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "source_expr": rec.get("source_expr"),
                    "condition_expr": rec.get("condition_expr"),
                })
                records.append(rec)

        return records

    def _pal_block_for_addr(self, addr):
        if addr is None:
            return None

        for block in getattr(self.func, "blocks", []) or []:
            if getattr(block, "addr", None) == addr:
                return block

        # Some layers expose cfg nodes instead of PAL blocks.  Accept the CFG
        # node's attached block if available.
        cfg = getattr(self.func, "cfg", None) or getattr(self, "cfg", None)
        nodes = getattr(cfg, "nodes", {}) if cfg is not None else {}
        node = nodes.get(addr) if isinstance(nodes, dict) else None
        if node is not None:
            block = getattr(node, "block", None)
            if block is not None:
                return block

        get_node = getattr(cfg, "get_node", None) if cfg is not None else None
        if callable(get_node):
            try:
                node = get_node(addr)
                block = getattr(node, "block", None) if node is not None else None
                if block is not None:
                    return block
            except Exception:
                pass

        return None



    # ---------------------------------------------------------
    # SGL-ADJACENT POST-UPDATE ALIAS CLOSURE
    # ---------------------------------------------------------

    def _sgl_adjacent_post_update_alias_records(self):
        """
        Derive post-update condition aliases from frozen SGL ordering.

        This is for RawCond/text conditions that are not ordinary FormulaNode
        consumers.  It walks the ExecTree and looks for:
            block with emitted state update expression
            immediately following if/loop condition containing that expression

        It emits metadata only.
        """

        root = getattr(self.func, "exec_root", None) or getattr(self.func, "exec_tree", None)
        if root is None:
            return []

        records = []
        seen = set()

        for producer_node, consumer_node in self._iter_sgl_adjacent_block_condition_pairs(root):
            producer_block = self._exec_block_to_pal_block(producer_node)
            if producer_block is None:
                continue

            consumer = self._consumer_record_from_exec_node(consumer_node)
            if consumer is None:
                continue

            cond_expr = str(consumer.get("cond_expr") or "")
            if not cond_expr:
                continue

            for state in self._state_update_records_for_block(producer_block):
                source_expr = state.get("source_expr")
                target_name = state.get("target_name")
                if not source_expr or not target_name:
                    continue

                if not self._condition_expr_contains_exact_formula(cond_expr, source_expr):
                    continue

                rec = self._make_post_update_condition_alias_record(
                    state.get("source_sid"),
                    consumer.get("cond_sid"),
                    source_expr,
                    target_name,
                    consumer,
                    "sgl_adjacent_state_write_condition_alias",
                    state.get("source_opcode"),
                )
                if rec is None:
                    continue

                rec["producer_addr"] = state.get("producer_addr")
                rec["target_sid"] = state.get("target_sid")
                rec["producer_opcode"] = state.get("source_opcode")

                key = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("source_expr"),
                    rec.get("consumer_addr"),
                    rec.get("producer_addr"),
                )
                if key in seen:
                    continue
                seen.add(key)

                self.sgl_adjacent_post_update_alias_events.append({
                    "kind": "sgl_adjacent_post_update_alias",
                    "producer_addr": rec.get("producer_addr"),
                    "consumer_addr": rec.get("consumer_addr"),
                    "source_sid": rec.get("source_sid"),
                    "target_name": rec.get("target_name"),
                    "source_expr": rec.get("source_expr"),
                    "condition_expr": rec.get("condition_expr"),
                })
                records.append(rec)

        return records

    def _iter_sgl_adjacent_block_condition_pairs(self, node):
        """
        Yield (previous_block_node, condition_node) pairs in the same SGL
        sequence/loop body container.  Recurses through nested structures.
        """

        if node is None:
            return

        children = list(getattr(node, "children", []) or [])
        last_block = None

        for child in children:
            kind = getattr(child, "kind", None)

            if kind == "block":
                last_block = child

            elif kind in ("if", "loop"):
                if last_block is not None and getattr(child, "cond_var", None) is not None:
                    yield (last_block, child)
                for pair in self._iter_sgl_adjacent_block_condition_pairs(child):
                    yield pair
                last_block = None

            else:
                for pair in self._iter_sgl_adjacent_block_condition_pairs(child):
                    yield pair
                # A nested sequence may end with a block, but without a stable
                # last-child contract exposed here we do not propagate it out.
                last_block = None

        for attr in ("body", "then_branch", "else_branch"):
            child = getattr(node, attr, None)
            if child is not None:
                for pair in self._iter_sgl_adjacent_block_condition_pairs(child):
                    yield pair

    def _exec_block_to_pal_block(self, exec_block):
        cfg_node = getattr(exec_block, "cfg_node", None)
        if cfg_node is None:
            return None
        return getattr(cfg_node, "block", None)

    def _consumer_record_from_exec_node(self, node):
        if node is None:
            return None

        kind = getattr(node, "kind", None)
        cond = getattr(node, "cond_var", None)
        cond_sid = self.sid_of(cond)

        cfg_node = getattr(node, "cfg_node", None)
        if cfg_node is None:
            cfg_node = getattr(node, "header", None)

        addr = getattr(cfg_node, "addr", None) if cfg_node is not None else None
        cond_expr = self._cond_expr_for_exec_node(cond)

        return {
            "kind": kind,
            "addr": addr,
            "role": getattr(node, "condition_role", None),
            "cond_sid": cond_sid,
            "cond_expr": cond_expr,
        }

    def _cond_expr_for_exec_node(self, cond):
        if cond is None:
            return ""

        # SGL RawCond/string-like constants.
        cv = getattr(cond, "const_value", None)
        if isinstance(cv, str):
            return cv

        if isinstance(cond, str):
            return cond

        # FormulaNode condition.
        if hasattr(cond, "var") and hasattr(cond, "opcode"):
            expr = self._expr_for_node(cond, seen=set())
            return expr or ""

        sid = self.sid_of(cond)
        if sid is not None:
            node = self.nodes.get(sid)
            if node is not None:
                expr = self._expr_for_node(node, seen=set())
                return expr or ""

        # Last resort: readable var name.  Do not use this for alias match
        # unless it happens to match exactly.
        return self.name_for_var(self.to_var(cond)) or str(cond)

    def _state_update_records_for_block(self, block):
        records = []

        if block is None:
            return records

        for op in list(getattr(block, "ops", []) or []):
            rec = self._state_update_record_for_op(block, op)
            if rec is not None:
                records.append(rec)

        return records

    def _state_update_record_for_op(self, block, op):
        if op is None:
            return None

        opcode = getattr(op, "opcode", None)
        if opcode not in self.PURE_INLINE_OPS:
            return None
        if opcode in self.COMPARE_OPS or opcode in ("BOOL_NEGATE",):
            return None

        out = getattr(op, "output", None)
        out_sid = self.sid_of(out)
        if out_sid is None:
            return None

        # The target name may be a real local output or a source alias mapped
        # by PHIfolder earlier, e.g. v_367 -> local_14.
        target_name = self.var_map.get(out_sid) or self.name_for_var(self.to_var(out))
        if not target_name:
            return None

        source_expr = self._expr_for_op(op, block=block, seen=set())
        if not source_expr:
            return None

        # Require that the source expression mentions the same target.  This
        # rejects plain assignments and unrelated pure temps.
        if not self._expr_mentions_name(source_expr, target_name):
            return None

        return {
            "kind": "sgl_adjacent_state_update",
            "producer_addr": getattr(block, "addr", None),
            "source_sid": out_sid,
            "target_sid": out_sid,
            "target_name": target_name,
            "source_expr": source_expr,
            "source_opcode": opcode,
        }


    # ---------------------------------------------------------
    # NULL EMPEROR EXACT MATERIALIZED CONSUMER CUSTODY (v31)
    # ---------------------------------------------------------


    # ---------------------------------------------------------
    # v32 GHOST-EMPEROR STRUCTURAL SNAPSHOT OWNER CUSTODY
    # ---------------------------------------------------------

    def _refresh_ghost_emperor_inputs_v32(self):
        self.ghost_emperor_sgl_bindings_v68 = dict(
            getattr(
                self.func,
                "sgl_ghost_emperor_loop_exit_snapshot_bindings_v68",
                {},
            ) or self.ghost_emperor_sgl_bindings_v68 or {}
        )

    def _consume_ghost_emperor_loop_exit_rebindings_v32(self, stage=None):
        self._refresh_ghost_emperor_inputs_v32()
        for key, raw in sorted(
            self.ghost_emperor_sgl_bindings_v68.items(),
            key=lambda item: str(item[0]),
        ):
            if not isinstance(raw, dict):
                continue
            sid = self._erase_emperor_sid_text_v29(
                raw.get("snapshot_sid") or key
            )
            source_sid = self._erase_emperor_sid_text_v29(
                raw.get("source_sid")
            )
            if sid is None or source_sid is None:
                self.ghost_emperor_warnings_v32.append({
                    "kind": "ghost_emperor_binding_missing_sid_v32",
                    "stage": stage,
                    "binding": dict(raw),
                })
                continue
            if sid not in self.erase_emperor_snapshot_sids_v29:
                self.ghost_emperor_warnings_v32.append({
                    "kind": "ghost_emperor_binding_not_snapshot_v32",
                    "stage": stage,
                    "snapshot_sid": sid,
                })
                continue

            name = str(raw.get("projection_name") or sid)
            binding = dict(raw)
            binding.update({
                "kind": "phi_ghost_emperor_loop_exit_snapshot_binding_v32",
                "version": self.ghost_emperor_version_v32,
                "snapshot_sid": sid,
                "source_sid": source_sid,
                "projection_name": name,
                "execution_owner": "loop_exit_snapshot_binding",
                "native_producer_emit": False,
                "value_materialized": True,
                "stage": stage,
            })
            self.ghost_emperor_loop_exit_snapshot_bindings_v32[sid] = binding
            self.ghost_emperor_native_producer_sids_v32.add(sid)
            self.ghost_emperor_native_capture_suppressions_v32[sid] = {
                "snapshot_sid": sid,
                "capture_block_addr": binding.get("capture_block_addr"),
                "native_capture_op_id": binding.get("native_capture_op_id"),
                "replacement_owner": "loop_exit_snapshot_binding",
            }

            self.var_map[sid] = name
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self.phi_source_foldable_sids.discard(sid)
            self.prefer_var_expr_sids.add(sid)
            self._set_ssa_policy(
                sid,
                "ghost_emperor_loop_exit_snapshot",
                emit=True,
                expr_mode="var",
                reason=(
                    "snapshot value is defined once by SGL-owned loop-exit "
                    "binding; native repeating COPY is not the final owner"
                ),
                target_name=name,
            )
            node = self.nodes.get(sid)
            if node is not None:
                try:
                    node.ghost_emperor_loop_exit_binding_v32 = binding
                    node.snapshot_execution_owner_v32 = (
                        "loop_exit_snapshot_binding"
                    )
                    node.native_snapshot_producer_emit_v32 = False
                    var = self.to_var(node)
                    if var is not None:
                        var.ghost_emperor_loop_exit_binding_v32 = binding
                        var.snapshot_execution_owner_v32 = (
                            "loop_exit_snapshot_binding"
                        )
                        var.native_snapshot_producer_emit_v32 = False
                except Exception:
                    pass

            self.ghost_emperor_events_v32.append({
                "kind": "ghost_emperor_structural_owner_consumed_v32",
                "stage": stage,
                "snapshot_sid": sid,
                "source_sid": source_sid,
                "loop_header_addr": binding.get("loop_header_addr"),
                "projection_name": name,
            })

    def _finalize_ghost_emperor_compute_bindings_v32(self):
        for sid, binding in self.ghost_emperor_loop_exit_snapshot_bindings_v32.items():
            compute = self.compute_bindings_by_sid.get(sid)
            if not isinstance(compute, dict):
                continue
            compute["execution_mode"] = "loop_exit_snapshot_binding"
            compute["effective_target_sid"] = sid
            compute["effective_target_name"] = binding.get(
                "projection_name", sid
            )
            compute["native_producer_emit"] = False
            compute["structural_execution_owner"] = dict(binding)
            node = self.nodes.get(sid)
            if node is not None:
                try:
                    node.phi_compute_binding = compute
                    var = self.to_var(node)
                    if var is not None:
                        var.phi_compute_binding = compute
                except Exception:
                    pass

    def _audit_ghost_emperor_structural_snapshot_owners_v32(self):
        failures = []
        for sid, binding in sorted(
            self.ghost_emperor_loop_exit_snapshot_bindings_v32.items(),
            key=lambda item: str(item[0]),
        ):
            policy = dict(self.ssa_policy_by_sid.get(sid, {}) or {})
            gates = {
                "snapshot_identity_retained": (
                    sid in self.erase_emperor_snapshot_sids_v29
                ),
                "exact_projection_retained": (
                    self.var_map.get(sid) == binding.get("projection_name")
                ),
                "value_materialized": sid in self.materialize_sids,
                "native_site_not_global_suppression": (
                    sid not in self.suppress_assign_sids
                ),
                "native_producer_emit_false": (
                    binding.get("native_producer_emit") is False
                ),
                "execution_owner_loop_exit": (
                    binding.get("execution_owner")
                    == "loop_exit_snapshot_binding"
                ),
                "policy_var_reference": policy.get("expr_mode") == "var",
                "not_state_alias": sid not in self.state_transition_alias_sids,
            }
            failed = [name for name, ok in gates.items() if not ok]
            if failed:
                failures.append({
                    "kind": "ghost_emperor_structural_owner_failure_v32",
                    "snapshot_sid": sid,
                    "failed_gates": failed,
                    "binding": dict(binding),
                    "policy": policy,
                })

        self.ghost_emperor_audit_v32 = {
            "kind": (
                "ghost_emperor_structural_snapshot_owner_verified_v32"
                if not failures else
                "ghost_emperor_structural_snapshot_owner_failed_v32"
            ),
            "version": self.ghost_emperor_version_v32,
            "active": bool(self.ghost_emperor_loop_exit_snapshot_bindings_v32),
            "bindings": len(self.ghost_emperor_loop_exit_snapshot_bindings_v32),
            "failures": failures,
            "rule": (
                "snapshot_value_survives_but_native_COPY_owner_transfers_"
                "atomically_to_exact_SGL_loop_exit"
            ),
        }
        self.ghost_emperor_events_v32.append(
            dict(self.ghost_emperor_audit_v32)
        )
        if failures:
            raise RuntimeError(
                "PALPHIfolder v32 ghost-emperor custody failed: %s"
                % failures
            )
        return self.ghost_emperor_audit_v32

    def _refresh_null_emperor_inputs_v31(self):
        sgl = dict(
            getattr(
                self.func,
                "sgl_null_emperor_derived_contracts_v67",
                {},
            )
            or self.null_emperor_sgl_contracts_v67
            or {}
        )
        contracts = {}
        projections = {}
        result_sids = set()

        for key, rec in list(sgl.items()):
            if not isinstance(rec, dict):
                continue
            sid = self._erase_emperor_sid_text_v29(
                rec.get("result_sid") or key
            )
            if sid is None:
                continue
            item = dict(rec)
            item["result_sid"] = sid
            projection = str(item.get("projection_name") or sid)
            item["projection_name"] = projection
            contracts[sid] = item
            projections[sid] = projection
            result_sids.add(sid)

        # Compatibility: when PHIfolder is paired with pre-v67 SGL, retain the
        # same exact derived identities from SemanticGraph v35/v29 contracts.
        # The audit records that the SGL text boundary is not independently
        # proven, but metadata rendering still stops at the materialized SID.
        for sid in list(self.erase_emperor_derived_result_sids_v29 or []):
            sid = self._erase_emperor_sid_text_v29(sid)
            if sid is None or sid in contracts:
                continue
            info = self._erase_emperor_derived_info_for_sid_v29(sid)
            contracts[sid] = {
                "kind": "null_emperor_derived_value_boundary_v31_compat",
                "version": self.null_emperor_version_v31,
                "result_sid": sid,
                "projection_name": sid,
                "consumer_opcode": info.get("consumer_opcode"),
                "snapshot_sids": list(info.get("snapshot_sids", []) or []),
                "source_sids": list(info.get("source_sids", []) or []),
                "later_epoch_sids": list(
                    info.get("later_epoch_sids", []) or []
                ),
                "materialization_required": True,
                "formula_inline_allowed": False,
                "authority": "PHIfolder_v29_compatibility_without_SGL_v67",
                "sgl_boundary_proven": False,
            }
            projections[sid] = sid
            result_sids.add(sid)

        self.null_emperor_sgl_contracts_v67 = sgl
        self.null_emperor_derived_contracts_v31 = contracts
        self.null_emperor_derived_result_sids_v31 = result_sids
        self.null_emperor_projection_names_by_sid_v31 = projections
        return contracts

    def _null_emperor_contract_for_value_v31(self, value):
        sid = self._erase_emperor_sid_text_v29(value)
        if sid is None:
            return None
        rec = self.null_emperor_derived_contracts_v31.get(sid)
        return rec if isinstance(rec, dict) else None

    def _null_emperor_projection_for_value_v31(self, value):
        rec = self._null_emperor_contract_for_value_v31(value)
        if not isinstance(rec, dict):
            return None
        if not bool(rec.get("materialization_required", True)):
            return None
        if bool(rec.get("formula_inline_allowed", False)):
            return None
        sid = self._erase_emperor_sid_text_v29(
            rec.get("result_sid") or value
        )
        name = (
            self.var_map.get(sid)
            or rec.get("projection_name")
            or sid
        )
        return str(name) if name is not None else None

    def _consume_null_emperor_derived_boundaries_v31(self, stage):
        contracts = self._refresh_null_emperor_inputs_v31()
        for sid, rec in sorted(contracts.items(), key=lambda item: str(item[0])):
            projection = str(rec.get("projection_name") or sid)
            current = self.var_map.get(sid)
            forbidden = self._vanquish_emperor_forbidden_state_names_v30(sid)
            if current and str(current) not in forbidden:
                projection = str(current)
            elif projection in forbidden:
                projection = sid

            self.var_map[sid] = projection
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self.phi_source_foldable_sids.discard(sid)
            self.prefer_var_expr_sids.add(sid)
            self._set_ssa_policy(
                sid,
                "null_emperor_exact_materialized_consumer",
                emit=True,
                expr_mode="var",
                reason=(
                    "materialized snapshot-derived value is consumed by its "
                    "exact SID, never by recursive producer expansion"
                ),
                target_name=projection,
            )
            rec["projection_name"] = projection
            self.null_emperor_projection_names_by_sid_v31[sid] = projection
            self.null_emperor_events_v31.append({
                "kind": "null_emperor_derived_boundary_consumed_v31",
                "version": self.null_emperor_version_v31,
                "stage": stage,
                "result_sid": sid,
                "projection_name": projection,
                "sgl_boundary_proven": bool(
                    sid in self.null_emperor_sgl_contracts_v67
                ),
            })
        return len(contracts)

    def _null_emperor_condition_consumers_v31(self, sid):
        out = []
        for consumer in list(self.consumer_nodes_by_sid.get(sid, []) or []):
            consumer_sid = self._erase_emperor_sid_text_v29(consumer)
            if consumer_sid in self.condition_dependency_sids:
                out.append(consumer)
                continue
            if self.is_condition(consumer):
                out.append(consumer)
        return out

    def _audit_null_emperor_materialized_consumers_v31(self):
        contracts = self._refresh_null_emperor_inputs_v31()
        failures = []
        checked = []
        for sid, rec in sorted(contracts.items(), key=lambda item: str(item[0])):
            projection = self._null_emperor_projection_for_value_v31(sid)
            producer = self._erase_emperor_node_for_sid_v29(sid)
            producer_expr = (
                self._expr_for_node(producer, seen=set())
                if producer is not None else None
            )
            consumers = self._null_emperor_condition_consumers_v31(sid)
            consumer_rows = []
            for consumer in consumers:
                expr = self._expr_for_node(consumer, seen=set())
                has_projection = bool(
                    projection
                    and re.search(
                        r"\b%s\b" % re.escape(str(projection)),
                        str(expr or ""),
                    )
                )
                producer_reexpanded = bool(
                    producer_expr
                    and producer_expr != projection
                    and self._normalize_expr_text(producer_expr)
                    in self._normalize_expr_text(expr)
                    and not has_projection
                )
                row = {
                    "consumer_sid": self._erase_emperor_sid_text_v29(consumer),
                    "consumer_opcode": getattr(consumer, "opcode", None),
                    "condition_expr": expr,
                    "projection_present": has_projection,
                    "producer_reexpanded": producer_reexpanded,
                }
                consumer_rows.append(row)
                if not has_projection or producer_reexpanded:
                    failures.append({
                        "kind": "null_emperor_condition_consumer_reexpanded_v31",
                        "result_sid": sid,
                        "projection_name": projection,
                        "producer_expr": producer_expr,
                        "consumer": row,
                    })

            item = {
                "result_sid": sid,
                "projection_name": projection,
                "producer_expr": producer_expr,
                "materialized": sid in self.materialize_sids,
                "policy": dict(self.ssa_policy_by_sid.get(sid, {}) or {}),
                "condition_consumers": consumer_rows,
                "sgl_boundary_proven": sid in self.null_emperor_sgl_contracts_v67,
            }
            checked.append(item)
            if sid not in self.materialize_sids:
                failures.append({
                    "kind": "null_emperor_result_not_materialized_v31",
                    "state": item,
                })

        audit = {
            "kind": (
                "null_emperor_materialized_consumer_custody_verified_v31"
                if not failures
                else "null_emperor_materialized_consumer_custody_failed_v31"
            ),
            "version": self.null_emperor_version_v31,
            "active": bool(contracts),
            "contracts": len(contracts),
            "checked": checked,
            "failures": failures,
            "snapshot_capture_moved": False,
            "rule": (
                "keep_exact_snapshot_capture_then_consume_materialized_"
                "derived_result_by_SID_without_recursive_recomputation"
            ),
        }
        self.null_emperor_audit_v31 = audit
        self.null_emperor_events_v31.append(dict(audit))

        # Do not convert a pre-v67 SGL pairing into another matrix-wide hard
        # stop.  Exact v67 handoff failures remain fatal; compatibility-only
        # records are published as diagnostics for staged deployment.
        fatal = [
            item for item in failures
            if item.get("result_sid") in self.null_emperor_sgl_contracts_v67
        ]
        if fatal:
            raise RuntimeError(
                "PALPHIfolder v31 null-emperor consumer custody failed: %s"
                % fatal
            )
        return audit

    # ---------------------------------------------------------
    # ERASE EMPEROR TEMPORAL SNAPSHOT CUSTODY (v29)
    # ---------------------------------------------------------

    def _erase_emperor_sid_text_v29(self, value):
        if value is None:
            return None
        try:
            sid = self.sid_of(value)
        except Exception:
            sid = None
        if sid is None:
            sid = getattr(value, "ssa_id", value)
        if sid is None:
            return None
        text = str(sid)
        if text.startswith(("v_", "c_")):
            return text
        if text.isdigit():
            return "v_%s" % text
        return text

    def _erase_emperor_sid_variants_v29(self, value):
        text = self._erase_emperor_sid_text_v29(value)
        if text is None:
            return []
        values = [text]
        if text.startswith("v_") and text[2:].isdigit():
            values.extend([text[2:], int(text[2:])])
        elif text.isdigit():
            values.extend(["v_%s" % text, int(text)])
        out = []
        seen = set()
        for item in values:
            marker = (type(item).__name__, str(item))
            if marker in seen:
                continue
            seen.add(marker)
            out.append(item)
        return out

    def _erase_emperor_node_for_sid_v29(self, sid):
        for key in self._erase_emperor_sid_variants_v29(sid):
            try:
                node = self.nodes.get(key)
            except Exception:
                node = None
            if node is not None:
                return node
            try:
                node = self.nodes.get(str(key))
            except Exception:
                node = None
            if node is not None:
                return node
        return None

    def _refresh_erase_emperor_snapshot_inputs_v29(self):
        semantic = dict(
            getattr(self.func, "snapshot_copy_contracts_v35", {})
            or self.erase_emperor_semantic_snapshot_contracts_v35
            or {}
        )
        sgl = dict(
            getattr(self.func, "sgl_snapshot_copy_contracts_v66", {})
            or self.erase_emperor_sgl_snapshot_contracts_v66
            or {}
        )
        projections = dict(
            getattr(
                self.func,
                "snapshot_copy_projection_names_by_sid_v35",
                {},
            )
            or self.erase_emperor_snapshot_projection_names_v29
            or {}
        )
        sgl_projections = dict(
            getattr(
                self.func,
                "sgl_snapshot_copy_projection_names_by_sid_v66",
                {},
            )
            or {}
        )
        projections.update(sgl_projections)

        unique = {}
        for mapping in (semantic, sgl):
            for rec in list(mapping.values()):
                if not isinstance(rec, dict):
                    continue
                sid = self._erase_emperor_sid_text_v29(
                    rec.get("snapshot_sid")
                )
                if sid is None:
                    continue
                existing = unique.get(sid)
                if existing is None:
                    unique[sid] = dict(rec)
                    continue
                # SGL forwards the same semantic contract.  Merge only missing
                # fields so no downstream layer can silently weaken v35 proof.
                merged = dict(existing)
                for key, value in rec.items():
                    if key not in merged or merged.get(key) is None:
                        merged[key] = value
                unique[sid] = merged

        contracts = {}
        snapshot_sids = set()
        snapshot_info = {}
        derived_sids = set()
        derived_info = {}

        for sid, rec in unique.items():
            projection = rec.get("projection_name")
            if not projection:
                for key in self._erase_emperor_sid_variants_v29(sid):
                    projection = projections.get(key)
                    if projection is None:
                        projection = projections.get(str(key))
                    if projection:
                        break
            if not projection:
                projection = sid

            rec = dict(rec)
            rec["snapshot_sid"] = sid
            rec["projection_name"] = str(projection)
            contracts[sid] = rec
            snapshot_sids.add(sid)
            snapshot_info[sid] = {
                "snapshot_sid": sid,
                "source_sid": self._erase_emperor_sid_text_v29(
                    rec.get("source_sid")
                ),
                "projection_name": str(projection),
                "capture_block_addr": rec.get("capture_block_addr"),
                "materialization_required": bool(
                    rec.get("materialization_required", True)
                ),
                "transparent_copy_allowed": bool(
                    rec.get("transparent_copy_allowed", False)
                ),
                "semantic_identity": rec.get("semantic_identity"),
                "contract": rec,
            }

            for joint in list(rec.get("joint_consumers", []) or []):
                if not isinstance(joint, dict):
                    continue
                consumer_sid = self._erase_emperor_sid_text_v29(
                    joint.get("consumer_sid")
                )
                if consumer_sid is None:
                    continue
                derived_sids.add(consumer_sid)
                info = derived_info.setdefault(consumer_sid, {
                    "consumer_sid": consumer_sid,
                    "consumer_opcode": joint.get("consumer_opcode"),
                    "snapshot_sids": [],
                    "source_sids": [],
                    "later_epoch_sids": [],
                    "joint_consumers": [],
                    "reason": (
                        "order-sensitive result derives from a protected "
                        "historical epoch and a later dependent state epoch"
                    ),
                })
                if sid not in info["snapshot_sids"]:
                    info["snapshot_sids"].append(sid)
                source_sid = self._erase_emperor_sid_text_v29(
                    rec.get("source_sid")
                )
                if source_sid and source_sid not in info["source_sids"]:
                    info["source_sids"].append(source_sid)
                later_sid = self._erase_emperor_sid_text_v29(
                    joint.get("later_epoch_sid")
                )
                if later_sid and later_sid not in info["later_epoch_sids"]:
                    info["later_epoch_sids"].append(later_sid)
                info["joint_consumers"].append(dict(joint))
                # Compatibility singular fields for compact diagnostics.
                info["later_epoch_sid"] = (
                    info["later_epoch_sids"][0]
                    if info["later_epoch_sids"] else None
                )
                info["source_sid"] = (
                    info["source_sids"][0]
                    if info["source_sids"] else None
                )

        self.erase_emperor_semantic_snapshot_contracts_v35 = semantic
        self.erase_emperor_sgl_snapshot_contracts_v66 = sgl
        self.erase_emperor_snapshot_projection_names_v29 = projections
        self.erase_emperor_snapshot_contracts_v29 = contracts
        self.erase_emperor_snapshot_sids_v29 = snapshot_sids
        self.erase_emperor_snapshot_info_v29 = snapshot_info
        self.erase_emperor_derived_result_sids_v29 = derived_sids
        self.erase_emperor_derived_result_info_v29 = derived_info
        return contracts

    def _erase_emperor_snapshot_contract_for_value_v29(self, value):
        direct = getattr(value, "snapshot_copy_contract_v35", None)
        if isinstance(direct, dict):
            return direct
        node = self.to_node(value)
        if node is not None:
            direct = getattr(node, "snapshot_copy_contract_v35", None)
            if isinstance(direct, dict):
                return direct
            direct = getattr(
                getattr(node, "var", None),
                "snapshot_copy_contract_v35",
                None,
            )
            if isinstance(direct, dict):
                return direct
        var = self.to_var(value)
        direct = getattr(var, "snapshot_copy_contract_v35", None)
        if isinstance(direct, dict):
            return direct
        sid = self._erase_emperor_sid_text_v29(value)
        return self.erase_emperor_snapshot_contracts_v29.get(sid)

    def _erase_emperor_projection_for_value_v29(self, value):
        rec = self._erase_emperor_snapshot_contract_for_value_v29(value)
        if not isinstance(rec, dict):
            return None
        if not bool(rec.get("materialization_required", True)):
            return None
        if bool(rec.get("transparent_copy_allowed", False)):
            return None
        name = rec.get("projection_name")
        if name:
            return str(name)
        sid = self._erase_emperor_sid_text_v29(
            rec.get("snapshot_sid") or value
        )
        return sid

    def _erase_emperor_is_snapshot_sid_v29(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        return bool(text and text in self.erase_emperor_snapshot_sids_v29)

    def _erase_emperor_is_snapshot_value_v29(self, value):
        return isinstance(
            self._erase_emperor_snapshot_contract_for_value_v29(value),
            dict,
        )

    def _erase_emperor_snapshot_info_for_sid_v29(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        return dict(self.erase_emperor_snapshot_info_v29.get(text, {}) or {})

    def _erase_emperor_is_derived_result_sid_v29(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        return bool(
            text and text in self.erase_emperor_derived_result_sids_v29
        )

    def _erase_emperor_derived_info_for_sid_v29(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        return dict(
            self.erase_emperor_derived_result_info_v29.get(text, {}) or {}
        )

    def _erase_emperor_snapshot_dependencies_for_node_v29(
        self, node, seen=None, depth=0, max_depth=16,
    ):
        if node is None or depth > max_depth:
            return set()
        if seen is None:
            seen = set()
        sid = self._erase_emperor_sid_text_v29(node)
        marker = sid if sid is not None else "node:%s" % id(node)
        if marker in seen:
            return set()
        seen.add(marker)

        found = set()
        if self._erase_emperor_is_snapshot_value_v29(node):
            snapshot_sid = self._erase_emperor_sid_text_v29(node)
            if snapshot_sid:
                found.add(snapshot_sid)
            return found

        for value in list(getattr(node, "inputs", []) or []):
            if self._erase_emperor_is_snapshot_value_v29(value):
                snapshot_sid = self._erase_emperor_sid_text_v29(value)
                if snapshot_sid:
                    found.add(snapshot_sid)
                continue
            child = self.to_node(value)
            if child is not None:
                found.update(
                    self._erase_emperor_snapshot_dependencies_for_node_v29(
                        child,
                        seen=set(seen),
                        depth=depth + 1,
                        max_depth=max_depth,
                    )
                )
        return found

    def _erase_emperor_name_for_sid_v29(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        if text is None:
            return None
        for key in self._erase_emperor_sid_variants_v29(text):
            name = self.var_map.get(key)
            if name:
                return str(name)
            name = self.var_map.get(str(key))
            if name:
                return str(name)
        node = self._erase_emperor_node_for_sid_v29(text)
        return self.name_for_var(self.to_var(node)) if node is not None else None

    def _erase_emperor_alias_targets_snapshot_state_v29(
        self, source_sid, target_sid=None, target_name=None,
    ):
        info = self._erase_emperor_derived_info_for_sid_v29(source_sid)
        state_sids = set(info.get("source_sids", []) or [])
        state_sids.update(info.get("later_epoch_sids", []) or [])
        state_sids.update(info.get("snapshot_sids", []) or [])
        target_text = self._erase_emperor_sid_text_v29(target_sid)
        if target_text and target_text in state_sids:
            return True
        if target_name:
            state_names = {
                self._erase_emperor_name_for_sid_v29(sid)
                for sid in state_sids
            }
            state_names.discard(None)
            if str(target_name) in state_names:
                return True
        return False

    def _record_erase_emperor_derived_alias_rejection_v29(
        self, source_sid, target_sid, owner, pred_addr=None, join_addr=None,
        target_name=None,
    ):
        source_text = self._erase_emperor_sid_text_v29(source_sid)
        target_text = self._erase_emperor_sid_text_v29(target_sid)
        if source_text is None:
            return None
        event = {
            "kind": "erase_emperor_snapshot_derived_state_alias_rejected_v29",
            "version": self.erase_emperor_snapshot_version_v29,
            "source_sid": source_text,
            "target_sid": target_text,
            "target_name": target_name,
            "owner": str(owner),
            "pred_addr": pred_addr,
            "join_addr": join_addr,
            "derived_info": self._erase_emperor_derived_info_for_sid_v29(
                source_text
            ),
            "reason": (
                "order-sensitive snapshot/later-epoch result is an independent "
                "derived value, not the next state of either operand"
            ),
        }
        marker = (
            source_text,
            target_text,
            str(target_name),
            str(owner),
            pred_addr,
            join_addr,
        )
        existing = {
            (
                item.get("source_sid"),
                item.get("target_sid"),
                str(item.get("target_name")),
                str(item.get("owner")),
                item.get("pred_addr"),
                item.get("join_addr"),
            )
            for item in self.erase_emperor_snapshot_events_v29
            if isinstance(item, dict)
            and item.get("kind")
            == "erase_emperor_snapshot_derived_state_alias_rejected_v29"
        }
        if marker not in existing:
            self.erase_emperor_snapshot_events_v29.append(event)
        self.erase_emperor_rejected_state_alias_sids_v29.add(source_text)
        return event

    def _vanquish_emperor_protected_sids_v30(self):
        return {
            self._erase_emperor_sid_text_v29(value)
            for value in (
                list(self.erase_emperor_snapshot_sids_v29)
                + list(self.erase_emperor_derived_result_sids_v29)
            )
            if self._erase_emperor_sid_text_v29(value) is not None
        }

    def _vanquish_emperor_forbidden_state_sids_v30(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        info = self._erase_emperor_derived_info_for_sid_v29(text)
        out = set()
        for key in ("source_sids", "later_epoch_sids", "snapshot_sids"):
            for value in list(info.get(key, []) or []):
                value = self._erase_emperor_sid_text_v29(value)
                if value is not None:
                    out.add(value)
        return out

    def _vanquish_emperor_forbidden_state_names_v30(self, sid):
        names = {
            self._erase_emperor_name_for_sid_v29(value)
            for value in self._vanquish_emperor_forbidden_state_sids_v30(sid)
        }
        names.discard(None)
        return {str(value) for value in names}

    def _vanquish_emperor_snapshot_value_expr_v30(self, value):
        """Return the independent name used when a snapshot is referenced."""
        return self._erase_emperor_projection_for_value_v29(value)

    def _vanquish_emperor_snapshot_copy_rhs_v30(self, value):
        """Return the captured epoch expression for a snapshot COPY producer."""
        node = self.to_node(value)
        if node is None and hasattr(value, "opcode"):
            node = value
        if node is None or getattr(node, "opcode", None) != "COPY":
            return None
        inputs = list(getattr(node, "inputs", []) or [])
        if not inputs:
            return None
        return self._value_expr_for_metadata(inputs[0], seen=set())

    def _vanquish_emperor_alias_fingerprint_v30(self):
        """Stable, diagnostic-only view of alias ownership tables."""
        out = {}
        for map_name in (
            "state_transition_aliases",
            "phi_source_aliases",
            "temp_phi_source_aliases",
            "post_update_aliases",
            "post_update_consumer_aliases",
            "duplicate_phi_cleanup_alias_info",
        ):
            mapping = getattr(self, map_name, {}) or {}
            rows = []
            for key, info in list(mapping.items()):
                if isinstance(info, dict):
                    rows.append((
                        str(key),
                        self._erase_emperor_sid_text_v29(info.get("target_sid")),
                        str(info.get("target_name")),
                        info.get("pred_addr"),
                        info.get("join_addr"),
                        self._erase_emperor_sid_text_v29(info.get("source_sid")),
                    ))
                else:
                    rows.append((str(key), None, str(info), None, None, None))
            out[map_name] = tuple(sorted(rows, key=str))
        return out

    def _vanquish_emperor_alias_records_for_sid_v30(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        if text is None:
            return []
        records = []
        seen = set()
        for map_name in (
            "state_transition_aliases",
            "phi_source_aliases",
            "temp_phi_source_aliases",
            "post_update_aliases",
        ):
            mapping = getattr(self, map_name, {}) or {}
            for key, info in list(mapping.items()):
                if self._erase_emperor_sid_text_v29(key) != text:
                    continue
                info = dict(info or {}) if isinstance(info, dict) else {}
                rec = {
                    "owner": map_name,
                    "mapping_key": key,
                    "source_sid": text,
                    "target_sid": self._erase_emperor_sid_text_v29(
                        info.get("target_sid")
                    ),
                    "target_name": info.get("target_name"),
                    "pred_addr": info.get("pred_addr"),
                    "join_addr": info.get("join_addr"),
                    "alias_info": info,
                }
                marker = (
                    rec["source_sid"], rec["target_sid"],
                    str(rec["target_name"]), rec["pred_addr"],
                    rec["join_addr"], rec["owner"], str(key),
                )
                if marker not in seen:
                    seen.add(marker)
                    records.append(rec)

        # A closure pass can leave only set membership.  Preserve that fact as
        # an owner record so the transaction still removes it deliberately.
        if text in {
            self._erase_emperor_sid_text_v29(value)
            for value in self.state_transition_alias_sids
        } and not any(rec.get("owner") == "state_transition_aliases" for rec in records):
            info = dict(self.state_transition_aliases.get(text, {}) or {})
            records.append({
                "owner": "state_transition_alias_sids",
                "mapping_key": text,
                "source_sid": text,
                "target_sid": self._erase_emperor_sid_text_v29(
                    info.get("target_sid")
                ),
                "target_name": info.get("target_name"),
                "pred_addr": info.get("pred_addr"),
                "join_addr": info.get("join_addr"),
                "alias_info": info,
            })
        return records

    def _vanquish_emperor_matching_dropins_v30(self, alias):
        source_sid = self._erase_emperor_sid_text_v29(alias.get("source_sid"))
        target_sid = self._erase_emperor_sid_text_v29(alias.get("target_sid"))
        pred_addr = alias.get("pred_addr")
        join_addr = alias.get("join_addr")
        matches = []
        for rec in list(self.phi_dropins or []):
            if not isinstance(rec, dict):
                continue
            if self._erase_emperor_sid_text_v29(rec.get("source_sid")) != source_sid:
                continue
            if target_sid is not None and self._erase_emperor_sid_text_v29(
                rec.get("target_sid")
            ) != target_sid:
                continue
            if pred_addr is not None and rec.get("pred_addr") != pred_addr:
                continue
            if join_addr is not None and rec.get("join_addr") != join_addr:
                continue
            matches.append(rec)
        return matches

    def _vanquish_emperor_restore_dropin_v30(self, rec, alias, reason):
        rid = self._phi_record_id(rec)
        rec.pop("source_aliased_to_target", None)
        rec.pop("accounted_for_by_state_alias", None)
        rec.pop("dropin_suppressed_reason", None)
        rec["dropin_required"] = True
        rec["must_print_override"] = True
        rec["must_print_reason"] = reason
        rec["vanquish_emperor_restored_owner_v30"] = True
        rec["vanquish_emperor_replaced_alias_owner_v30"] = alias.get("owner")

        self.required_phi_dropin_ids.add(rid)
        self.non_suppressible_dropin_ids.add(rid)
        source_sid = rec.get("source_sid")
        if source_sid is not None:
            self.executable_dropin_source_sids.add(source_sid)
            self.dropin_suppressed_by_source_alias.discard(source_sid)
        tuple_key = (
            rec.get("pred_addr"), rec.get("join_addr"),
            rec.get("target_sid"), rec.get("source_sid"),
        )
        self.dropin_suppressed_by_source_alias.discard(tuple_key)

        compact = {
            "kind": "vanquish_emperor_restored_phi_dropin_v30",
            "version": self.vanquish_emperor_version_v30,
            "id": rid,
            "source_sid": self._erase_emperor_sid_text_v29(rec.get("source_sid")),
            "target_sid": self._erase_emperor_sid_text_v29(rec.get("target_sid")),
            "target_name": rec.get("target_name"),
            "pred_addr": rec.get("pred_addr"),
            "join_addr": rec.get("join_addr"),
            "replaced_alias_owner": alias.get("owner"),
            "reason": reason,
        }
        if rid not in {
            item.get("id") for item in self.vanquish_emperor_restored_dropins_v30
        }:
            self.vanquish_emperor_restored_dropins_v30.append(compact)
        if rid not in {item.get("id") for item in self.required_phi_dropin_records}:
            self.required_phi_dropin_records.append(dict(compact))
        if rid not in {item.get("id") for item in self.non_suppressible_dropin_records}:
            self.non_suppressible_dropin_records.append(dict(compact))
        return compact

    def _vanquish_emperor_remove_exact_alias_v30(self, alias):
        source_sid = self._erase_emperor_sid_text_v29(alias.get("source_sid"))
        target_sid = self._erase_emperor_sid_text_v29(alias.get("target_sid"))
        target_name = alias.get("target_name")
        pred_addr = alias.get("pred_addr")
        join_addr = alias.get("join_addr")
        owner = alias.get("owner")
        removed = []

        def matches(info):
            if not isinstance(info, dict):
                return target_sid is None and target_name is None
            info_target = self._erase_emperor_sid_text_v29(info.get("target_sid"))
            if target_sid is not None and info_target != target_sid:
                return False
            if target_name is not None and str(info.get("target_name")) != str(target_name):
                return False
            if pred_addr is not None and info.get("pred_addr") != pred_addr:
                return False
            if join_addr is not None and info.get("join_addr") != join_addr:
                return False
            return True

        mapping = getattr(self, owner, None)
        key = alias.get("mapping_key")
        if isinstance(mapping, dict) and key in mapping and matches(mapping.get(key)):
            mapping.pop(key, None)
            removed.append((owner, key))

        # Remove exact companion entries, never mappings belonging to another
        # source SID or target transition.
        for map_name in (
            "state_transition_aliases",
            "phi_source_aliases",
            "temp_phi_source_aliases",
            "post_update_aliases",
            "duplicate_phi_cleanup_alias_info",
        ):
            companion = getattr(self, map_name, None)
            if not isinstance(companion, dict):
                continue
            for companion_key, info in list(companion.items()):
                if self._erase_emperor_sid_text_v29(companion_key) != source_sid:
                    continue
                if matches(info):
                    companion.pop(companion_key, None)
                    removed.append((map_name, companion_key))

        # Consumer aliases are keyed by consumer SID; remove only records that
        # explicitly name this protected source and this same target.
        mapping = getattr(self, "post_update_consumer_aliases", None)
        if isinstance(mapping, dict):
            for consumer_key, info in list(mapping.items()):
                if not isinstance(info, dict):
                    continue
                if self._erase_emperor_sid_text_v29(info.get("source_sid")) != source_sid:
                    continue
                if target_name is not None and str(info.get("target_name")) != str(target_name):
                    continue
                mapping.pop(consumer_key, None)
                removed.append(("post_update_consumer_aliases", consumer_key))
                self.post_update_consumer_sids.discard(consumer_key)

        for set_name in (
            "state_transition_alias_sids",
            "phi_source_alias_sids",
            "temp_phi_source_alias_sids",
            "post_update_alias_sids",
            "post_update_condition_alias_sids",
        ):
            values = getattr(self, set_name, None)
            if isinstance(values, set):
                for item in list(values):
                    if self._erase_emperor_sid_text_v29(item) == source_sid:
                        values.discard(item)
                        removed.append((set_name, item))

        self.post_update_condition_aliases = [
            rec for rec in list(self.post_update_condition_aliases or [])
            if not (
                isinstance(rec, dict)
                and self._erase_emperor_sid_text_v29(rec.get("source_sid")) == source_sid
                and (target_name is None or str(rec.get("target_name")) == str(target_name))
            )
        ]
        self.duplicate_phi_cleanup_alias_sids.discard(source_sid)
        self.dropin_suppressed_by_source_alias.discard(source_sid)
        for item in list(self.dropin_suppressed_by_source_alias):
            if (
                isinstance(item, tuple)
                and item
                and self._erase_emperor_sid_text_v29(item[-1]) == source_sid
            ):
                if target_sid is None or (
                    len(item) >= 2
                    and self._erase_emperor_sid_text_v29(item[-2]) == target_sid
                ):
                    self.dropin_suppressed_by_source_alias.discard(item)
                    removed.append(("dropin_suppressed_by_source_alias", item))
        return removed

    def _vanquish_emperor_reject_alias_transaction_v30(
        self, alias, reason, stage,
    ):
        source_sid = self._erase_emperor_sid_text_v29(alias.get("source_sid"))
        if source_sid is None:
            return None
        matches = self._vanquish_emperor_matching_dropins_v30(alias)
        restored = [
            self._vanquish_emperor_restore_dropin_v30(rec, alias, reason)
            for rec in matches
        ]
        removed = self._vanquish_emperor_remove_exact_alias_v30(alias)

        # The defining operation now owns the protected source value under its
        # exact SID.  A restored drop-in separately owns any PHI transition.
        self.must_emit_state_write_sids.discard(source_sid)
        self.state_write_info.pop(source_sid, None)
        self.materialize_sids.add(source_sid)
        self.suppress_assign_sids.discard(source_sid)
        self.inline_only_sids.discard(source_sid)
        self.phi_source_foldable_sids.discard(source_sid)
        self.prefer_var_expr_sids.add(source_sid)

        receipt = {
            "kind": "vanquish_emperor_alias_rejected_owner_restored_v30",
            "version": self.vanquish_emperor_version_v30,
            "stage": stage,
            "source_sid": source_sid,
            "target_sid": self._erase_emperor_sid_text_v29(alias.get("target_sid")),
            "target_name": alias.get("target_name"),
            "pred_addr": alias.get("pred_addr"),
            "join_addr": alias.get("join_addr"),
            "alias_owner": alias.get("owner"),
            "removed_bindings": removed,
            "restored_dropins": restored,
            "replacement_owner": (
                "independent_source_definition_plus_predecessor_phi_dropin"
                if restored else "independent_source_definition"
            ),
            "reason": reason,
        }
        marker = (
            receipt["source_sid"], receipt["target_sid"],
            str(receipt["target_name"]), receipt["pred_addr"],
            receipt["join_addr"], receipt["alias_owner"], stage,
        )
        existing = {
            (
                item.get("source_sid"), item.get("target_sid"),
                str(item.get("target_name")), item.get("pred_addr"),
                item.get("join_addr"), item.get("alias_owner"),
                item.get("stage"),
            )
            for item in self.vanquish_emperor_rejected_aliases_v30
        }
        if marker not in existing:
            self.vanquish_emperor_rejected_aliases_v30.append(receipt)
        return receipt

    def _erase_emperor_remove_alias_for_sid_v29(self, sid):
        """Compatibility wrapper using v30 transactional owner conservation."""
        removed = []
        for alias in self._vanquish_emperor_alias_records_for_sid_v30(sid):
            receipt = self._vanquish_emperor_reject_alias_transaction_v30(
                alias,
                reason="protected temporal value cannot retain state alias",
                stage="v29_compatibility_remove",
            )
            if receipt:
                removed.extend(receipt.get("removed_bindings", []) or [])
        return removed

    def _erase_emperor_independent_result_name_v29(self, sid):
        text = self._erase_emperor_sid_text_v29(sid)
        forbidden = self._vanquish_emperor_forbidden_state_names_v30(text)
        explicit = None
        for key in self._erase_emperor_sid_variants_v29(text):
            explicit = self.joint_consumer_result_projection_names.get(key)
            if explicit is None:
                explicit = self.joint_consumer_result_projection_names.get(
                    str(key)
                )
            if explicit:
                break
        if explicit and str(explicit) not in forbidden:
            return str(explicit)
        if explicit:
            self.vanquish_emperor_owner_warnings_v30.append({
                "kind": "vanquish_emperor_forbidden_result_projection_rejected_v30",
                "source_sid": text,
                "rejected_name": str(explicit),
                "forbidden_state_names": sorted(forbidden, key=str),
                "replacement": text,
            })

        current = self._erase_emperor_name_for_sid_v29(text)
        if current and str(current) not in forbidden:
            return str(current)
        return text

    def _consume_erase_emperor_snapshot_custody_v29(self, stage):
        contracts = self._refresh_erase_emperor_snapshot_inputs_v29()
        if not contracts:
            self.erase_emperor_snapshot_events_v29.append({
                "kind": "erase_emperor_snapshot_custody_inactive_v29",
                "version": self.erase_emperor_snapshot_version_v29,
                "stage": stage,
                "reason": "no_SemanticGraph_v35_or_SGL_v66_snapshot_contracts",
            })
            return 0

        protected = 0
        for snapshot_sid, rec in sorted(
            contracts.items(), key=lambda item: str(item[0])
        ):
            node = self._erase_emperor_node_for_sid_v29(snapshot_sid)
            if node is None:
                self.erase_emperor_snapshot_warnings_v29.append({
                    "kind": "erase_emperor_snapshot_formula_node_missing_v29",
                    "snapshot_sid": snapshot_sid,
                    "stage": stage,
                })
                continue
            actual_sid = self._erase_emperor_sid_text_v29(node)
            projection = str(
                rec.get("projection_name") or snapshot_sid
            )
            if actual_sid is None:
                actual_sid = snapshot_sid

            self.var_map[actual_sid] = projection
            self.protected_copy_temp_sids.add(actual_sid)
            self.materialize_sids.add(actual_sid)
            self.suppress_assign_sids.discard(actual_sid)
            self.inline_only_sids.discard(actual_sid)
            self.phi_source_foldable_sids.discard(actual_sid)
            self.copy_bridge_sids.discard(actual_sid)
            self.pure_bridge_sids.discard(actual_sid)
            self.prefer_var_expr_sids.add(actual_sid)
            self._erase_emperor_remove_alias_for_sid_v29(actual_sid)

            info = dict(self.protected_copy_temp_info.get(actual_sid, {}) or {})
            info.update({
                "kind": "erase_emperor_temporal_snapshot_v29",
                "version": self.erase_emperor_snapshot_version_v29,
                "source_sid": self._erase_emperor_sid_text_v29(
                    rec.get("source_sid")
                ),
                "snapshot_sid": actual_sid,
                "target_name": projection,
                "projection_name": projection,
                "capture_block_addr": rec.get("capture_block_addr"),
                "joint_consumers": list(rec.get("joint_consumers", []) or []),
                "reason": (
                    "COPY captures historical PHI/state epoch before a later "
                    "epoch is consumed beside it"
                ),
            })
            self.protected_copy_temp_info[actual_sid] = info

            self._set_ssa_policy(
                actual_sid,
                "erase_emperor_temporal_snapshot",
                emit=True,
                expr_mode="var",
                reason=info["reason"],
                target_name=projection,
            )
            try:
                node.no_inline = True
                node.materialize = True
                node.prefer_var_expr = True
                node.is_temporal_snapshot_v29 = True
                node.semantic_role = "temporal_state_epoch_snapshot"
                var = self.to_var(node)
                if var is not None:
                    var.no_inline = True
                    var.materialize = True
                    var.is_temporal_snapshot_v29 = True
                    var.snapshot_projection_name_v29 = projection
            except Exception:
                pass
            protected += 1
            self.erase_emperor_snapshot_events_v29.append({
                "kind": "erase_emperor_temporal_snapshot_protected_v29",
                "version": self.erase_emperor_snapshot_version_v29,
                "stage": stage,
                "snapshot_sid": actual_sid,
                "source_sid": info.get("source_sid"),
                "projection_name": projection,
                "capture_block_addr": info.get("capture_block_addr"),
            })

        # A joint consumer result is not a writeback to either operand state.
        # Give it independent execution custody before compute bindings are
        # generated, even if an older condition heuristic already aliased it.
        for result_sid in sorted(
            self.erase_emperor_derived_result_sids_v29, key=str
        ):
            node = self._erase_emperor_node_for_sid_v29(result_sid)
            if node is None:
                self.erase_emperor_snapshot_warnings_v29.append({
                    "kind": "erase_emperor_derived_formula_node_missing_v29",
                    "source_sid": result_sid,
                    "stage": stage,
                })
                continue
            name = self._erase_emperor_independent_result_name_v29(result_sid)
            self.var_map[result_sid] = name
            self.materialize_sids.add(result_sid)
            self.suppress_assign_sids.discard(result_sid)
            self.inline_only_sids.discard(result_sid)
            self.phi_source_foldable_sids.discard(result_sid)
            self.pure_bridge_sids.discard(result_sid)
            self.prefer_var_expr_sids.add(result_sid)
            self._set_ssa_policy(
                result_sid,
                "erase_emperor_snapshot_derived_value",
                emit=True,
                expr_mode="var",
                reason=(
                    "order-sensitive operation derives an independent value "
                    "from historical and later state epochs"
                ),
                target_name=name,
            )
            try:
                node.no_inline = True
                node.materialize = True
                node.prefer_var_expr = True
                node.is_snapshot_derived_value_v29 = True
                var = self.to_var(node)
                if var is not None:
                    var.no_inline = True
                    var.materialize = True
                    var.is_snapshot_derived_value_v29 = True
            except Exception:
                pass

        return protected

    def _vanquish_emperor_reconcile_alias_owners_v30(self, stage):
        self._refresh_erase_emperor_snapshot_inputs_v29()
        protected = sorted(self._vanquish_emperor_protected_sids_v30(), key=str)
        before = self._vanquish_emperor_alias_fingerprint_v30()
        if not self.vanquish_emperor_alias_fingerprint_before_v30:
            self.vanquish_emperor_alias_fingerprint_before_v30 = dict(before)

        transactions = []
        for sid in protected:
            aliases = self._vanquish_emperor_alias_records_for_sid_v30(sid)
            for alias in aliases:
                if self._erase_emperor_is_derived_result_sid_v29(sid):
                    self._record_erase_emperor_derived_alias_rejection_v29(
                        sid,
                        alias.get("target_sid"),
                        alias.get("owner"),
                        pred_addr=alias.get("pred_addr"),
                        join_addr=alias.get("join_addr"),
                        target_name=alias.get("target_name"),
                    )
                    reason = (
                        "snapshot-derived result remains an independent SSA "
                        "definition; PHI transition ownership is restored"
                    )
                else:
                    reason = (
                        "temporal snapshot remains an independent COPY "
                        "definition; PHI transition ownership is restored"
                    )
                receipt = self._vanquish_emperor_reject_alias_transaction_v30(
                    alias, reason=reason, stage=stage
                )
                if receipt:
                    transactions.append(receipt)

        # Reassert independent names and producer ownership after every legacy
        # alias/closure pass.  This is idempotent.
        for sid in sorted(self.erase_emperor_snapshot_sids_v29, key=str):
            info = self._erase_emperor_snapshot_info_for_sid_v29(sid)
            name = str(info.get("projection_name") or sid)
            node = self._erase_emperor_node_for_sid_v29(sid)
            rhs = self._vanquish_emperor_snapshot_copy_rhs_v30(node)
            self.var_map[sid] = name
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self.phi_source_foldable_sids.discard(sid)
            self.prefer_var_expr_sids.add(sid)
            self._set_ssa_policy(
                sid,
                "vanquish_emperor_temporal_snapshot",
                emit=True,
                expr_mode="var",
                reason="historical state epoch has one independent COPY owner",
                target_name=name,
            )
            self.vanquish_emperor_snapshot_owners_v30[sid] = {
                "kind": "vanquish_emperor_snapshot_owner_v30",
                "version": self.vanquish_emperor_version_v30,
                "snapshot_sid": sid,
                "source_sid": info.get("source_sid"),
                "producer_opcode": getattr(node, "opcode", None) if node else None,
                "producer_block_addr": self.block_addr(
                    self.block_of_semantic(node)
                ) if node is not None else None,
                "projection_name": name,
                "definition_rhs": rhs,
                "execution_owner": "independent_snapshot_copy_definition",
            }

        for sid in sorted(self.erase_emperor_derived_result_sids_v29, key=str):
            node = self._erase_emperor_node_for_sid_v29(sid)
            name = self._erase_emperor_independent_result_name_v29(sid)
            self.var_map[sid] = name
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self.phi_source_foldable_sids.discard(sid)
            self.prefer_var_expr_sids.add(sid)
            self.must_emit_state_write_sids.discard(sid)
            self.state_write_info.pop(sid, None)
            self._set_ssa_policy(
                sid,
                "vanquish_emperor_snapshot_derived_value",
                emit=True,
                expr_mode="var",
                reason=(
                    "order-sensitive result has one independent producer; "
                    "any PHI transition uses an explicit restored drop-in"
                ),
                target_name=name,
            )
            self.vanquish_emperor_derived_owners_v30[sid] = {
                "kind": "vanquish_emperor_derived_owner_v30",
                "version": self.vanquish_emperor_version_v30,
                "source_sid": sid,
                "producer_opcode": getattr(node, "opcode", None) if node else None,
                "producer_block_addr": self.block_addr(
                    self.block_of_semantic(node)
                ) if node is not None else None,
                "projection_name": name,
                "forbidden_state_sids": sorted(
                    self._vanquish_emperor_forbidden_state_sids_v30(sid), key=str
                ),
                "forbidden_state_names": sorted(
                    self._vanquish_emperor_forbidden_state_names_v30(sid), key=str
                ),
                "execution_owner": "independent_derived_definition",
            }

        after = self._vanquish_emperor_alias_fingerprint_v30()
        self.vanquish_emperor_alias_fingerprint_after_v30 = dict(after)
        protected_set = set(protected)
        # The exact mutation code is SID-scoped; this list is reserved for any
        # future proof that a non-protected source changed unexpectedly.
        self.vanquish_emperor_unrelated_alias_mutations_v30 = []
        event = {
            "kind": "vanquish_emperor_owner_reconciliation_v30",
            "version": self.vanquish_emperor_version_v30,
            "stage": stage,
            "protected_sids": protected,
            "transactions": len(transactions),
            "restored_dropins": len(self.vanquish_emperor_restored_dropins_v30),
            "unrelated_alias_mutations": 0,
            "rule": "reject_alias_and_restore_displaced_transition_atomically",
        }
        self.vanquish_emperor_owner_events_v30.append(event)
        return transactions

    def _scrub_erase_emperor_false_state_aliases_v29(self):
        """Compatibility entrypoint; v30 performs transactional reconciliation."""
        return self._vanquish_emperor_reconcile_alias_owners_v30(
            stage="v29_scrub_compatibility"
        )

    def _audit_erase_emperor_snapshot_custody_v29(self):
        contracts = self._refresh_erase_emperor_snapshot_inputs_v29()
        if not contracts:
            audit = {
                "kind": "erase_emperor_snapshot_custody_verified_v29",
                "version": self.erase_emperor_snapshot_version_v29,
                "active": False,
                "reason": "no_temporal_snapshot_contracts",
                "failures": [],
            }
            self.erase_emperor_snapshot_audit_v29 = audit
            self.erase_emperor_snapshot_events_v29.append(dict(audit))
            return audit

        failures = []
        checked_snapshots = []
        checked_results = []

        for sid, rec in sorted(contracts.items(), key=lambda item: str(item[0])):
            node = self._erase_emperor_node_for_sid_v29(sid)
            projection = str(rec.get("projection_name") or sid)
            policy = self.ssa_policy_by_sid.get(sid, {}) or {}
            item = {
                "snapshot_sid": sid,
                "projection_name": projection,
                "node_found": node is not None,
                "opcode": getattr(node, "opcode", None) if node is not None else None,
                "var_map_name": self.var_map.get(sid),
                "materialized": sid in self.materialize_sids,
                "suppressed": sid in self.suppress_assign_sids,
                "inline_only": sid in self.inline_only_sids,
                "phi_foldable": sid in self.phi_source_foldable_sids,
                "policy": dict(policy),
            }
            checked_snapshots.append(item)
            gates = {
                "copy_node_present": node is not None and getattr(node, "opcode", None) == "COPY",
                "projection_preserved": self.var_map.get(sid) == projection,
                "materialized": sid in self.materialize_sids,
                "not_suppressed": sid not in self.suppress_assign_sids,
                "not_inline_only": sid not in self.inline_only_sids,
                "not_phi_foldable": sid not in self.phi_source_foldable_sids,
                "policy_emits": policy.get("emit") is True,
                "policy_uses_var": policy.get("expr_mode") == "var",
                "not_state_alias": not any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.state_transition_alias_sids
                ),
            }
            failed = [name for name, value in gates.items() if not value]
            if failed:
                failures.append({
                    "kind": "erase_emperor_snapshot_gate_failure_v29",
                    "snapshot_sid": sid,
                    "failed_gates": failed,
                    "state": item,
                })

        for sid in sorted(self.erase_emperor_derived_result_sids_v29, key=str):
            info = self._erase_emperor_derived_info_for_sid_v29(sid)
            node = self._erase_emperor_node_for_sid_v29(sid)
            policy = self.ssa_policy_by_sid.get(sid, {}) or {}
            name = self.var_map.get(sid)
            forbidden = {
                self._erase_emperor_name_for_sid_v29(state_sid)
                for state_sid in list(info.get("source_sids", []) or [])
                + list(info.get("later_epoch_sids", []) or [])
                + list(info.get("snapshot_sids", []) or [])
            }
            forbidden.discard(None)
            item = {
                "source_sid": sid,
                "opcode": getattr(node, "opcode", None) if node is not None else None,
                "execution_name": name,
                "forbidden_state_names": sorted(forbidden, key=str),
                "materialized": sid in self.materialize_sids,
                "state_transition_alias": any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.state_transition_alias_sids
                ),
                "post_update_alias": any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.post_update_alias_sids
                ),
                "must_emit_state_write": any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.must_emit_state_write_sids
                ),
                "policy": dict(policy),
                "derived_info": info,
            }
            checked_results.append(item)
            gates = {
                "node_present": node is not None,
                "independent_name": bool(name) and str(name) not in forbidden,
                "materialized": sid in self.materialize_sids,
                "not_state_transition_alias": not any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.state_transition_alias_sids
                ),
                "not_post_update_alias": not any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.post_update_alias_sids
                ),
                "not_state_write": not any(
                    self._erase_emperor_sid_text_v29(value) == sid
                    for value in self.must_emit_state_write_sids
                ),
                "policy_emits": policy.get("emit") is True,
                "policy_uses_var": policy.get("expr_mode") == "var",
            }
            failed = [name for name, value in gates.items() if not value]
            if failed:
                failures.append({
                    "kind": "erase_emperor_derived_result_gate_failure_v29",
                    "source_sid": sid,
                    "failed_gates": failed,
                    "state": item,
                })

        audit = {
            "kind": (
                "erase_emperor_snapshot_custody_verified_v29"
                if not failures
                else "erase_emperor_snapshot_custody_failed_v29"
            ),
            "version": self.erase_emperor_snapshot_version_v29,
            "active": True,
            "semantic_contracts": len(contracts),
            "protected_snapshot_sids": sorted(
                self.erase_emperor_snapshot_sids_v29, key=str
            ),
            "derived_result_sids": sorted(
                self.erase_emperor_derived_result_sids_v29, key=str
            ),
            "rejected_state_alias_sids": sorted(
                self.erase_emperor_rejected_state_alias_sids_v29, key=str
            ),
            "checked_snapshots": checked_snapshots,
            "checked_results": checked_results,
            "failures": failures,
            "global_storage_renames": 0,
            "global_phi_family_renames": 0,
            "rule": (
                "materialize_exact_COPY_epoch_then_reject_joint_"
                "order_sensitive_result_as_state_successor"
            ),
        }
        self.erase_emperor_snapshot_audit_v29 = audit
        self.erase_emperor_snapshot_events_v29.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALPHIfolder v30 vanquish-emperor compatibility custody failed: %s"
                % failures
            )
        return audit

    def _audit_vanquish_emperor_owner_custody_v30(self):
        self._refresh_erase_emperor_snapshot_inputs_v29()
        protected = sorted(self._vanquish_emperor_protected_sids_v30(), key=str)
        if not protected:
            audit = {
                "kind": "vanquish_emperor_owner_custody_verified_v30",
                "version": self.vanquish_emperor_version_v30,
                "active": False,
                "reason": "no_temporal_snapshot_contracts",
                "failures": [],
            }
            self.vanquish_emperor_owner_audit_v30 = audit
            self.vanquish_emperor_owner_events_v30.append(dict(audit))
            return audit

        failures = []
        snapshot_checks = []
        derived_checks = []

        surviving_aliases = {
            sid: self._vanquish_emperor_alias_records_for_sid_v30(sid)
            for sid in protected
        }
        for sid, aliases in surviving_aliases.items():
            if aliases:
                failures.append({
                    "kind": "vanquish_emperor_forbidden_alias_survives_v30",
                    "source_sid": sid,
                    "aliases": aliases,
                })

        for sid in sorted(self.erase_emperor_snapshot_sids_v29, key=str):
            owner = dict(self.vanquish_emperor_snapshot_owners_v30.get(sid, {}) or {})
            node = self._erase_emperor_node_for_sid_v29(sid)
            lhs = self.var_map.get(sid)
            rhs = self._vanquish_emperor_snapshot_copy_rhs_v30(node)
            policy = self.ssa_policy_by_sid.get(sid, {}) or {}
            item = {
                "snapshot_sid": sid,
                "lhs": lhs,
                "rhs": rhs,
                "node_found": node is not None,
                "opcode": getattr(node, "opcode", None) if node else None,
                "materialized": sid in self.materialize_sids,
                "suppressed": sid in self.suppress_assign_sids,
                "inline_only": sid in self.inline_only_sids,
                "policy": dict(policy),
                "owner": owner,
            }
            snapshot_checks.append(item)
            gates = {
                "copy_definition_present": node is not None and getattr(node, "opcode", None) == "COPY",
                "one_independent_definition_owner": owner.get("execution_owner") == "independent_snapshot_copy_definition",
                "definition_rhs_present": bool(rhs),
                "definition_not_self_copy": bool(lhs) and bool(rhs) and str(lhs) != str(rhs),
                "materialized": sid in self.materialize_sids,
                "not_suppressed": sid not in self.suppress_assign_sids,
                "not_inline_only": sid not in self.inline_only_sids,
                "policy_emits": policy.get("emit") is True,
                "policy_uses_var": policy.get("expr_mode") == "var",
            }
            failed = [name for name, value in gates.items() if not value]
            if failed:
                failures.append({
                    "kind": "vanquish_emperor_snapshot_owner_gate_failure_v30",
                    "snapshot_sid": sid,
                    "failed_gates": failed,
                    "state": item,
                })

        for sid in sorted(self.erase_emperor_derived_result_sids_v29, key=str):
            owner = dict(self.vanquish_emperor_derived_owners_v30.get(sid, {}) or {})
            node = self._erase_emperor_node_for_sid_v29(sid)
            name = self.var_map.get(sid)
            forbidden = self._vanquish_emperor_forbidden_state_names_v30(sid)
            policy = self.ssa_policy_by_sid.get(sid, {}) or {}
            item = {
                "source_sid": sid,
                "execution_name": name,
                "forbidden_state_names": sorted(forbidden, key=str),
                "node_found": node is not None,
                "opcode": getattr(node, "opcode", None) if node else None,
                "materialized": sid in self.materialize_sids,
                "policy": dict(policy),
                "owner": owner,
            }
            derived_checks.append(item)
            gates = {
                "producer_present": node is not None,
                "one_independent_definition_owner": owner.get("execution_owner") == "independent_derived_definition",
                "independent_name": bool(name) and str(name) not in forbidden,
                "materialized": sid in self.materialize_sids,
                "not_suppressed": sid not in self.suppress_assign_sids,
                "not_inline_only": sid not in self.inline_only_sids,
                "not_state_write": sid not in self.must_emit_state_write_sids,
                "policy_emits": policy.get("emit") is True,
                "policy_uses_var": policy.get("expr_mode") == "var",
            }
            failed = [name for name, value in gates.items() if not value]
            if failed:
                failures.append({
                    "kind": "vanquish_emperor_derived_owner_gate_failure_v30",
                    "source_sid": sid,
                    "failed_gates": failed,
                    "state": item,
                })

        replacement_failures = []
        for rec in self.vanquish_emperor_rejected_aliases_v30:
            restored = list(rec.get("restored_dropins", []) or [])
            removed = list(rec.get("removed_bindings", []) or [])
            if removed and rec.get("replacement_owner") not in (
                "independent_source_definition",
                "independent_source_definition_plus_predecessor_phi_dropin",
            ):
                replacement_failures.append(rec)
            for dropin in restored:
                rid = dropin.get("id")
                if rid not in self.required_phi_dropin_ids or rid not in self.non_suppressible_dropin_ids:
                    replacement_failures.append({
                        "receipt": rec,
                        "dropin": dropin,
                        "reason": "restored_dropin_not_required_and_non_suppressible",
                    })
        if replacement_failures:
            failures.append({
                "kind": "vanquish_emperor_removed_alias_without_replacement_owner_v30",
                "records": replacement_failures,
            })

        if self.vanquish_emperor_unrelated_alias_mutations_v30:
            failures.append({
                "kind": "vanquish_emperor_unrelated_alias_mutation_v30",
                "mutations": list(self.vanquish_emperor_unrelated_alias_mutations_v30),
            })

        audit = {
            "kind": (
                "vanquish_emperor_owner_custody_verified_v30"
                if not failures
                else "vanquish_emperor_owner_custody_failed_v30"
            ),
            "version": self.vanquish_emperor_version_v30,
            "active": True,
            "protected_sids": protected,
            "snapshot_owners": snapshot_checks,
            "derived_owners": derived_checks,
            "aliases_removed": sum(
                len(rec.get("removed_bindings", []) or [])
                for rec in self.vanquish_emperor_rejected_aliases_v30
            ),
            "dropins_restored": len(self.vanquish_emperor_restored_dropins_v30),
            "unrelated_alias_mutations": list(
                self.vanquish_emperor_unrelated_alias_mutations_v30
            ),
            "surviving_aliases": surviving_aliases,
            "failures": failures,
            "rule": "every_alias_rejection_conserves_one_executable_transition_owner",
        }
        self.vanquish_emperor_owner_audit_v30 = audit
        self.vanquish_emperor_owner_events_v30.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALPHIfolder v30 vanquish-emperor owner custody failed: %s"
                % failures
            )
        return audit

    # ---------------------------------------------------------
    # Presentation metadata
    # ---------------------------------------------------------

    def _set_ssa_policy(self, sid, cls, emit=False, expr_mode="inline", reason=None, target_name=None):
        if sid is None:
            return

        self.presentation_class_by_sid[sid] = cls
        self.ssa_policy_by_sid[sid] = {
            "class": cls,
            "emit": bool(emit),
            "expr_mode": expr_mode,
            "reason": reason,
            "target_name": target_name,
        }

    def _is_protected_materialized_sid(self, sid):
        if sid is None:
            return False

        if sid in self.local_target_sids:
            return True

        if sid in self.used_temp_phi_target_sids:
            return True

        if sid in self.used_temp_phi_output_sids:
            return True

        if sid in self.temp_phi_source_alias_sids:
            return True

        if sid in self.phi_source_alias_sids:
            return True

        if sid in self.protected_copy_temp_sids:
            return True

        if sid in self.distinct_ssa_snapshot_sids:
            return True

        if self._erase_emperor_is_snapshot_sid_v29(sid):
            return True

        if self._erase_emperor_is_derived_result_sid_v29(sid):
            return True

        if self._projection_sid_is_protected_v28(sid):
            return True

        if sid in self.must_emit_state_write_sids:
            return True

        if sid in self.real_local_copy_sids:
            return True

        if sid in self.required_call_result_sids:
            return True

        if sid in self.protected_condition_value_sids:
            return True

        if sid in self.executable_dropin_source_sids:
            return True

        if sid in self.condition_temp_def_sids:
            return True

        return False

    def _classify_transparent_bridge(self, sid, node):
        opcode = getattr(node, "opcode", None)
        if opcode not in self.TRANSPARENT_OPS:
            return False

        if self._erase_emperor_is_snapshot_sid_v29(sid):
            info = self._erase_emperor_snapshot_info_for_sid_v29(sid)
            projection = info.get("projection_name") or self.var_map.get(sid)
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self.phi_source_foldable_sids.discard(sid)
            self.copy_bridge_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "erase_emperor_temporal_snapshot",
                emit=True,
                expr_mode="var",
                reason=(
                    "COPY captures a historical PHI/state epoch that remains "
                    "live beside a later epoch"
                ),
                target_name=projection,
            )
            return True

        if sid in self.protected_condition_value_sids:
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "protected_condition_value",
                emit=True,
                expr_mode="var",
                reason="condition dependency value is protected from bridge suppression",
                target_name=self.var_map.get(sid),
            )
            return True

        if sid in self.real_local_copy_sids:
            info = self.real_local_copy_info.get(sid, {})
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "real_local_copy",
                emit=True,
                expr_mode="var",
                reason=info.get("reason", "real local copy state write"),
                target_name=info.get("target_name") or self.var_map.get(sid),
            )
            return True

        if sid in self.protected_copy_temp_sids:
            self.materialize_sids.add(sid)
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "protected_snapshot_copy",
                emit=True,
                expr_mode="var",
                reason="snapshot copy required for local swap/state preservation",
                target_name=self.var_map.get(sid),
            )
            return True

        inputs = list(getattr(node, "inputs", []) or [])
        if not inputs:
            return False

        # COPY/CAST/ZEXT/SEXT/TRUNC are presentation bridges unless the SID is
        # protected as a PHI target or materialized semantic value. This removes
        # artifacts like:
        #     v_6644 = v_2704
        #     v_4880 = local_2c
        #     v_4949 = local_28
        self.inline_only_sids.add(sid)
        self.suppress_assign_sids.add(sid)
        self.copy_bridge_sids.add(sid)
        self._set_ssa_policy(
            sid,
            "transparent_bridge",
            emit=False,
            expr_mode="inline",
            reason="transparent op %s" % opcode,
        )
        return True

    def _classify_pure_bridge(self, sid, node):
        opcode = getattr(node, "opcode", None)
        if opcode not in self.PURE_INLINE_OPS:
            return False

        if sid in self.protected_condition_value_sids and sid in self.materialize_sids:
            self.suppress_assign_sids.discard(sid)
            self.inline_only_sids.discard(sid)
            self._set_ssa_policy(
                sid,
                "protected_condition_value",
                emit=True,
                expr_mode="var",
                reason="condition dependency value remains materialized",
                target_name=self.var_map.get(sid),
            )
            return True

        if opcode in self.TRANSPARENT_OPS:
            return False

        uses = self.use_counts.get(sid, 0)

        # Conditions are never standalone assignments in PAL presentation.
        if self.is_condition(node):
            self.suppress_assign_sids.add(sid)
            self.inline_only_sids.add(sid)
            self.compare_bridge_sids.add(sid)
            self._set_ssa_policy(
                sid,
                "compare_bridge",
                emit=False,
                expr_mode="inline",
                reason="condition compare bridge",
            )
            return True

        # SUBPIECE is helper-like, but if it is a one-use bridge inside a
        # larger condition, suppress the standalone assignment. In POW mode we
        # can later choose to materialize helper primitives instead.
        if opcode == "SUBPIECE" and uses <= 1:
            self.suppress_assign_sids.add(sid)
            self.inline_only_sids.add(sid)
            self.pure_bridge_sids.add(sid)
            self._set_ssa_policy(
                sid,
                "helper_inline_bridge",
                emit=False,
                expr_mode="inline",
                reason="one-use SUBPIECE helper bridge",
            )
            return True

        # One-use pure arithmetic/bitwise bridge: inline and suppress.
        if uses <= 1:
            self.inline_only_sids.add(sid)
            self.suppress_assign_sids.add(sid)
            self.pure_bridge_sids.add(sid)
            self._set_ssa_policy(
                sid,
                "pure_inline_bridge",
                emit=False,
                expr_mode="inline",
                reason="one-use pure op %s" % opcode,
            )
            return True

        # Repeated pure expressions can remain materialized for execution
        # fidelity / avoiding recomputation. Do not suppress by default.
        self._set_ssa_policy(
            sid,
            "repeated_pure_expr",
            emit=True,
            expr_mode="var",
            reason="repeated pure op %s uses=%s" % (opcode, uses),
        )
        return True


    def _build_presentation_metadata(self):
        """
        Build layer-owned presentation policy for formula SIDs.

        This is the cleanup pass that prevents emitter lock-in:
          - SSA ghosts are marked suppress/inline here.
          - semantic values stay materialized here.
          - PHI selector sources keep their aliased target names here.
        """

        for sid, node in self.nodes.items():
            opcode = getattr(node, "opcode", None)

            # Calls are materialized by _mark_materialization_policy unless
            # they are explicitly PHI-foldable/selector-aliased. Do not mark
            # them as ghosts here.
            if opcode in self.CALL_OPS:
                if sid in self.required_call_result_sids:
                    self.suppress_assign_sids.discard(sid)
                    self.inline_only_sids.discard(sid)
                    self.materialize_sids.add(sid)
                    self._set_ssa_policy(
                        sid,
                        "required_condition_call_result",
                        emit=True,
                        expr_mode="var",
                        reason="call result feeds condition dependency",
                        target_name=self.var_map.get(sid),
                    )
                elif sid in self.temp_phi_source_alias_sids or sid in self.phi_source_alias_sids:
                    self.suppress_assign_sids.discard(sid)
                    self.inline_only_sids.discard(sid)
                    self.materialize_sids.add(sid)
                    self._set_ssa_policy(
                        sid,
                        "phi_source_call_alias",
                        emit=True,
                        expr_mode="var",
                        reason="call source renamed to PHI target",
                        target_name=self.var_map.get(sid),
                    )
                else:
                    self._set_ssa_policy(
                        sid,
                        "materialized_call",
                        emit=True,
                        expr_mode="var",
                        reason="call result",
                    )
                continue

            # State writes are executable statements, not bridge artifacts.
            if sid in self.must_emit_state_write_sids:
                self.suppress_assign_sids.discard(sid)
                self.inline_only_sids.discard(sid)
                self.materialize_sids.add(sid)

                existing = self.ssa_policy_by_sid.get(sid, {})
                cls = existing.get("class") or "must_emit_state_write"
                reason = existing.get("reason") or self.state_write_info.get(sid, {}).get("reason") or "state write"

                self._set_ssa_policy(
                    sid,
                    cls,
                    emit=True,
                    expr_mode="var",
                    reason=reason,
                    target_name=self.var_map.get(sid) or self.state_write_info.get(sid, {}).get("target_name"),
                )
                continue

            # PHI targets, including used temp PHI outputs such as v_5848,
            # are real semantic values and must not be suppressed.
            if self._is_protected_materialized_sid(sid):
                self.suppress_assign_sids.discard(sid)
                self.inline_only_sids.discard(sid)
                self.materialize_sids.add(sid)
                self._set_ssa_policy(
                    sid,
                    "protected_phi_or_local_target",
                    emit=True,
                    expr_mode="var",
                    reason="PHI/local target",
                    target_name=self.var_map.get(sid),
                )
                continue

            if self._classify_transparent_bridge(sid, node):
                continue

            if self._classify_pure_bridge(sid, node):
                continue

            # Default: leave visible only if it was explicitly materialized
            # elsewhere. Otherwise avoid inventing suppression not backed by
            # policy.
            if sid in self.materialize_sids:
                self._set_ssa_policy(
                    sid,
                    "materialized_value",
                    emit=True,
                    expr_mode="var",
                    reason="pre-marked materialized sid",
                )
            else:
                self._set_ssa_policy(
                    sid,
                    "unclassified_visible",
                    emit=True,
                    expr_mode="var",
                    reason="no suppression rule matched",
                )

        for rec in self.phi_dropins:
            sid = rec.get("source_sid")
            node = rec.get("source_node")
            if sid is not None and node is not None:
                mode = "formula"
                if sid in self.materialize_sids:
                    mode = "var"
                if sid in self.phi_source_foldable_sids:
                    mode = "formula"
                if (
                    sid in self.temp_phi_source_alias_sids
                    or sid in self.phi_source_alias_sids
                    or sid in self.state_transition_alias_sids
                    or sid in self.prefer_var_expr_sids
                    or sid in self.post_update_alias_sids
                ):
                    mode = "var"

                self.preferred_expr_by_sid[sid] = {
                    "mode": mode,
                    "target_sid": rec.get("target_sid"),
                    "target_name": rec.get("target_name"),
                    "post_update_alias": sid in self.post_update_alias_sids,
                }

        # v19: consumer compare nodes of post-update aliases must also prefer
        # variable-form rendering, so higher layers do not reconstruct stale
        # pre-update expressions such as local_14 + 1 after local_14 += 1.
        for sid in self.post_update_consumer_sids:
            info = self.post_update_consumer_aliases.get(sid, {})
            self.preferred_expr_by_sid.setdefault(sid, {})
            self.preferred_expr_by_sid[sid].update({
                "mode": "formula_with_var_inputs",
                "post_update_consumer": True,
                "source_sid": info.get("source_sid"),
                "target_name": info.get("target_name"),
            })

